  "Ez a telepítés több részből áll, ezért nem menthető egyetlen fájlba.": "Esta instalación consta de varias partes, por lo que no se puede guardar en un solo archivo.",
  "Egy mentés vagy betöltés már folyamatban van.": "Ya hay un guardado o una carga en curso.",
