  "Bibliai hangfelvételek": "Grabaciones de la Biblia",
  "Zenék és imahangok": "Música y sonidos de oración",
  "Alkalmazás mentése fájlba": "Guardar la aplicación en un archivo",
  "Az alkalmazást egyetlen fájlba mentheted, és internet nélkül telepítheted egy másik Android telefonra. A saját adataid nincsenek benne: azokat a Teljes mentés viszi át, titkosítva.": "Puedes guardar la aplicación en un solo archivo e instalarla sin internet en otro teléfono Android. Tus propios datos no están incluidos: los traslada la Copia de seguridad completa, cifrada.",
  "Letöltött tartalom": "Contenido descargado",
  "A letöltött tartalmat külön fájlba mentheted, így a másik telefonnak nem kell újra letöltenie.": "Puedes guardar el contenido descargado en un archivo aparte, para que el otro teléfono no tenga que descargarlo de nuevo.",
  "Tartalom mentése fájlba": "Guardar contenido en un archivo",
  "Ezen a telefonon még nincs letöltött tartalom.": "En este teléfono todavía no hay contenido descargado.",
  "Tartalom betöltése fájlból": "Cargar contenido desde un archivo",
  "Hogyan telepítsem a másik telefonra?": "¿Cómo la instalo en el otro teléfono?",
  "Másold át a fájlokat a másik telefonra: SD-kártyán, USB-kábellel, pendrive-on vagy Bluetooth-on.": "Copia los archivos al otro teléfono: en una tarjeta SD, con un cable USB, en una memoria USB o por Bluetooth.",
  "A másik telefonon nyisd meg az .apk fájlt a Fájlok alkalmazásban, és koppints a Telepítés gombra. Ha a telefon kéri, egyszer engedélyezd az „Ismeretlen alkalmazások telepítése” beállítást annak az alkalmazásnak, amellyel a fájlt megnyitottad.": "En el otro teléfono, abre el archivo .apk en la aplicación Archivos y toca Instalar. Si el teléfono lo pide, permite una vez «Instalar aplicaciones desconocidas» para la aplicación con la que abriste el archivo.",
  "Indítsd el az alkalmazást, nyisd meg a Beállítások, Adatok és mentés részt, koppints a „Tartalom betöltése fájlból” gombra, és válaszd ki a .pptartalom fájlt.": "Inicia la aplicación, abre Ajustes, Datos y copia de seguridad, toca «Cargar contenido desde un archivo» y elige el archivo .pptartalom.",
  "Végül a saját adataidat a Teljes mentés fájljából töltsd vissza a Visszatöltés gombbal, a mentési kulcsoddal.": "Por último, restaura tus propios datos desde el archivo de la Copia de seguridad completa con el botón Restaurar y tu clave de copia.",
