  "Nyilvános béta tudnivalók": "Beta pública: lo que debes saber",
  // ===== 2026-11-02 Gerah escrow + weekly goal (owner TG 33434/33435, decision A TG 1322, card 8ed3c59e; the daily item is the signed wording) =====
  "Napi Bibliaolvasás, heti céllal. Minden nap, amikor eléred a napra beállított olvasási célodat, Gerah kerül letétbe a cél hossza szerint: legalább 10 perces cél után 1, legalább 20 perces után 2, legalább 30 perces után 3; az 5 perces cél után nem jár. Naponta legfeljebb 3 gerah. A letét akkor kerül a tárcádba, ha 7 egymást követő napon eléred a napi célodat. Ha egy nap kimarad, a letét elvész, és a hét nap elölről indul. A Gerah-t a PrepperPapa alkalmazás tárcája tárolja: a Wordlightban végzett olvasásért akkor jár, ha nálad telepítve van a PrepperPapa alkalmazás. A reggeli ébresztős felolvasás is beleszámít.": "Lectura diaria de la Biblia, con objetivo semanal. Cada día en que alcances el objetivo de lectura que fijaste para ese día, se deposita Gerah según la duración del objetivo: 1 por un objetivo de al menos 10 minutos, 2 por al menos 20 minutos, 3 por al menos 30 minutos; un objetivo de 5 minutos no da ninguna. Como máximo 3 gerah al día. El depósito pasa a tu cartera cuando alcanzas tu objetivo diario 7 días seguidos. Si te saltas un día, el depósito se pierde y los 7 días empiezan de nuevo. La Gerah se guarda en la cartera de la app PrepperPapa: por la lectura en Wordlight la recibes solo si tienes instalada la app PrepperPapa. La lectura del despertador de la mañana también cuenta.",
  "Napi Bibliaolvasás, heti céllal: minden nap, amikor eléred a napra beállított olvasási célodat (legalább {p} perc), 1 gerah kerül letétbe. A letét akkor kerül a tárcádba, ha {h} egymást követő napon eléred a napi célodat; ha egy nap kimarad, a letét elvész, és a {h} nap elölről indul. A reggeli ébresztős felolvasás is beleszámít.": "Lectura diaria de la Biblia, con objetivo semanal: cada día en que alcances el objetivo de lectura que fijaste para ese día (al menos {p} minutos), se deposita 1 gerah. El depósito pasa a tu cartera cuando alcanzas tu objetivo diario {h} días seguidos; si te saltas un día, el depósito se pierde y los {h} días empiezan de nuevo. La lectura del despertador de la mañana también cuenta.",
  "Ma {n} gerah-t letétbe helyeztünk. Heti cél: {k} / {h} nap.": "Hoy se han depositado {n} gerah. Objetivo semanal: {k} / {h} días.",
  "Heti cél teljesítve: {n} gerah a tárcádba került!": "Objetivo semanal alcanzado: ¡{n} gerah han pasado a tu cartera!",
  "heti bibliaolvasási cél": "objetivo semanal de lectura de la Biblia",
  "Heti cél · Gerah-letét": "Objetivo semanal · depósito de Gerah",
  "Letétben: {n} gerah": "En depósito: {n} gerah",
  "{k} / {h} nap egymás után": "{k} / {h} días seguidos",
  "A {h}. egymást követő olvasott nap után a letét a tárcádba kerül.": "Tras el {h}.º día de lectura seguido, el depósito pasa a tu cartera.",
  "Kimaradt egy nap: ez a letét elvész. A következő olvasott nappal a {h} nap elölről indul.": "Te saltaste un día: este depósito se pierde. Con tu próximo día de lectura los {h} días empiezan de nuevo.",
  "Gerah letétben": "Gerah en depósito",
  "letét": "depósito",
