  "A készülék készít egy kulcspárt. A titkos kulcs csak a titkosított mentésbe kerül bele. Ezzel írod alá a fizetéseidet, és ezért nem tud más a nevedben fizetni.": "El dispositivo crea un par de claves. La clave secreta solo se guarda en la copia de seguridad cifrada. Con ella firmas tus pagos, y por eso nadie más puede pagar en tu nombre.",
