 "Több hely is illik erre: „{cel}”. Melyikre gondolsz? Koppints rá, vagy írd meg pontosabban.": "Varios lugares coinciden con «{cel}». ¿Cuál quieres decir? Tócalo o escríbelo con más precisión.",
