  "Írd fel, amiért imádkozol, és jelöld meg, amikor választ kapsz. Csak ezen a készüléken tárolódik.": "Anota por qué oras y márcalo cuando recibas respuesta. Se guarda solo en este dispositivo.",
  "Imatéma hozzáadása": "Añadir motivo de oración",
