  "Hét rövid vezetett ima, a hét minden napjára egy. Mindegyik hálaadással kezdődik, és csenddel zárul.": "Siete oraciones guiadas breves, una para cada día de la semana. Cada una empieza con gratitud y termina en silencio.",
