  "Megválaszolva": "Respondida",
  "Vissza az imalistára": "Volver a la lista de oración",
  "Ezt a helyet nem találom a Bibliában. Szövegként megmarad.": "No encuentro este pasaje en la Biblia. Se guarda como texto.",
