 "Amikor nem tudsz aludni": "Cuando no puedes dormir",
 "Amikor beteg vagy, vagy fájdalmad van": "Cuando estás enfermo o tienes dolor",
 "Amikor bűntudat nyom": "Cuando te pesa la culpa",
 "Amikor haragszol, vagy megbántottak": "Cuando estás enojado o te han herido",
 "Amikor bátorság kell": "Cuando necesitas valor",
 "Amikor menekülnöd kell, vagy úton vagy": "Cuando tienes que huir o estás de camino",
