 "Amikor a gyermekeidért aggódsz": "Cuando te preocupan tus hijos",
 "Amikor reménytelennek látszik minden": "Cuando todo parece sin esperanza",
 "Amikor gyász ér": "Cuando estás de duelo",
 "Amikor a halál gondolata félelemmel tölt el": "Cuando la idea de la muerte te llena de miedo",
