// ===== 2026-11-01 prayer room: the 4-week cycle of 28 guided prayers + "Imádság a világért" (text: Énok; owner TG 32765-32783) =====
Object.assign(window.PP_FORD_SZOTAR.es, {
  "Imádság a világért": "Oración por el mundo",
  "Mind a 28 vezetett ima": "Las 28 oraciones guiadas",
  "{n}. hét": "Semana {n}",
  "Ezen a héten": "Esta semana",
  "Négy hét, minden napra egy rövid vezetett ima, a kör négyhetente ismétlődik. Mindegyik hálaadással kezdődik, és csenddel zárul.": "Cuatro semanas, una breve oración guiada para cada día; el ciclo se repite cada cuatro semanas. Cada una empieza con gratitud y termina en silencio.",
  "Megnyitás a térképen": "Abrir en el mapa",
  "A térkép világhelyzet-adatából, frissítve {kor}.": "Según los datos de la situación mundial del mapa, actualizados {kor}.",
  "Köszönd meg a hetet, ami mögötted van. Nevezz meg három konkrét dolgot, amiért hálás vagy.": "Da gracias por la semana que dejas atrás. Nombra tres cosas concretas por las que estás agradecido.",
  "Uram, köszönöm a mögöttem lévő hetet, a jót is és azt is, amit még nem értek. Köszönöm, hogy nem engedted el a kezemet. Hálás vagyok azért a három dologért, amit most eléd hozok.": "Señor, te doy gracias por la semana que dejo atrás, por lo bueno y también por lo que todavía no entiendo. Gracias por no soltar mi mano. Estoy agradecido por las tres cosas que ahora traigo delante de ti.",
  "Uram, voltak napok, amikor nélküled indultam, és nélküled döntöttem. Nem mentegetem magam, hanem eléd teszem. Köszönöm, hogy Jézusért megbocsátasz, és tisztán állhatok előtted.": "Señor, hubo días en que salí sin ti y decidí sin ti. No me excuso, sino que lo pongo delante de ti. Gracias porque me perdonas por amor de Jesús, y puedo estar limpio delante de ti.",
  "Uram, te mondod: csendesedjetek. Elcsendesedek, és elismerem, hogy te vagy az Isten, nem én. Te vagy az, aki a zaj fölött is úr marad.": "Señor, tú dices: estad quietos. Me quedo quieto y reconozco que tú eres Dios, no yo. Tú eres quien sigue siendo Señor por encima de todo el ruido.",
  "Uram, eléd teszem a jövő hetet: a munkámat, a családomat és a döntéseket, amik várnak rám. Nem kérem, hogy minden könnyű legyen, azt kérem, hogy te vezess benne. Add, hogy felismerjem a hangodat, amikor szólsz.": "Señor, pongo delante de ti la semana que viene: mi trabajo, mi familia y las decisiones que me esperan. No te pido que todo sea fácil; te pido que tú me guíes en ella. Ayúdame a reconocer tu voz cuando hablas.",
  "Uram, itt vagyok. Nem mondok többet, csak előtted maradok.": "Señor, aquí estoy. No digo nada más; solo me quedo delante de ti.",
  "Uram, mielőtt bármit kérnék, köszönöm, amit már adtál. Köszönöm az otthonomat, az erőmet és azokat az embereket, akik mellettem állnak. Nem magától értetődő, ajándék.": "Señor, antes de pedirte nada, te doy gracias por lo que ya me has dado. Gracias por mi hogar, por mis fuerzas y por las personas que están a mi lado. No es algo que se dé por sentado; es un regalo.",
  "Uram, voltak gondok, amiket úgy cipeltem, mintha te nem látnád. Bocsásd meg, hogy a félelmemnek jobban hittem, mint neked. Most leteszem őket a kezedbe.": "Señor, hubo preocupaciones que cargué como si tú no las vieras. Perdóname por haber creído más a mi miedo que a ti. Ahora las dejo en tus manos.",
  "Uram, te nem azt mondod, hogy ne legyenek gondjaim, hanem hogy hozzam őket eléd. Imádsággal, kéréssel és hálával jövök, ahogy mondtad. Te békességet ígérsz, nem magyarázatot, és ez nekem elég.": "Señor, tú no me dices que no tenga preocupaciones, sino que las traiga delante de ti. Vengo con oración, con peticiones y con gratitud, como tú dijiste. Tú prometes paz, no una explicación, y eso me basta.",
  "Uram, egyenként hozom eléd, ami ma a vállamon van. Mindegyiket rád bízom, nem azért, mert kicsik, hanem mert te nagy vagy. Őrizd meg a szívemet és a gondolataimat a Krisztus Jézusban.": "Señor, una por una traigo delante de ti las cargas que hoy llevo sobre los hombros. Te las confío todas, no porque sean pequeñas, sino porque tú eres grande. Guarda mi corazón y mis pensamientos en Cristo Jesús.",
  "Uram, ami még bennem maradt, azt is tudod. Átadom szavak nélkül is.": "Señor, tú conoces también lo que aún queda en mí. Te lo entrego, aunque sea sin palabras.",
  "Uram, köszönöm, hogy nem azt kapom, amit megérdemlek, hanem kegyelmet. Köszönöm, hogy Jézus már megfizetett azért, amit én nem tudtam volna. Ezért jöhetek most eléd félelem nélkül.": "Señor, gracias porque no recibo lo que merezco, sino gracia. Gracias porque Jesús ya pagó lo que yo nunca habría podido pagar. Por eso puedo venir ahora delante de ti sin miedo.",
  "Uram, mutasd meg, mi az, amit rendbe kell tennem. Néven nevezem előtted, nem szépítem és nem magyarázom. Te hű és igaz vagy: megbocsátasz, és megtisztítasz minden hamisságtól.": "Señor, muéstrame lo que debo poner en orden. Lo llamo por su nombre delante de ti; no lo adorno ni lo justifico. Tú eres fiel y justo: me perdonas y me limpias de toda maldad.",
  "Uram, a te szavad azt mondja: ha megvallom, megbocsátod. Nem a jó érzésemre építek, hanem a te hűségedre. Elfogadom, hogy ami megvallva van, az el is van rendezve.": "Señor, tu palabra dice: si confieso, tú perdonas. No me apoyo en lo que siento, sino en tu fidelidad. Acepto que lo que he confesado ya está arreglado.",
  "Uram, adj erőt, hogy ahol embertől kell bocsánatot kérnem, megtegyem. És adj szívet, hogy annak is megbocsássak, aki engem bántott. Tedd rendbe, amit én már nem tudok.": "Señor, dame fuerza para pedir perdón a quien deba pedírselo. Y dame un corazón para perdonar también a quien me hizo daño. Arregla tú lo que yo ya no puedo arreglar.",
  "Uram, tiszta lappal indulok. Köszönöm.": "Señor, empiezo de nuevo, con borrón y cuenta nueva. Gracias.",
  "Uram, köszönöm a mai napot, a reggelt, az ételt az asztalon, a tetőt a fejem fölött. Köszönöm a kicsiket is, amiket észre sem veszek. Mindegyik tőled jött.": "Señor, gracias por el día de hoy, por la mañana, por la comida en la mesa, por el techo sobre mi cabeza. Gracias también por las cosas pequeñas que ni siquiera noto. Todas vinieron de ti.",
  "Uram, tudom, mi került az első helyre nálam az utóbbi időben, és az nem te voltál. Megvallom, hogy a figyelmemet és az időmet máshová adtam. Bocsáss meg, és segíts újra sorba rakni.": "Señor, sé qué ha ocupado el primer lugar en mi vida últimamente, y no has sido tú. Confieso que he dado mi atención y mi tiempo a otras cosas. Perdóname y ayúdame a volver a poner las cosas en orden.",
  "Uram, te azt mondod: először az országodat és az igazságodat keressem. Nem arra kérsz, hogy ne dolgozzak, hanem hogy ne a gond vezessen. Segíts úgy élni, mintha hinném, hogy te viselsz rám gondot, mert hiszem.": "Señor, tú me dices que busque primero tu reino y tu justicia. No me pides que no trabaje, sino que no sea la preocupación la que me guíe. Ayúdame a vivir como quien cree que tú cuidas de mí, porque lo creo.",
  "Uram, rakd rendbe a mai napom sorrendjét: te legyél az első, és minden más a helyére kerüljön. És eléd hozom a szükségleteimet is, mert te mondtad, hogy hozzam. Add meg, ami kell, és adj hálás szívet ahhoz, amit adsz.": "Señor, ordena mi día de hoy: que tú seas el primero y que todo lo demás encuentre su lugar. Y te traigo también mis necesidades, porque tú me dijiste que te las trajera. Dame lo que necesito, y dame un corazón agradecido por lo que me das.",
  "Uram, a nap többi része a tiéd. Járj velem benne.": "Señor, el resto del día es tuyo. Camina conmigo en él.",
  "Uram, köszönöm, hogy nem kell bejelentkeznem hozzád, és nem kell érdemet hoznom. Jézus miatt nyitva az út, és te nem fordulsz el. Köszönöm, hogy a trónod kegyelem trónja.": "Señor, gracias porque no necesito pedir cita para venir a ti, ni tengo que traer méritos. Por Jesús el camino está abierto, y tú no te apartas. Gracias porque tu trono es un trono de gracia.",
  "Uram, amiben elbuktam, azt nem rejtem el előled. A szégyen azt mondja, hogy maradjak távol, de te azt mondod, hogy jöjjek közel. Jövök, és kérem az irgalmadat.": "Señor, no te escondo en qué he fallado. La vergüenza me dice que me quede lejos, pero tú me dices que me acerque. Vengo, y te pido tu misericordia.",
  "Uram, te bizalommal hívsz, nem rettegéssel. Jézus tudja, milyen embernek lenni, ezért értesz engem. Alkalmas időben segítesz, és ez az idő most van.": "Señor, tú me llamas a venir con confianza, no con temor. Jesús sabe lo que es ser humano, y por eso me comprendes. Tú ayudas en el momento oportuno, y ese momento es ahora.",
  "Uram, most nem magamért jövök, hanem másokért. Eléd hozom a családomat, név szerint, és a barátaimat. És eléd hozom azt az embert, akiről tudom, hogy most nehéz helyzetben van: légy közel hozzá, adj neki erőt és reményt, és használj engem, ha kell.": "Señor, ahora no vengo por mí, sino por otros. Te traigo a mi familia, por su nombre, y a mis amigos. Y te traigo a esa persona que sé que ahora pasa por un momento difícil: acércate a ella, dale fuerza y esperanza, y úsame si hace falta.",
  "Uram, itt maradok előtted. Elég, hogy te itt vagy.": "Señor, me quedo aquí delante de ti. Me basta con que tú estés aquí.",
  "Uram, ma a hálával kezdem, és nem sietek vele. Végigmegyek a héten, és köszönöm a jó pillanatokat egyiket a másik után: egy beszélgetést, egy elvégzett munkát, egy nyugodt estét. Te voltál mindegyikben, akkor is, ha nem vettem észre.": "Señor, hoy empiezo con gratitud, y no me apresuro. Repaso la semana y te doy gracias por los buenos momentos, uno tras otro: una conversación, un trabajo terminado, una tarde tranquila. Tú estabas en cada uno de ellos, aunque yo no me diera cuenta.",
  "Uram, voltak percek a héten, amikor zúgolódtam, és a hiányra néztem, nem rád. Bocsásd meg, és változtasd meg a szívemet. Taníts hálásnak lenni akkor is, amikor nem könnyű.": "Señor, hubo momentos esta semana en que murmuré y miré lo que me faltaba en lugar de mirarte a ti. Perdóname y cambia mi corazón. Enséñame a ser agradecido también cuando no es fácil.",
  "Uram, te azt mondod, mindenben adjak hálát, nem mindenért, hanem mindenben. A nehézben is te vagy velem, és ezért ott is van mit köszönnöm. Ez a te akaratod, és én ezt választom.": "Señor, tú me dices que dé gracias en todo: no por todo, sino en todo. También en lo difícil estás conmigo, y por eso también allí hay algo que agradecer. Esta es tu voluntad, y yo la elijo.",
  "Uram, a hétvégét is veled szeretném tölteni, ne csak a hétköznapokat. Vigyázz azokra, akikkel együtt leszek, és add, hogy jó legyek hozzájuk. Legyen pihenés és öröm is benne.": "Señor, quiero pasar contigo también el fin de semana, no solo los días de trabajo. Cuida a las personas con las que estaré, y ayúdame a ser bueno con ellas. Que haya también descanso y alegría.",
  "Uram, örülök, hogy velem vagy. Csendben is ezt mondom.": "Señor, me alegro de que estés conmigo. También en silencio te lo digo.",
  "Uram, köszönöm, hogy ma meg lehet állni. Köszönöm, ami ezen a héten elkészült, és köszönöm, hogy nem rajtam múlik a világ. A pihenés is tőled jön.": "Señor, gracias porque hoy puedo detenerme. Gracias por lo que se terminó esta semana, y gracias porque el mundo no depende de mí. También el descanso viene de ti.",
  "Uram, cipelek dolgokat, amiket nem rám bíztál. Felelősséget, amit te hordozol, aggodalmat, amit te már elrendeztél. Megvallom, hogy nehezen engedem el, és most leteszem.": "Señor, cargo cosas que tú no me encomendaste: responsabilidades que llevas tú, preocupaciones que tú ya has resuelto. Confieso que me cuesta soltarlas, y ahora las dejo.",
  "Uram, te a megfáradtakat hívod, és én fáradt vagyok. Nem azt kéred, hogy előbb rendbe jöjjek, hanem hogy jöjjek. Jövök hozzád, úgy, ahogy vagyok.": "Señor, tú llamas a los cansados, y yo estoy cansado. No me pides que primero me ponga en orden, sino que venga. Vengo a ti tal como soy.",
  "Uram, adj nyugalmat a testemnek és a lelkemnek. Ami a jövő héten vár, azt is a kezedbe teszem, hogy ne most hordozzam. Újítsd meg az erőmet, ahogy csak te tudod.": "Señor, da descanso a mi cuerpo y a mi alma. Lo que me espera la próxima semana también lo pongo en tus manos, para no cargarlo ahora. Renueva mis fuerzas, como solo tú puedes hacerlo.",
  "Uram, megpihenek nálad. Nem teszek semmit, csak itt vagyok.": "Señor, descanso en ti. No hago nada; solo estoy aquí.",
  "Az Úr az én pásztorom": "El Señor es mi pastor",
  "Köszönd meg, hogy van, aki vezet, és nem egyedül kell kitalálnod az utat.": "Da gracias porque hay alguien que te guía, y no tienes que descubrir el camino tú solo.",
  "Uram, köszönöm, hogy nem egyedül kell kitalálnom, hová megyek. Te vezetsz, te gondoskodsz, és te ismered az utat, ahol én még nem jártam. Jó a te nyájadhoz tartozni.": "Señor, gracias porque no tengo que descubrir solo adónde voy. Tú me guías, tú me cuidas, y tú conoces el camino por donde yo nunca he pasado. Es bueno pertenecer a tu rebaño.",
  "Hol mentél a magad feje után a héten, ahelyett, hogy őt követted volna? Mondd el.": "¿Dónde fuiste por tu cuenta esta semana en lugar de seguirle? Díselo.",
  "Uram, voltak helyek, ahová a magam feje után mentem, és nem kérdeztelek meg. Megvallom, hogy okosabbnak hittem magam a pásztoromnál. Hozz vissza, és én jövök.": "Señor, hubo lugares adonde fui por mi cuenta sin preguntarte. Confieso que me creí más sabio que mi pastor. Hazme volver, y volveré.",
  "Olvasd el, és mondd ki saját szavaddal: ő az én pásztorom.": "Léelo y dilo con tus propias palabras: él es mi pastor.",
  "Uram, te vagy az én pásztorom, nem általánosságban, hanem az enyém. Ha te vezetsz, nem szűkölködöm, mert te tudod, mi kell nekem. Erre építem ezt a hetet.": "Señor, tú eres mi pastor, no en general, sino el mío. Si tú me guías, nada me faltará, porque tú sabes lo que necesito. Sobre esto edifico esta semana.",
  "Kérd, hogy a jövő héten a hangját kövesd, és hogy a sötét völgyben is érezd, hogy ott van.": "Pide seguir su voz la próxima semana, y sentir que él está allí incluso en el valle oscuro.",
  "Uram, add, hogy a jövő héten a te hangodat kövessem, ne a zajt. Ha völgybe vezet az út, add, hogy tudjam, ott is velem vagy. Legelőt és vizet is te adsz, rád bízom.": "Señor, ayúdame a seguir tu voz la próxima semana, no el ruido. Si el camino me lleva a un valle, hazme saber que también allí estás conmigo. Los pastos y el agua también los das tú; en ti confío.",
  "Maradj csendben, mint aki biztonságban van.": "Quédate en silencio, como quien está a salvo.",
  "Uram, biztonságban vagyok nálad. Csendben maradok.": "Señor, contigo estoy a salvo. Me quedo en silencio.",
  "Elég a kegyelem": "Basta la gracia",
  "Köszönd meg azokat a helyzeteket, ahol a saját erőd nem volt elég, mégis átjutottál.": "Da gracias por las situaciones en que tus propias fuerzas no bastaron y, aun así, saliste adelante.",
  "Uram, köszönöm azokat a helyzeteket, ahol a saját erőm elfogyott, és mégis átjutottam. Nem én voltam erős, te voltál. Köszönöm, hogy a gyengeségem nem akadály nálad.": "Señor, gracias por las situaciones en que mis propias fuerzas se acabaron y, aun así, salí adelante. No fui yo el fuerte; fuiste tú. Gracias porque mi debilidad no es un obstáculo para ti.",
  "Hol próbáltad a saját erődből megoldani, amit rá kellett volna bíznod? Valld meg.": "¿Dónde intentaste resolver con tus propias fuerzas lo que debías haberle confiado a él? Confiésalo.",
  "Uram, megvallom, hogy sokszor a magam erejéből akartam megoldani, amit neked kellett volna átadnom. Büszkeségből vagy félelemből, de nélküled. Bocsáss meg, és taníts rád támaszkodni.": "Señor, confieso que muchas veces quise resolver con mis propias fuerzas lo que debía haberte entregado a ti. Por orgullo o por miedo, pero sin ti. Perdóname y enséñame a apoyarme en ti.",
  "Olvasd el. Figyeld meg: Pál nem a gyengeség megszűnését kapta, hanem a kegyelmet benne.": "Léelo. Fíjate: Pablo no recibió el fin de su debilidad, sino la gracia en medio de ella.",
  "Uram, te azt mondtad Pálnak: elég neked az én kegyelmem. Nekem is ezt mondod. Nem azt ígéred, hogy elveszed a tövist, hanem hogy az erőd a gyengeségemben teljesedik ki.": "Señor, tú le dijiste a Pablo: bástate mi gracia. A mí me dices lo mismo. No prometes quitarme el aguijón, sino que tu poder se perfecciona en mi debilidad.",
  "Nevezd meg a gyenge pontodat erre a hétre, és kérd, hogy ott Krisztus ereje lakjon.": "Nombra tu punto débil para esta semana, y pide que el poder de Cristo habite allí.",
  "Uram, tudom, hol vagyok gyenge ezen a héten, és eléd hozom. Ott lakjon a Krisztus ereje, ahol az enyém nem elég. Nem kérem, hogy erős legyek, azt kérem, hogy te legyél erős bennem.": "Señor, sé dónde soy débil esta semana, y lo traigo delante de ti. Que el poder de Cristo habite allí, donde el mío no basta. No te pido ser fuerte; te pido que tú seas fuerte en mí.",
  "Csendben hagyd, hogy a kegyelem elég legyen.": "En silencio, deja que la gracia te baste.",
  "Uram, elég nekem a kegyelmed. Ezt most elhiszem, és csendben maradok.": "Señor, tu gracia me basta. Ahora lo creo, y me quedo en silencio.",
  "Ne félj": "No temas",
  "Köszönd meg azokat a pillanatokat, amikor féltél, és ő mégis ott volt.": "Da gracias por los momentos en que tuviste miedo y, aun así, él estaba allí.",
  "Uram, köszönöm azokat a pillanatokat, amikor féltem, és te mégis ott voltál. Köszönöm, hogy nem hagytál egyedül a félelemmel, akkor sem, amikor nem éreztelek. Visszanézve látom a kezedet.": "Señor, gracias por los momentos en que tuve miedo y, aun así, tú estabas allí. Gracias por no dejarme solo con mi miedo, incluso cuando no te sentía. Al mirar atrás, veo tu mano.",
  "A félelem gyakran olyan döntésekhez vezet, amiket nem vállalnánk tisztán. Hol döntöttél félelemből? Mondd el neki.": "El miedo nos lleva a menudo a decisiones que no tomaríamos con la mente clara. ¿Dónde decidiste por miedo? Díselo.",
  "Uram, megvallom, hogy voltak döntéseim, amiket a félelem hozott, nem a hit. Elhallgattam, elkerültem, halogattam, mert féltem. Bocsásd meg, és szabadíts meg a félelem uralmától.": "Señor, confieso que algunas de mis decisiones las tomó el miedo, no la fe. Callé, evité, aplacé, porque tenía miedo. Perdóname y líbrame del dominio del miedo.",
  "Olvasd el, és számold meg, hány ígéret van egy versben. Mindegyik a jelenlétéből fakad.": "Léelo y cuenta cuántas promesas hay en un solo versículo. Cada una brota de su presencia.",
  "Uram, te azt mondod: ne félj, mert veled vagyok. Nem azt mondod, hogy nincs mitől, hanem hogy te ott vagy. Megerősítesz, megsegítesz, a jobboddal támogatsz, és én ebbe kapaszkodom.": "Señor, tú dices: no temas, porque yo estoy contigo. No dices que no haya nada que temer, sino que tú estás ahí. Me fortaleces, me ayudas, me sostienes con tu diestra, y a eso me aferro.",
  "Nevezd meg a legnagyobb félelmedet most, és tedd mellé a vers szavait.": "Nombra ahora tu mayor miedo, y pon a su lado las palabras del versículo.",
  "Uram, kimondom előtted, mitől félek most a legjobban. Odateszem mellé a te szavaidat: veled vagyok, megerősítelek. Add, hogy a félelmem kisebb legyen, mint a hitem benned.": "Señor, digo delante de ti lo que más temo ahora. Pongo a su lado tus palabras: yo estoy contigo, yo te fortalezco. Haz que mi miedo sea más pequeño que mi fe en ti.",
  "Maradj csendben, mint akit fog a jobb kéz.": "Quédate en silencio, como quien es sostenido por la mano derecha.",
  "Uram, te fogsz engem, nem én téged. Ebben nyugszom meg.": "Señor, tú me sostienes a mí, no yo a ti. En eso descanso.",
  "Bízd rá az utadat": "Encomienda a él tu camino",
  "Köszönd meg azokat a döntéseket, amiket utólag nézve ő igazgatott.": "Da gracias por las decisiones que, mirando atrás, él dirigió.",
  "Uram, köszönöm azokat a döntéseket, amikről utólag látom, hogy te igazgattad. Akkor nem értettem, most már igen. Köszönöm, hogy a kerülőutak is a te kezedben voltak.": "Señor, gracias por las decisiones que ahora veo que tú dirigiste. Entonces no lo entendía; ahora sí. Gracias porque también los rodeos estaban en tus manos.",
  "Hol támaszkodtál csak a saját értelmedre, és hagytad ki őt a döntésből? Valld meg.": "¿Dónde te apoyaste solo en tu propio entendimiento y lo dejaste fuera de la decisión? Confiésalo.",
  "Uram, megvallom, hogy voltak döntéseim, amikbe nem vontalak be. Mindent kiszámoltam, csak téged nem kérdeztelek meg. Bocsáss meg, és segíts bizalommal élni, ne csak okosan.": "Señor, confieso que hubo decisiones en las que no te incluí. Lo calculé todo, pero a ti no te pregunté. Perdóname y ayúdame a vivir con confianza, no solo con inteligencia.",
  "Olvasd el. Nem az értelmet tiltja, hanem azt, hogy csak arra építs.": "Léelo. No prohíbe el entendimiento, sino apoyarse solo en él.",
  "Uram, te adtad az értelmemet, és nem kéred, hogy eldobjam. Azt kéred, hogy ne egyedül arra építsek, hanem rád. Minden utamon számolok veled, és te igazgatod az utamat.": "Señor, tú me diste mi entendimiento, y no me pides que lo deseche. Me pides que no me apoye solo en él, sino en ti. En todos mis caminos te reconozco, y tú enderezas mis veredas.",
  "Hozd eléje azt a döntést, ami most előtted áll. Kérj bölcsességet és nyitott szívet az ő irányára.": "Trae delante de él la decisión que ahora tienes por delante. Pide sabiduría y un corazón abierto a su dirección.",
  "Uram, eléd hozom azt a döntést, ami most előttem áll. Adj bölcsességet, és adj nyitott szívet, hogy a te irányodat elfogadjam akkor is, ha más, mint amit terveztem. Igazgasd ezt az utamat.": "Señor, traigo delante de ti la decisión que ahora tengo por delante. Dame sabiduría, y dame un corazón abierto para aceptar tu dirección, aunque sea distinta de lo que yo había planeado. Endereza este camino mío.",
  "Csendben engedd el a kontrollt.": "En silencio, suelta el control.",
  "Uram, az utam a tiéd. Elengedem, és rád bízom.": "Señor, mi camino es tuyo. Lo suelto y te lo confío.",
  "Egymás terhét": "Las cargas los unos de los otros",
  "Köszönd meg azokat, akik a te terhedet hordozták, amikor nehéz volt.": "Da gracias por quienes llevaron tu carga cuando las cosas se pusieron difíciles.",
  "Uram, köszönöm azokat az embereket, akik hordozták a terhemet, amikor nehéz volt. Egy hívás, egy ima, egy segítő kéz, amikor kellett. Rajtuk keresztül te voltál ott.": "Señor, gracias por las personas que llevaron mi carga cuando las cosas se pusieron difíciles. Una llamada, una oración, una mano amiga cuando la necesitaba. A través de ellas, tú estabas allí.",
  "Kinek a terhe elől fordultál el az utóbbi időben, mert kényelmetlen volt? Mondd el.": "¿De la carga de quién te apartaste últimamente porque era incómoda? Díselo.",
  "Uram, megvallom, hogy volt valaki, akinek a terhe elől elfordultam, mert kényelmetlen volt. Láttam, és továbbmentem. Bocsásd meg, és adj szívet, ami nem fordul el.": "Señor, confieso que hubo alguien de cuya carga me aparté porque era incómoda. Lo vi y seguí de largo. Perdóname y dame un corazón que no se aparte.",
  "Olvasd el. A Krisztus törvénye a szeretet: így teljesítjük be.": "Léelo. La ley de Cristo es el amor: así la cumplimos.",
  "Uram, te azt mondod, hogy egymás terhét hordozzuk, és ezzel a Krisztus törvényét töltjük be. Nem szabály ez, hanem szeretet. Taníts úgy szeretni, ahogy te szerettél engem.": "Señor, tú nos dices que sobrellevemos los unos las cargas de los otros, y así cumplamos la ley de Cristo. No es una regla, es amor. Enséñame a amar como tú me has amado.",
  "Nevezz meg három embert, akiknek most teher van a vállán. Imádkozz érte egyenként: egészségért, erőért, kiútért.": "Nombra a tres personas que ahora llevan una carga. Ora por cada una: por salud, por fuerza, por una salida.",
  "Uram, eléd hozok három embert, akik most terhet hordoznak. Az elsőért kérem, hogy adj neki erőt, a másodikért, hogy gyógyítsd, a harmadikért, hogy mutass neki kiutat. És ha engem akarsz használni bármelyiküknél, mutasd meg, hogyan.": "Señor, traigo delante de ti a tres personas que ahora llevan una carga. Por la primera te pido que le des fuerza; por la segunda, que la sanes; por la tercera, que le muestres una salida. Y si quieres usarme con alguna de ellas, muéstrame cómo.",
  "Csendben kérdezd meg: kihez küld ma?": "En silencio, pregunta: ¿a quién te envía hoy?",
  "Uram, kihez küldesz ma? Csendben várom.": "Señor, ¿a quién me envías hoy? Espero en silencio.",
  "Ahogy ő megbocsátott": "Como él perdonó",
  "Köszönd meg, hogy neked megbocsáttatott, konkrétan, nem általánosságban.": "Da gracias porque has sido perdonado, de forma concreta, no en general.",
  "Uram, köszönöm, hogy megbocsátottál nekem. Nem általánosságban, hanem azt a konkrét dolgot is, ami most eszembe jut. Krisztusban elrendezted, és nem tartod számon.": "Señor, gracias por haberme perdonado. No en general, sino también eso concreto que ahora me viene a la mente. En Cristo lo arreglaste, y ya no me lo tomas en cuenta.",
  "Kire haragszol még? Mondd ki a nevét Isten előtt, és valld meg, ha keserűséget hordozol.": "¿Con quién sigues enojado? Di su nombre delante de Dios, y confiésalo si llevas amargura.",
  "Uram, van valaki, akire még haragszom, és a nevét most kimondom előtted. Megvallom, hogy keserűséget hordozok, és ez nem tőled van. Vedd ki a szívemből, mert magam nem tudom.": "Señor, hay alguien con quien sigo enojado, y ahora digo su nombre delante de ti. Confieso que llevo amargura, y no viene de ti. Quítala de mi corazón, porque yo solo no puedo.",
  "Olvasd el. A mérce: ahogy Isten Krisztusban nekem.": "Léelo. La medida: como Dios me perdonó en Cristo.",
  "Uram, te azt mondod, úgy bocsássak meg, ahogy te megbocsátottál nekem Krisztusban. Ez a mérce, és én ebből élek. Nem azért bocsátok meg, mert a másik megérdemli, hanem mert én is kegyelmet kaptam.": "Señor, tú me dices que perdone como tú me perdonaste en Cristo. Esa es la medida, y de ella vivo. No perdono porque el otro lo merezca, sino porque yo también he recibido gracia.",
  "Kérj erőt a megbocsátásra, és áldást arra az emberre. Ha túl nehéz, csak ezt mondd: segíts akarni.": "Pide fuerza para perdonar, y bendición para esa persona. Si es demasiado difícil, di solo: ayúdame a querer.",
  "Uram, adj erőt, hogy megbocsássak annak, akit most eléd hoztam, és áldd meg őt. Ha még nem tudom teljesen, segíts akarni. Tedd meg bennem, amit én még nem tudok megtenni.": "Señor, dame fuerza para perdonar a quien acabo de traer delante de ti, y bendícelo. Si todavía no puedo del todo, ayúdame a querer hacerlo. Haz en mí lo que yo todavía no puedo hacer.",
  "Csendben engedd el, ami a kezedben volt.": "En silencio, suelta lo que tenías en la mano.",
  "Uram, elengedem. A kezedbe teszem, nem az enyémben tartom.": "Señor, lo suelto. Lo pongo en tus manos y ya no lo retengo en las mías.",
  "Megújuló erő": "Fuerzas renovadas",
  "Köszönd meg a hetet, és azt, hogy végigvitt rajta, akkor is, ha elfáradtál.": "Da gracias por la semana, y porque él te llevó a través de ella, aunque te cansaras.",
  "Uram, köszönöm, hogy végigvittél ezen a héten. Volt, hogy elfáradtam, de te nem fáradtál el mellettem. Köszönöm a mai napot, amikor meg lehet állni.": "Señor, gracias por llevarme a través de esta semana. A veces me cansé, pero tú no te cansaste a mi lado. Gracias por el día de hoy, en que puedo detenerme.",
  "Hol pótoltad a saját erőddel azt, amit tőle kellett volna várnod? Mondd el.": "¿Dónde intentaste suplir con tus propias fuerzas lo que debías haber esperado de él? Díselo.",
  "Uram, megvallom, hogy sokszor a saját erőmből próbáltam pótolni azt, amit tőled kellett volna várnom. Hajtottam, mert nem bíztam. Bocsásd meg, és taníts várni rád.": "Señor, confieso que muchas veces intenté suplir con mis propias fuerzas lo que debía haber esperado de ti. Me exigí sin descanso porque no confiaba. Perdóname y enséñame a esperar en ti.",
  "Olvasd el lassan. Az erő azoknak újul meg, akik benne bíznak, nem akik jobban igyekeznek.": "Léelo despacio. Las fuerzas se renuevan para quienes confían en él, no para quienes se esfuerzan más.",
  "Uram, te azt mondod, hogy akik benned bíznak, azok ereje megújul. Nem akik jobban igyekeznek, hanem akik bíznak. Én is ezt választom: nem több erőlködés, hanem több bizalom.": "Señor, tú dices que los que confían en ti renovarán sus fuerzas. No los que se esfuerzan más, sino los que confían. Yo también elijo esto: no más esfuerzo, sino más confianza.",
  "Kérj megújulást a testednek, a gondolataidnak és a hitednek a jövő hétre.": "Pide renovación para tu cuerpo, tus pensamientos y tu fe para la próxima semana.",
  "Uram, újítsd meg az erőmet a jövő hétre: a testemet, a gondolataimat és a hitemet. Add, hogy ne lankadjak meg a hosszú úton, és ne fáradjak el a mindennapiban. Te vagy a forrás, nem én.": "Señor, renueva mis fuerzas para la próxima semana: mi cuerpo, mis pensamientos y mi fe. Que no desfallezca en el camino largo, ni me canse en lo cotidiano. Tú eres la fuente, no yo.",
  "Pihenj csendben, mint aki vár az Úrra.": "Descansa en silencio, como quien espera en el Señor.",
  "Uram, várok rád. Csendben, nem sietve.": "Señor, espero en ti. En silencio, sin prisa.",
  "Világosságom és üdvösségem": "Mi luz y mi salvación",
  "Köszönd meg, hogy van világosságod, amikor minden más sötét.": "Da gracias porque tienes una luz cuando todo lo demás está oscuro.",
  "Uram, köszönöm, hogy te vagy a világosságom, amikor körülöttem sötét van. Köszönöm, hogy az üdvösségem nem rajtam áll, hanem rajtad. Jó ezt egy vasárnap reggel kimondani.": "Señor, gracias porque tú eres mi luz cuando a mi alrededor todo está oscuro. Gracias porque mi salvación no depende de mí, sino de ti. Es bueno decirlo un domingo por la mañana.",
  "Mitől remegtél a héten, ami nagyobbnak látszott, mint Isten? Valld meg.": "¿Qué te hizo temblar esta semana porque parecía más grande que Dios? Confiésalo.",
  "Uram, megvallom, hogy voltak dolgok a héten, amik nagyobbnak látszottak, mint te. Remegtem tőlük, mintha te nem lennél az erősségem. Bocsáss meg, és állítsd helyre bennem az arányokat.": "Señor, confieso que hubo cosas esta semana que parecían más grandes que tú. Temblé ante ellas, como si tú no fueras mi fortaleza. Perdóname y vuelve a poner las cosas en su justa medida dentro de mí.",
  "Olvasd el, és válaszolj a kérdésre: kitől féljek?": "Léelo y responde a la pregunta: ¿de quién temeré?",
  "Uram, te kérdezed: kitől féljek? És a válasz az, hogy senkitől, mert te vagy az életem erőssége. Nem azért, mert bátor vagyok, hanem mert a tiéd vagyok.": "Señor, tú preguntas: ¿de quién temeré? Y la respuesta es: de nadie, porque tú eres la fortaleza de mi vida. No porque yo sea valiente, sino porque soy tuyo.",
  "Kérd, hogy a jövő héten a te világosságában lásd a dolgokat, és hogy a házában lakjon a szíved.": "Pide ver las cosas a su luz la próxima semana, y que tu corazón habite en su casa.",
  "Uram, add, hogy a jövő héten a te világosságodban lássam a dolgokat, ne a félelem fényében. Legyen a szívem otthon nálad, akármerre jár a testem. Ezt kérem egyedül.": "Señor, ayúdame a ver las cosas a tu luz la próxima semana, no a la luz del miedo. Que mi corazón esté en casa contigo, vaya donde vaya mi cuerpo. Solo esto te pido.",
  "Maradj csendben az ő világosságában.": "Quédate en silencio en su luz.",
  "Uram, a világosságodban vagyok. Itt maradok.": "Señor, estoy en tu luz. Aquí me quedo.",
  "A Lélek gyümölcse": "El fruto del Espíritu",
  "Köszönd meg, hogy a Szentlélek benned lakik, és nem egyedül kell jóvá lenned.": "Da gracias porque el Espíritu Santo vive en ti, y no tienes que llegar a ser bueno tú solo.",
  "Uram, köszönöm, hogy a Szentlelked bennem lakik, és nem egyedül kell jóvá lennem. Köszönöm, hogy a változás nem az én görcsös igyekezetem, hanem a te munkád bennem.": "Señor, gracias porque tu Espíritu Santo vive en mí, y no tengo que llegar a ser bueno yo solo. Gracias porque el cambio no es mi esfuerzo crispado, sino tu obra en mí.",
  "A kilenc gyümölcsből melyik hiányzott a legjobban a hétvégén? Mondd el.": "De los nueve frutos, ¿cuál faltó más durante el fin de semana? Díselo.",
  "Uram, végignézem a Lélek gyümölcseit, és tudom, melyik hiányzott a hétvégén. Kimondom előtted, mi volt az. Bocsásd meg, és ne hagyd, hogy ez legyen a végső szó rólam.": "Señor, repaso el fruto del Espíritu, y sé cuál faltó durante el fin de semana. Lo nombro delante de ti. Perdóname, y no permitas que esa sea la última palabra sobre mí.",
  "Olvasd el lassan a kilenc szót. Melyiket kéri tőled Isten ezen a héten?": "Lee despacio las nueve palabras. ¿Cuál te pide Dios esta semana?",
  "Uram, kilenc szót olvasok, és mindegyik a te természeted. Nem én termelem, a te Lelked termi bennem, ha vele járok. Mutasd meg, melyiket akarod ezen a héten növelni bennem.": "Señor, leo nueve palabras, y cada una es tu naturaleza. No las produzco yo; tu Espíritu las hace crecer en mí cuando camino con él. Muéstrame cuál quieres hacer crecer en mí esta semana.",
  "Kérd azt az egy gyümölcsöt a hétre, és nevezd meg a helyzetet, ahol szükséged lesz rá.": "Pide ese único fruto para la semana, y nombra la situación en la que lo vas a necesitar.",
  "Uram, azt az egy gyümölcsöt kérem erre a hétre, amit most mutattál. Tudom, melyik helyzetben lesz rá szükségem, és eléd hozom azt is. Teremd meg bennem, amit én nem tudok előállítani.": "Señor, para esta semana te pido ese único fruto que acabas de mostrarme. Sé en qué situación lo voy a necesitar, y también la traigo delante de ti. Haz crecer en mí lo que yo no puedo producir.",
  "Csendben engedd, hogy a Lélek dolgozzon.": "En silencio, deja que el Espíritu obre.",
  "Uram, dolgozz bennem. Nem állok az utadba.": "Señor, obra en mí. No me pondré en tu camino.",
  "Gyors a hallásra": "Pronto para oír",
  "Köszönd meg azokat, akik meghallgattak téged, és azt, hogy Isten mindig meghallgat.": "Da gracias por quienes te escucharon, y porque Dios siempre escucha.",
  "Uram, köszönöm, hogy te mindig meghallgatsz, mielőtt szólnék. És köszönöm azokat az embereket, akik meghallgattak engem, amikor beszélnem kellett. A meghallgatás ajándék, és te adod.": "Señor, gracias porque siempre me escuchas, incluso antes de que hable. Y gracias por las personas que me escucharon cuando necesitaba hablar. Ser escuchado es un regalo, y tú lo das.",
  "Hol szóltál túl gyorsan, hol haragudtál túl hamar a héten? Nevezd meg az esetet, és valld meg.": "¿Dónde hablaste demasiado rápido, o te enojaste demasiado pronto esta semana? Nombra el momento y confiésalo.",
  "Uram, megvallom, hogy voltak percek, amikor gyorsabban szóltam, mint hallgattam, és hamarabb haragudtam, mint értettem. Egy konkrét eset most eszembe jut, és eléd teszem. Bocsásd meg, és adj szelíd nyelvet.": "Señor, confieso que hubo momentos en que hablé antes de escuchar, y me enojé antes de entender. Ahora me viene a la mente un caso concreto, y lo pongo delante de ti. Perdóname y dame una lengua apacible.",
  "Olvasd el a három sorrendet: gyors, késedelmes, késedelmes. Melyik a te gyenge pontod?": "Lee las tres en orden: pronto, tardo, tardo. ¿Cuál es tu punto débil?",
  "Uram, te azt kéred: gyors legyek a hallásra, késedelmes a szólásra és a haragra. Tudom, hol vagyok ebben gyenge. Taníts először téged hallgatni, aztán az embereket, és csak utána szólni.": "Señor, tú me pides que sea pronto para oír, tardo para hablar y tardo para enojarme. Sé dónde soy débil en esto. Enséñame a escucharte primero a ti, después a las personas, y solo entonces hablar.",
  "Kérj türelmes szívet a mai beszélgetéseidhez, és egy konkrét emberhez, akivel nehezen beszélsz.": "Pide un corazón paciente para las conversaciones de hoy, y por una persona concreta con la que te cuesta hablar.",
  "Uram, adj türelmes szívet a mai beszélgetésekhez. Van valaki, akivel nehezen beszélek, őt külön eléd hozom: segíts meghallgatnom, mielőtt válaszolok. Legyen a szavam békesség, ne tűz.": "Señor, dame un corazón paciente para las conversaciones de hoy. Hay alguien con quien me cuesta hablar, y lo traigo especialmente delante de ti: ayúdame a escuchar antes de responder. Que mis palabras traigan paz, no fuego.",
  "Csendben hallgass, ez a gyakorlat maga.": "Escucha en silencio; ese es el ejercicio mismo.",
  "Uram, hallgatlak. Most nem beszélek.": "Señor, te escucho. Ahora no hablo.",
  "Nézd a madarakat": "Mirad las aves",
  "Köszönd meg a mindennapi gondviselést: az ételt, a munkát, a hónap végéig kitartó erőt.": "Da gracias por la provisión de cada día: la comida, el trabajo, las fuerzas que alcanzaron hasta fin de mes.",
  "Uram, köszönöm a mindennapi gondviselésedet: az ételt az asztalon, a munkát, ami van, és az erőt, ami kitartott a hónap végéig. Nem magamnak köszönhetem, neked.": "Señor, gracias por tu provisión de cada día: por la comida en la mesa, por el trabajo que tengo, y por las fuerzas que alcanzaron hasta fin de mes. No me lo debo a mí, sino a ti.",
  "Hol aggódtál a jövő miatt úgy, mintha az Atya elfelejtett volna? Mondd el.": "¿Dónde te preocupaste por el futuro como si el Padre te hubiera olvidado? Díselo.",
  "Uram, megvallom, hogy aggódtam a jövő miatt, mintha elfelejtettél volna. Számoltam, forgattam, nem aludtam, és közben nem néztem rád. Bocsásd meg a kishitűségemet.": "Señor, confieso que me preocupé por el futuro como si me hubieras olvidado. Hice cuentas, le di vueltas, no dormí, y mientras tanto no te miré a ti. Perdona mi poca fe.",
  "Olvasd el. Figyeld meg a kérdést a végén: nem vagytok-e sokkal különbek?": "Léelo. Fíjate en la pregunta del final: ¿no valéis vosotros mucho más?",
  "Uram, te a madarakra mutatsz, és azt kérdezed, nem vagyok-e sokkal különb azoknál. A te gyermeked vagyok, nem csak a teremtményed. Ha őket eltartod, engem sem hagysz el.": "Señor, tú señalas las aves y me preguntas si no valgo yo mucho más que ellas. Soy tu hijo, no solo tu criatura. Si a ellas las alimentas, a mí tampoco me abandonarás.",
  "Hozd eléje az anyagi és gyakorlati gondjaidat, egyenként, és kérd, hogy ő tartson el.": "Trae delante de él tus preocupaciones económicas y prácticas, una por una, y pídele que te sustente.",
  "Uram, eléd hozom az anyagi és gyakorlati gondjaimat, egyenként, ahogy vannak. Nem kérek fölösleget, azt kérem, hogy te tarts el, ahogy a madarakat. Adj munkát a kezemnek, és bizalmat a szívemnek.": "Señor, traigo delante de ti mis preocupaciones económicas y prácticas, una por una, tal como son. No te pido lo superfluo; te pido que me sustentes, como a las aves. Da trabajo a mis manos y confianza a mi corazón.",
  "Csendben nézz ki az ablakon, vagy képzeld el: ő gondot visel.": "En silencio, mira por la ventana, o imagínalo: él cuida de ti.",
  "Uram, te gondot viselsz rám. Csendben ezt hagyom bennem leülepedni.": "Señor, tú cuidas de mí. En silencio dejo que esto se asiente en mí.",
  "Imádság a vezetőkért": "Oración por los gobernantes",
  "Köszönd meg a békét, amiben élsz, a rendet, ami működik, és azokat, akik szolgálnak benne.": "Da gracias por la paz en la que vives, por el orden que funciona, y por quienes sirven en él.",
  "Uram, köszönöm a békét, amiben élek, és a rendet, ami működik körülöttem, akkor is, ha nem tökéletes. Köszönöm azokat, akik ebben szolgálnak, az orvosokat, a tanárokat, a tisztviselőket. Rajtuk keresztül is gondot viselsz.": "Señor, gracias por la paz en la que vivo, y por el orden que funciona a mi alrededor, aunque no sea perfecto. Gracias por quienes sirven en él: los médicos, los maestros, los funcionarios. También a través de ellos cuidas de nosotros.",
  "Hol ítéltél vagy szidtál vezetőket imádság helyett? Valld meg.": "¿Dónde juzgaste o criticaste a los gobernantes en lugar de orar por ellos? Confiésalo.",
  "Uram, megvallom, hogy könnyebben szidtam a vezetőket, mint imádkoztam értük. Ítéltem ott, ahol könyörögnöm kellett volna. Bocsásd meg, és adj szívet, ami inkább kér, mint vádol.": "Señor, confieso que me ha sido más fácil criticar a los gobernantes que orar por ellos. Juzgué donde debía haber intercedido. Perdóname y dame un corazón que prefiera pedir antes que acusar.",
  "Olvasd el. Mindenek előtt: ez a sorrend. És mindenkiért, nem csak azokért, akiket kedvelünk.": "Léelo. Ante todo: ese es el orden. Y por todos, no solo por los que nos caen bien.",
  "Uram, te azt kéred, hogy mindenekelőtt imádkozzak minden emberért, a vezetőkért is. Nem azért, mert egyetértek velük, hanem mert te így akarod. Ez nem politika, ez közbenjárás.": "Señor, tú me pides que ante todo ore por todas las personas, también por los gobernantes. No porque esté de acuerdo con ellos, sino porque así lo quieres tú. Esto no es política, es intercesión.",
  "Imádkozz a saját országod vezetőiért, a településedért, a gyülekezeted vezetőiért, és azokért, akik háborús országokban döntenek.": "Ora por los gobernantes de tu propio país, por tu localidad, por los líderes de tu iglesia, y por quienes toman decisiones en países en guerra.",
  "Uram, eléd hozom azokat, akik az országomat vezetik, bármilyen oldalon állnak: adj nekik bölcsességet, igazságot és félelmet tőled. Imádkozom a településemért és azokért, akik ott döntenek. Imádkozom a gyülekezetem vezetőiért, hogy hűek maradjanak. És imádkozom azokért, akik háborús országokban döntenek életről és halálról: fordítsd a szívüket a béke felé.": "Señor, traigo delante de ti a quienes gobiernan mi país, estén del lado que estén: dales sabiduría, justicia y temor de ti. Oro por mi localidad y por quienes toman decisiones allí. Oro por los líderes de mi iglesia, para que permanezcan fieles. Y oro por quienes deciden sobre la vida y la muerte en países en guerra: vuelve su corazón hacia la paz.",
  "Csendben kérj békét, hogy nyugodalmas életet élhessünk.": "En silencio, pide paz, para que vivamos una vida tranquila y sosegada.",
  "Uram, adj békét, hogy csendes és nyugodalmas életet élhessünk. Ámen.": "Señor, danos paz, para que vivamos una vida tranquila y sosegada. Amén.",
  "A reménység Istene": "El Dios de la esperanza",
  "Péntek van, a hála napja. Köszönd meg a hét öt jó pillanatát, és köszönd meg a reménységet, ami nem tőled függ.": "Es viernes, el día de la gratitud. Da gracias por cinco buenos momentos de la semana, y da gracias por la esperanza que no depende de ti.",
  "Uram, végigmegyek a héten, és megköszönöm az öt legjobb pillanatát, egyiket a másik után. És köszönöm, hogy a reménységem nem a körülményeimtől függ, hanem tőled. Te vagy a reménység Istene.": "Señor, repaso la semana y te doy gracias por sus cinco mejores momentos, uno tras otro. Y gracias porque mi esperanza no depende de mis circunstancias, sino de ti. Tú eres el Dios de la esperanza.",
  "Hol engedted el a reményt a héten, és hol lett belőle keserű beszéd? Mondd el.": "¿Dónde soltaste la esperanza esta semana, y dónde se convirtió en palabras amargas? Díselo.",
  "Uram, megvallom, hogy voltak percek, amikor elengedtem a reményt, és keserű lett a beszédem. Nem hittem, hogy változhat bármi. Bocsásd meg, és töltsd meg újra a szívemet.": "Señor, confieso que hubo momentos en que solté la esperanza, y mis palabras se volvieron amargas. No creí que nada pudiera cambiar. Perdóname y vuelve a llenar mi corazón.",
  "Olvasd el. Az öröm és a békesség a hitből jön, a reménység a Lélek erejéből.": "Léelo. El gozo y la paz vienen de la fe; la esperanza, del poder del Espíritu.",
  "Uram, te a reménység Istene vagy, és örömmel, békességgel töltesz be a hitben. Nem én termelem a reményt, a Lelked adja. Hadd bővölködjek benne, ne csak megéljek.": "Señor, tú eres el Dios de la esperanza, y me llenas de gozo y de paz en la fe. No produzco yo la esperanza; me la da tu Espíritu. Déjame abundar en ella, no solo sobrevivir.",
  "Kérj reménységet egy konkrét ügyben, ami most reménytelennek látszik.": "Pide esperanza en un asunto concreto que ahora parece no tener salida.",
  "Uram, van egy ügy, ami most reménytelennek látszik, és eléd hozom. Adj reménységet benne, nem vak optimizmust, hanem a te Lelked erejét. Mutasd meg, hol vagy benne te.": "Señor, hay un asunto que ahora parece no tener salida, y lo traigo delante de ti. Dame esperanza en él, no un optimismo ciego, sino el poder de tu Espíritu. Muéstrame dónde estás tú en él.",
  "Csendben hagyd, hogy a béke betöltsön.": "En silencio, deja que la paz te llene.",
  "Uram, töltsd be a szívemet békével. Csendben várom.": "Señor, llena mi corazón de paz. Espero en silencio.",
  "Vizsgálj meg": "Examíname",
  "Köszönd meg, hogy Isten teljesen ismer, és mégis szeret.": "Da gracias porque Dios te conoce por completo y, aun así, te ama.",
  "Uram, köszönöm, hogy teljesen ismersz, a gondolataimat is, és mégis szeretsz. Előtted nem kell szerepet játszanom. Ez a legnagyobb nyugalom, ami egy hét végén létezik.": "Señor, gracias porque me conoces por completo, también mis pensamientos, y aun así me amas. Delante de ti no tengo que fingir. Es el mayor descanso que existe al final de una semana.",
  "Kérd, hogy ő mutassa meg, mit nem látsz magadban. Várj, és ami eszedbe jut, azt valld meg.": "Pídele que te muestre lo que no ves en ti mismo. Espera, y confiesa lo que te venga a la mente.",
  "Uram, vizsgálj meg, és mutasd meg, mit nem látok magamban. Nem védekezem, várok. Ami most eszembe jut, azt megvallom, és kérem, hogy tisztítsd ki belőlem.": "Señor, examíname y muéstrame lo que no veo en mí mismo. No me defiendo; espero. Lo que ahora me viene a la mente lo confieso, y te pido que me limpies de ello.",
  "Olvasd el lassan. Ez egy bizalmi kérés: aki szeret, azt engedjük vizsgálni.": "Léelo despacio. Es una petición de confianza: a quien nos ama, le dejamos examinarnos.",
  "Uram, Dávid azt kérte, hogy vizsgáld meg, és én is ezt kérem. Nem félek a tekintetedtől, mert tudom, hogy szeretettel nézel. Vezess az örökkévalóság útján, ne csak a mai napon át.": "Señor, David te pidió que lo examinaras, y yo te pido lo mismo. No temo tu mirada, porque sé que me miras con amor. Guíame por el camino eterno, no solo a lo largo de hoy.",
  "Kérd, hogy a jövő héten ott vezessen, ahol a legkönnyebb letérni.": "Pídele que te guíe la próxima semana allí donde es más fácil desviarse.",
  "Uram, tudom, hol a legkönnyebb letérnem a jövő héten, és eléd hozom. Ott vezess, ott tarts meg. Add, hogy a szívem ne menjen oda, ahová a lábam már ne lépjen.": "Señor, sé dónde me será más fácil desviarme la próxima semana, y lo traigo delante de ti. Guíame allí, sostenme allí. Que mi corazón no vaya adonde mis pies ya no deben pisar.",
  "Csendben hagyd, hogy ő nézzen rád, és pihenj ebben.": "En silencio, deja que él te mire, y descansa en ello.",
  "Uram, nézz rám. Én csendben maradok a tekinteted alatt.": "Señor, mírame. Me quedo en silencio bajo tu mirada.",
  "Hálaadással a kapuin": "Por sus puertas con acción de gracias",
  "Vasárnap van. Lépj be hálával: köszönd meg, aki ő, nem csak azt, amit ad.": "Es domingo. Entra con gratitud: dale gracias por quién es él, no solo por lo que da.",
  "Uram, hálaadással lépek eléd ezen a reggelen. Köszönöm, aki vagy: hű, jó, irgalmas, a kezdettől a végig ugyanaz. Nem csak az ajándékaidat áldom, hanem a nevedet.": "Señor, esta mañana vengo delante de ti con acción de gracias. Gracias por quién eres: fiel, bueno, misericordioso, el mismo del principio al fin. No solo alabo tus dones, sino tu nombre.",
  "Mi tart vissza attól, hogy teljes szívvel dicsérd? Mondd el neki.": "¿Qué te impide alabarle con todo tu corazón? Díselo.",
  "Uram, tudom, mi tart vissza attól, hogy teljes szívvel dicsérjelek. Fáradtság, sértődés, vagy egy el nem rendezett dolog. Eléd teszem, hogy ne álljon a kapuban.": "Señor, sé qué me impide alabarte con todo mi corazón. El cansancio, el resentimiento, o algo sin resolver. Lo pongo delante de ti, para que no se quede en la puerta.",
  "Olvasd el. Kapu, tornác, hála, dicséret: egyre közelebb visz hozzá.": "Léelo. Puertas, atrios, gratitud, alabanza: cada paso te acerca más a él.",
  "Uram, te hívsz, hogy a kapuidon hálaadással, az udvarodba dicsérettel lépjek be. Minden lépés közelebb visz hozzád. Áldom a nevedet, mert te vagy az Isten.": "Señor, tú me llamas a entrar por tus puertas con acción de gracias y por tus atrios con alabanza. Cada paso me acerca más a ti. Bendigo tu nombre, porque tú eres Dios.",
  "Kérj a gyülekezetedért, a mai istentiszteletért, és azokért, akik ma nem tudnak eljönni.": "Ora por tu iglesia, por el culto de hoy, y por quienes hoy no pueden asistir.",
  "Uram, eléd hozom a gyülekezetemet és a mai istentiszteletet: szólj, és add, hogy halljuk. Imádkozom azokért, akik ma nem tudnak eljönni, mert betegek vagy távol vannak. Légy velük ott, ahol vannak.": "Señor, traigo delante de ti a mi iglesia y el culto de hoy: habla, y haz que te oigamos. Oro por quienes hoy no pueden asistir porque están enfermos o lejos. Acompáñalos allí donde estén.",
  "Maradj csendben az ő udvarában.": "Quédate en silencio en sus atrios.",
  "Uram, itt vagyok az udvarodban. Jó itt lenni.": "Señor, aquí estoy en tus atrios. Es bueno estar aquí.",
  "Mint az Úrnak": "Como para el Señor",
  "Köszönd meg a munkádat, azt is, ami fárasztó. Ez a hely, ahol szolgálhatsz.": "Da gracias por tu trabajo, también por lo que cansa. Ese es el lugar donde puedes servir.",
  "Uram, köszönöm a munkámat, azt is, ami fárasztó és láthatatlan. Köszönöm, hogy van mit tennem, és van, aki számít rá. Ez a hely, ahol téged szolgálhatlak.": "Señor, gracias por mi trabajo, también por lo que cansa y nadie ve. Gracias porque tengo algo que hacer, y alguien cuenta con ello. Ese es el lugar donde puedo servirte.",
  "Hol dolgoztál csak a látszatért, vagy csak félszívvel? Valld meg.": "¿Dónde trabajaste solo para aparentar, o a medias? Confiésalo.",
  "Uram, megvallom, hogy voltak napok, amikor csak a látszatért dolgoztam, vagy félszívvel. Embereknek akartam megfelelni, nem neked. Bocsásd meg, és fordítsd a szívemet feléd a munkámban.": "Señor, confieso que hubo días en que trabajé solo para aparentar, o a medias. Quise agradar a las personas, no a ti. Perdóname y vuelve mi corazón hacia ti en mi trabajo.",
  "Olvasd el. Mint az Úrnak: ez az egyetlen szó megváltoztatja a hétfőt.": "Léelo. Como para el Señor: estas pocas palabras cambian tu lunes.",
  "Uram, amit ma teszek, azt neked teszem, nem embereknek. Ez a mondat megváltoztatja a hétfőmet. A legkisebb feladat is istentisztelet, ha neked végzem.": "Señor, lo que hago hoy lo hago para ti, no para las personas. Esta frase cambia mi lunes. Hasta la tarea más pequeña es adoración si la hago para ti.",
  "Hozd eléje a hét munkáját, a nehéz feladatot, és azokat, akikkel dolgozol.": "Trae delante de él el trabajo de la semana, la tarea difícil, y a las personas con las que trabajas.",
  "Uram, eléd hozom a hét munkáját és azt a feladatot, ami a legnehezebb lesz. Adj hozzá erőt és tiszta szándékot. Áldd meg azokat, akikkel együtt dolgozom, és add, hogy jó legyen velem dolgozni.": "Señor, traigo delante de ti el trabajo de esta semana y la tarea que será más difícil. Dame fuerza para ella y una intención limpia. Bendice a quienes trabajan conmigo, y haz que sea bueno trabajar conmigo.",
  "Csendben ajánld fel a napot neki.": "En silencio, ofrécele el día.",
  "Uram, ez a nap a tiéd. Lélekből, neked.": "Señor, este día es tuyo. De corazón, para ti.",
  "Békesség, amit a világ nem ad": "La paz que el mundo no da",
  "Köszönd meg azt a békességet, amit megéltél, amikor emberileg nem volt rá ok.": "Da gracias por la paz que viviste cuando, humanamente, no había motivo para ella.",
  "Uram, köszönöm azokat a pillanatokat, amikor békém volt, pedig emberileg nem volt rá ok. Az a te békességed volt, nem az enyém. Köszönöm, hogy nem a világtól függ.": "Señor, gracias por los momentos en que tuve paz aunque, humanamente, no había motivo para ella. Esa era tu paz, no la mía. Gracias porque no depende del mundo.",
  "Mi nyugtalanítja a szívedet? Mondd el, és valld meg, ha a békességet máshol kerested: a kontrollban, a zajban, a menekülésben.": "¿Qué inquieta tu corazón? Díselo, y confiésalo si buscaste la paz en otra parte: en el control, en el ruido, en la huida.",
  "Uram, megvallom, mi nyugtalanítja a szívemet, és azt is, hogy a békét máshol kerestem: a kontrollban, a zajban, a menekülésben. Nem tőled vártam. Bocsásd meg, és add vissza a békédet.": "Señor, te confieso lo que inquieta mi corazón, y también que busqué la paz en otra parte: en el control, en el ruido, en la huida. No la esperé de ti. Perdóname y devuélveme tu paz.",
  "Olvasd el. Nem úgy, ahogy a világ adja: ez a különbség.": "Léelo. No como el mundo la da: esa es la diferencia.",
  "Uram, te azt mondod, az én békességemet adom nektek, nem úgy, ahogy a világ adja. A világ békéje a baj hiánya, a tiéd a te jelenléted a bajban. Ezt kérem, nem a másikat.": "Señor, tú dices: mi paz os doy, no como el mundo la da. La paz del mundo es la ausencia de problemas; la tuya es tu presencia en medio de ellos. Esa es la que te pido, no la otra.",
  "Kérd a békességét egy konkrét helyzetre, ami most feszültséget okoz.": "Pide su paz para una situación concreta que ahora te causa tensión.",
  "Uram, van egy helyzet, ami most feszültséget okoz, és eléd hozom. Add bele a te békességedet, amit nem lehet elvenni. Ne nyugtalankodjék a szívem, és ne féljen.": "Señor, hay una situación que ahora me causa tensión, y la traigo delante de ti. Pon en ella tu paz, la que nadie puede quitar. Que no se turbe mi corazón, ni tenga miedo.",
  "Csendben fogadd el a békességét.": "En silencio, recibe su paz.",
  "Uram, elfogadom a békességedet. Csendben maradok benne.": "Señor, recibo tu paz. Me quedo en ella, en silencio.",
  "Lámpás az úton": "Lámpara en el camino",
  "Köszönd meg, hogy van Igéd, és hogy olvashatod, hallgathatod, amikor akarod.": "Da gracias porque tienes la Palabra de Dios, y puedes leerla y escucharla cuando quieras.",
  "Uram, köszönöm, hogy van Igéd, és hogy itt van nálam, olvashatom és hallgathatom, amikor akarom. Sokaknak ez nem adatott meg. Köszönöm, hogy szólsz rajta keresztül.": "Señor, gracias por tu Palabra, y porque la tengo aquí conmigo, para leerla y escucharla cuando quiera. A muchos no se les ha concedido esto. Gracias porque hablas a través de ella.",
  "Mikor tetted le az Igét, és indultál el a saját fényednél? Mondd el.": "¿Cuándo dejaste a un lado la Palabra y te pusiste en camino con tu propia luz? Díselo.",
  "Uram, megvallom, hogy sokszor letettem az Igédet, és a saját fényemnél indultam el. Aztán csodálkoztam, hogy sötét van. Bocsásd meg, és hozz vissza a lámpásodhoz.": "Señor, confieso que muchas veces dejé a un lado tu Palabra y me puse en camino con mi propia luz. Después me sorprendía de que estuviera oscuro. Perdóname y llévame de vuelta a tu lámpara.",
  "Olvasd el. A lámpás a következő lépést mutatja, nem az egész utat.": "Léelo. La lámpara muestra el siguiente paso, no todo el camino.",
  "Uram, a te Igéd lámpás a lábamnak. Nem az egész utat mutatja, csak a következő lépést, és ez elég. Taníts megelégedni annyi fénnyel, amennyit ma adsz.": "Señor, tu Palabra es lámpara a mis pies. No me muestra todo el camino, solo el siguiente paso, y eso basta. Enséñame a conformarme con la luz que me das hoy.",
  "Kérd, hogy egy konkrét kérdésben az Igéből kapj irányt, és hogy legyen időd olvasni a héten.": "Pide que la Palabra te dé dirección en una cuestión concreta, y tener tiempo para leer esta semana.",
  "Uram, van egy kérdés, amiben irányt várok, és kérem, hogy az Igéden keresztül szólj bele. Adj időt és csendet a héten, hogy olvassalak, ne csak kapkodjak. Legyen a te szavad az első, amit meghallok.": "Señor, hay una cuestión en la que espero dirección, y te pido que hables en ella a través de tu Palabra. Dame tiempo y calma esta semana para leer, no solo para correr de un lado a otro. Que tu palabra sea lo primero que oiga.",
  "Csendben hagyd, hogy a világosság rád essen.": "En silencio, deja que la luz caiga sobre ti.",
  "Uram, világíts az ösvényemre. Csendben követlek.": "Señor, alumbra mi sendero. Te sigo en silencio.",
  "Erősek az Úrban": "Fuertes en el Señor",
  "Köszönd meg, hogy a harc már eldőlt a kereszten, és te az ő erejében állsz.": "Da gracias porque la batalla ya se decidió en la cruz, y tú estás firme en su fuerza.",
  "Uram, köszönöm, hogy a döntő harcot te már megnyerted a kereszten. Nem én harcolok a győzelemért, hanem a győzelemből állok meg. Köszönöm a fegyverzetet, amit nem én gyártottam.": "Señor, gracias porque ya ganaste en la cruz la batalla decisiva. No lucho por la victoria; me mantengo firme desde la victoria. Gracias por la armadura que no fabriqué yo.",
  "Hol harcoltál emberek ellen, amikor nem ők voltak az igazi ellenség? Valld meg.": "¿Dónde luchaste contra personas cuando no eran ellas el verdadero enemigo? Confiésalo.",
  "Uram, megvallom, hogy emberek ellen harcoltam, pedig te azt mondod, nem test és vér ellen van a harcunk. Haraggal válaszoltam ott, ahol imádkozni kellett volna. Bocsásd meg, és nyisd meg a szememet.": "Señor, confieso que he luchado contra personas, aunque tú dices que nuestra lucha no es contra carne y sangre. Respondí con ira donde debía haber orado. Perdóname y abre mis ojos.",
  "Olvasd el. Erősek az Úrban, nem magunkban. Megállni, nem rohamozni.": "Léelo. Fuertes en el Señor, no en nosotros mismos. Mantenerse firmes, no lanzarse al asalto.",
  "Uram, te azt mondod, legyek erős az Úrban, a te hatalmas erődben, nem a magaméban. Felöltözöm, amit adsz: az igazságot, a hitet, a békesség evangéliumát. Nem rohamozok, megállok.": "Señor, tú me dices que me fortalezca en el Señor y en el poder de tu fuerza, no en la mía. Me revisto de lo que tú me das: la verdad, la fe, el evangelio de la paz. No me lanzo al asalto; me mantengo firme.",
  "Imádkozz közbenjárva: a családodért, hogy megálljanak, a gyülekezetedért, a kísértésben lévő testvéredért, és az üldözött keresztényekért.": "Ora intercediendo: por tu familia, para que se mantenga firme, por tu iglesia, por un hermano o una hermana que está en tentación, y por los cristianos perseguidos.",
  "Uram, imádkozom a családomért, hogy megálljanak a hitben, és te őrizd őket. Imádkozom a gyülekezetemért, hogy egy legyen és erős. Eléd hozom azt a testvéremet, akiről tudom, hogy kísértésben van: tarts meg őt. És imádkozom az üldözött keresztényekért a világban, hogy hűek maradjanak, és te légy nekik pajzs.": "Señor, oro por mi familia, para que se mantenga firme en la fe, y que tú la guardes. Oro por mi iglesia, para que esté unida y sea fuerte. Traigo delante de ti a ese hermano o esa hermana que sé que está en tentación: sostenlo firme. Y oro por los cristianos perseguidos en el mundo, para que permanezcan fieles, y que tú seas su escudo.",
  "Csendben állj meg az ő erejében.": "En silencio, mantente firme en su fuerza.",
  "Uram, a te erődben állok. Megállok, és te tartasz.": "Señor, estoy en tu fuerza. Me mantengo firme, y tú me sostienes.",
  "Minden reggel megújul": "Nuevas cada mañana",
  "A hála napja. Köszönd meg a hét minden reggelét, hogy felkelhettél, és azt, hogy ő minden reggel ugyanaz volt.": "El día de la gratitud. Da gracias por cada mañana de la semana, porque pudiste levantarte, y porque él fue el mismo cada mañana.",
  "Uram, köszönöm a hét minden reggelét, hogy felkelhettem, és hogy te minden reggel ugyanaz voltál. Köszönöm a kegyelmedet, ami nem fogyott el, pedig én sokszor elfogytam. Nagy a te hűséged.": "Señor, gracias por cada mañana de esta semana, porque pude levantarme, y porque tú fuiste el mismo cada mañana. Gracias por tu misericordia, que no se agotó, aunque yo muchas veces me agoté. Grande es tu fidelidad.",
  "Hol kételkedtél a hűségében a héten, mert a körülmény mást mondott? Mondd el.": "¿Dónde dudaste de su fidelidad esta semana porque las circunstancias decían otra cosa? Díselo.",
  "Uram, megvallom, hogy voltak percek a héten, amikor a körülmény mást mondott, mint te, és én a körülménynek hittem. Kételkedtem a hűségedben. Bocsásd meg, te hű maradtál akkor is.": "Señor, confieso que hubo momentos esta semana en que las circunstancias decían otra cosa que tú, y creí a las circunstancias. Dudé de tu fidelidad. Perdóname; tú seguiste siendo fiel también entonces.",
  "Olvasd el. Ez a mondat romok közül hangzik, ezért igaz a te romjaid közt is.": "Léelo. Estas palabras se pronunciaron entre ruinas; por eso son verdad también entre tus ruinas.",
  "Uram, ezt a mondatot valaki romok közt mondta ki, és azért igaz az én romjaim közt is. A te irgalmad nem fogyatkozik el, minden reggel megújul. Erre építem a következő reggelt is.": "Señor, alguien pronunció estas palabras entre ruinas, y por eso son verdad también entre mis ruinas. Tus misericordias nunca se acaban; son nuevas cada mañana. Sobre esto edifico también la próxima mañana.",
  "Kérd, hogy az ő hűsége legyen az, amire a hétvégén építesz, és nem a saját hangulatod.": "Pide que sea su fidelidad, y no tu propio estado de ánimo, lo que te sostenga este fin de semana.",
  "Uram, add, hogy a hétvégén a te hűségedre építsek, ne a hangulatomra. Újítsd meg a kegyelmedet a holnapi reggelre is, és add, hogy észrevegyem. Te vagy az, akiben nincs változás.": "Señor, ayúdame a apoyarme este fin de semana en tu fidelidad, no en mi estado de ánimo. Renueva tu misericordia también para mañana por la mañana, y ayúdame a notarla. Tú eres aquel en quien no hay cambio.",
  "Csendben nyugodj meg a hűségében.": "En silencio, descansa en su fidelidad.",
  "Uram, nagy a te hűséged. Ebben nyugszom meg.": "Señor, grande es tu fidelidad. En ella descanso.",
  "Aki elkezdte, elvégzi": "El que comenzó la obra la terminará",
  "Nézz vissza az elmúlt négy hétre. Köszönd meg, amit Isten elkezdett benned, akkor is, ha még nincs kész.": "Mira atrás a las últimas cuatro semanas. Da gracias por lo que Dios ha comenzado en ti, aunque todavía no esté terminado.",
  "Uram, visszanézek az elmúlt hetekre, és köszönöm, amit elkezdtél bennem. Nincs kész, de elkezdted, és ez a tiéd. Köszönöm, hogy nem hagytad abba, amikor én abbahagytam volna.": "Señor, miro atrás a las últimas semanas, y te doy gracias por lo que has comenzado en mí. No está terminado, pero tú lo comenzaste, y es tuyo. Gracias por no detenerte cuando yo me habría detenido.",
  "Hol adtad fel magad, mintha a befejezés rajtad állna? Valld meg.": "¿Dónde te diste por vencido, como si terminarlo dependiera de ti? Confiésalo.",
  "Uram, megvallom, hogy voltak percek, amikor feladtam magamat, mintha a befejezés rajtam állna. Elfelejtettem, hogy a munka a tiéd. Bocsásd meg, és emeld fel újra a fejemet.": "Señor, confieso que hubo momentos en que me di por vencido, como si terminarlo dependiera de mí. Olvidé que la obra es tuya. Perdóname y vuelve a levantar mi cabeza.",
  "Olvasd el lassan. Aki elkezdte, az végzi el. Nem te.": "Léelo despacio. El que la comenzó la terminará. No tú.",
  "Uram, te kezdted el bennem a jó dolgot, és te végzed el a Krisztus Jézus napjáig. Nem én tartom magam a kezedben, te tartasz engem. Ebben a bizonyosságban zárom a hetet.": "Señor, tú comenzaste en mí la buena obra, y la perfeccionarás hasta el día de Cristo Jesús. No soy yo quien me sostengo en tu mano; eres tú quien me sostiene. Con esta certeza cierro la semana.",
  "Kérd, hogy a következő hetekben is folytassa benned a munkáját, és nevezd meg, hol szeretnél növekedni.": "Pídele que siga su obra en ti en las próximas semanas, y nombra en qué te gustaría crecer.",
  "Uram, folytasd bennem a munkádat a következő hetekben is. Tudom, hol szeretnék növekedni, és eléd hozom, de rád bízom, hogy mit és milyen sorrendben formálsz. A te időd a jó idő.": "Señor, sigue tu obra en mí en las próximas semanas. Sé en qué me gustaría crecer, y lo traigo delante de ti, pero dejo en tus manos qué formas y en qué orden. Tu tiempo es el buen tiempo.",
  "Pihenj csendben abban, hogy Isten keze van rajtad, és ő nem engedi el.": "Descansa en silencio sabiendo que la mano de Dios está sobre ti, y que él no te soltará.",
  "Uram, a te kezed van rajtam, és te nem engedsz el. Csendben megpihenek ebben. Ámen.": "Señor, tu mano está sobre mí, y no me soltarás. En silencio descanso en esto. Amén.",
  "Most emeld fel a tekintetedet a saját ügyeidről a világra. Ezek az események most történnek, és ott emberek vannak.": "Ahora levanta la mirada de tus propios asuntos hacia el mundo. Estos sucesos están ocurriendo ahora, y allí hay personas.",
  "Uram, most nem magamért kérek, hanem azokért, akiket nem ismerek, de te igen. Eléd hozom a világ bajait, amik ma történnek.": "Señor, ahora no pido por mí, sino por quienes yo no conozco, pero tú sí. Traigo delante de ti las desgracias del mundo que están ocurriendo hoy.",
  "Uram, te vagy a mi oltalmunk és erősségünk, bizonyos segítség a nyomorúságban. Hadd legyél az nekik is ma. Ámen.": "Señor, tú eres nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones. Sé eso también para ellos hoy. Amén.",
  "Most nem tudjuk, mi történik épp a világban, de valahol most is baj van. Imádkozz azokért, akikről ma nem szól a hír.": "Ahora mismo no sabemos qué está pasando en el mundo, pero en algún lugar también ahora hay desgracia. Ora por aquellos de quienes hoy no hablan las noticias.",
  "Uram, nem tudom, hol van ma a legnagyobb baj a világon, de te tudod. Eléd hozom azokat, akik ebben az órában földrengésben, árvízben, tűzben vagy háborúban vannak, és akikről nem szól a hír. Légy az oltalmuk, adj nekik segítséget és vigaszt, és fordítsd a világ szívét a béke felé. Te vagy a mi oltalmunk és erősségünk, bizonyos segítség a nyomorúságban. Ámen.": "Señor, no sé dónde está hoy la mayor desgracia del mundo, pero tú lo sabes. Traigo delante de ti a quienes en esta hora están en medio de un terremoto, una inundación, un incendio o una guerra, y a aquellos de quienes no hablan las noticias. Sé su amparo, dales ayuda y consuelo, y vuelve el corazón del mundo hacia la paz. Tú eres nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones. Amén.",
  // Imádság a világért, per event (Énok, ima-vilag-rovid.json, owner 2026-11-02 TG 33947-33954): encouragement + prayer, news labels
  "Amikor a föld megrendül, Isten nem rendül meg. Az imád most valódi kéz lehet a romok fölött.": "Cuando la tierra tiembla, Dios no tiembla. Tu oración puede ser ahora una mano real sobre los escombros.",
  "A víz gyorsabb az embernél, de nem gyorsabb Istennél. Egy mondat most életet menthet.": "El agua es más rápida que el hombre, pero no más que Dios. Una frase ahora puede salvar una vida.",
  "A tűz nem kérdez, de Isten hall. Állj oda imádságban azok mellé, akik most mindent hátrahagynak.": "El fuego no pregunta, pero Dios escucha. Ponte en oración junto a quienes ahora lo dejan todo atrás.",
  "Isten megígérte, hogy a víz nem lesz úr a földön. Kérd ezt most azoknak, akiknek mindent elvisz.": "Dios prometió que el agua no dominaría la tierra. Pídelo ahora por aquellos a quienes se lo lleva todo.",
  "Jézus egy szóval elcsendesítette a vihart. Ugyanez a szó ma is érvényes, mondd ki értük.": "Jesús calmó la tormenta con una palabra. Esa palabra sigue vigente hoy; pronúnciala por ellos.",
  "A hegyek Isten kezében vannak. Imádkozz, hogy az emberek időben induljanak, és legyen hová menniük.": "Los montes están en la mano de Dios. Ora para que la gente salga a tiempo y tenga adónde ir.",
  "Az aszály csendes baj, ritkán szól róla a hír. Te most mégis eléje viheted Istennek.": "La sequía es una desgracia silenciosa, rara vez en las noticias. Aun así, puedes llevarla ahora ante Dios.",
  "Jézus gyógyító keze ma sem rövidült meg. Állj oda a betegek és az ápolók mellé.": "La mano sanadora de Jesús no se ha acortado hoy. Ponte al lado de los enfermos y de quienes los cuidan.",
  "Isten nem áll be egyik tömegbe sem, mindkét oldalon az övéit látja. Imádkozz oldal nélkül, békéért.": "Dios no se une a ninguna multitud; ve a los suyos en ambos lados. Ora por la paz sin tomar partido.",
  "Boldogok a békességre igyekezők. Az imád ma ott lehet, ahová senki más nem jut el.": "Bienaventurados los pacificadores. Tu oración hoy puede llegar adonde nadie más llega.",
  "Uram, légy {hely} romjai alatt a várakozókkal, adj erőt a mentőknek, és vigasztald a gyászolókat.": "Señor, acompaña a quienes esperan bajo los escombros en {hely}, da fuerza a los rescatistas y consuela a los que lloran.",
  "Uram, tartsd vissza a vizet, és vezesd időben magaslatra a part lakóit.": "Señor, detén el agua y guía a tiempo a los habitantes de la costa hacia lugares altos.",
  "Uram, védd meg {hely} menekülőit és tűzoltóit, és küldj esőt a lángokra.": "Señor, protege a los que huyen y a los bomberos en {hely}, y envía lluvia sobre las llamas.",
  "Uram, őrizd meg {hely} lakóinak életét, és adj menedéket azoknak, akiknek otthona víz alatt áll.": "Señor, guarda la vida de los habitantes de {hely} y da refugio a quienes tienen su hogar bajo el agua.",
  "Uram, csendesítsd le a szelet és a vizet {hely} fölött, ahogy a tanítványaid hajóján tetted.": "Señor, calma el viento y el agua sobre {hely}, como lo hiciste en la barca de tus discípulos.",
  "Uram, vezesd biztonságba {hely} lakóit, és adj bölcsességet azoknak, akik a kitelepítésről döntenek.": "Señor, lleva a salvo a los habitantes de {hely} y da sabiduría a quienes deciden la evacuación.",
  "Uram, adj esőt {hely} földjére és kenyeret az asztalukra, és nyisd meg a bővölködők kezét.": "Señor, da lluvia a la tierra de {hely} y pan a su mesa, y abre las manos de los que tienen en abundancia.",
  "Uram, gyógyítsd {hely} betegeit, és adj erőt és védelmet az orvosoknak és ápolóknak.": "Señor, sana a los enfermos de {hely} y da fuerza y protección a los médicos y enfermeros.",
  "Uram, őrizd meg {hely} életeit mindkét oldalon, és fordítsd a szíveket a béke felé.": "Señor, guarda las vidas en {hely} de todos los lados, y vuelve los corazones hacia la paz.",
  "Uram, védd meg {hely} civiljeit és gyermekeit, gyógyítsd a sebesülteket, és adj békét, bármelyik oldalon állnak.": "Señor, protege a los civiles y a los niños de {hely}, sana a los heridos y da paz, estén del lado que estén.",
  "Érintett terület": "Superficie afectada",
  "Legnagyobb szélsebesség": "Velocidad máxima del viento",
  "Események": "Sucesos",
  "Halálos áldozatok": "Muertes",
  "Időszak": "Periodo",
  "Egy földrengés után órák döntenek életekről. Imádkozz a romok alatt lévőkért és a mentőkért.": "Después de un terremoto, unas horas deciden sobre muchas vidas. Ora por quienes están bajo los escombros y por los rescatistas.",
  "Uram, eléd hozom {hely} területét, ahol megrendült a föld. Légy azokkal, akik a romok alatt várnak, és adj erőt és gyorsaságot azoknak, akik keresik őket. Vigasztald, aki ma elveszített valakit, és adj fedelet annak, akinek nem maradt.": "Señor, traigo delante de ti la región de {hely}, donde ha temblado la tierra. Acompaña a quienes esperan bajo los escombros, y da fuerza y rapidez a quienes los buscan. Consuela a quien hoy ha perdido a alguien, y da un techo a quien se ha quedado sin él.",
  "A tűz otthonokat, erdőket és életeket visz el. Imádkozz a menekülőkért és a tűzoltókért.": "El fuego se lleva hogares, bosques y vidas. Ora por quienes huyen y por los bomberos.",
  "Uram, eléd hozom {hely} területét, ahol tűz pusztít. Védd meg azokat, akik menekülnek, és add, hogy mindenkit elérjen a figyelmeztetés időben. Adj erőt és védelmet a tűzoltóknak, és küldj esőt és szelet úgy, ahogy csak te tudod.": "Señor, traigo delante de ti la región de {hely}, donde el fuego está arrasando. Protege a quienes huyen, y haz que el aviso llegue a todos a tiempo. Da fuerza y protección a los bomberos, y envía lluvia y viento como solo tú sabes hacerlo.",
  "Az árvíz lassan jön, és mindent elvisz. Imádkozz azokért, akik az otthonukat látják eltűnni.": "La inundación llega despacio y se lo lleva todo. Ora por quienes ven desaparecer su hogar.",
  "Uram, eléd hozom {hely} lakóit, akiket elért a víz. Őrizd meg az életüket, és adj menedéket azoknak, akiknek az otthona víz alatt áll. Légy a gyerekekkel és az idősekkel, akik nem tudnak maguktól menekülni, és adj türelmet és erőt a visszatéréshez.": "Señor, traigo delante de ti a la gente de {hely}, a quienes ha alcanzado el agua. Guarda sus vidas, y da refugio a quienes tienen su hogar bajo el agua. Acompaña a los niños y a los ancianos que no pueden huir por sí mismos, y da paciencia y fuerza para el regreso.",
  "A vihar előtt a várakozás, utána a kár. Imádkozz az útjában lévőkért.": "Antes de la tormenta, la espera; después, los daños. Ora por quienes están en su camino.",
  "Uram, eléd hozom {hely} területét, amerre a vihar tart vagy ahol már lecsapott. Csendesítsd a szelet és a vizet, ahogy a tanítványaid hajóján tetted. Védd meg azokat, akik az útjában állnak, és adj gyors segítséget, ahol a tetők és a falak már leomlottak.": "Señor, traigo delante de ti la región de {hely}, hacia donde se dirige la tormenta o donde ya ha golpeado. Calma el viento y las aguas, como lo hiciste en la barca de tus discípulos. Protege a quienes están en su camino, y envía ayuda rápida donde los techos y las paredes ya se han derrumbado.",
  "A hamu és a láva elől menekülni kell. Imádkozz a környék falvaiért és a kitelepítettekért.": "Hay que huir de la ceniza y de la lava. Ora por los pueblos de los alrededores y por los evacuados.",
  "Uram, eléd hozom {hely} környékét, ahol a hegy kitört. Védd meg a falvakat és a városokat a láva és a hamu útjából, és adj bölcsességet azoknak, akik a kitelepítésről döntenek. Légy azokkal, akik mindent otthagytak, és adj nekik helyet, ahol megpihenhetnek.": "Señor, traigo delante de ti los alrededores de {hely}, donde ha entrado en erupción la montaña. Protege los pueblos y las ciudades del paso de la lava y la ceniza, y da sabiduría a quienes deciden sobre la evacuación. Acompaña a quienes lo han dejado todo atrás, y dales un lugar donde puedan descansar.",
  "Az aszály csendes katasztrófa, nincs hírverése. Imádkozz az éhezőkért és a földművesekért.": "La sequía es una catástrofe silenciosa, sin titulares. Ora por los que pasan hambre y por los agricultores.",
  "Uram, eléd hozom {hely} lakóit, ahol kiszáradt a föld, és nincs mit enni. Adj esőt a földre és kenyeret az asztalra, és nyisd meg azok kezét, akiknek bőven van. Tartsd meg a gyerekeket, és adj reményt a földműveseknek, akik újra vetnek.": "Señor, traigo delante de ti a la gente de {hely}, donde la tierra se ha secado y no hay qué comer. Da lluvia a la tierra y pan a la mesa, y abre las manos de quienes tienen en abundancia. Sostén a los niños, y da esperanza a los agricultores que vuelven a sembrar.",
  "A háborúban mindkét oldalon emberek halnak meg. Imádkozz a civilekért, a sebesültekért és a békéért, oldal nélkül.": "En la guerra muere gente en ambos bandos. Ora por los civiles, por los heridos y por la paz, sin tomar partido.",
  "Uram, eléd hozom {hely} területét, ahol fegyverek szólnak. Védd meg a civileket, a gyerekeket, az öregeket és azokat, akiknek nincs hová menniük. Gyógyítsd a sebesülteket, vigasztald a gyászolókat, és fordítsd a döntéshozók szívét a béke felé, bármelyik oldalon állnak. Te vagy a békesség Istene, hadd legyen béke ott is.": "Señor, traigo delante de ti la región de {hely}, donde hablan las armas. Protege a los civiles, a los niños, a los ancianos y a quienes no tienen adónde ir. Sana a los heridos, consuela a los que lloran, y vuelve hacia la paz el corazón de quienes toman las decisiones, estén del lado que estén. Tú eres el Dios de paz; que haya paz también allí.",
  "Ahol tömegek feszülnek egymásnak, ott félelem és harag van mindkét oldalon. Imádkozz békéért és józanságért, oldal nélkül.": "Donde las multitudes se enfrentan, hay miedo e ira en ambos lados. Ora por la paz y la sensatez, sin tomar partido.",
  "Uram, eléd hozom {hely} területét, ahol feszültség és zavargás van az utcákon. Csendesítsd a haragot, és őrizd meg az életeket, azokét is, akik tüntetnek, és azokét is, akik rendet tartanak. Adj józanságot azoknak, akik döntenek, és add, hogy a sérelmek ne vérrel, hanem szóval oldódjanak meg.": "Señor, traigo delante de ti la región de {hely}, donde hay tensión y disturbios en las calles. Calma la ira, y guarda las vidas, tanto de quienes protestan como de quienes mantienen el orden. Da sensatez a quienes deciden, y haz que los agravios se resuelvan con palabras, no con sangre.",
  "A járványban a betegek és az ápolók egyformán kimerülnek. Imádkozz gyógyulásért és kitartásért.": "En una epidemia, los enfermos y quienes los cuidan se agotan por igual. Ora por sanidad y perseverancia.",
  "Uram, eléd hozom {hely} lakóit, ahol betegség terjed. Gyógyítsd a betegeket, és állítsd meg a terjedést, ahogy csak te tudod. Adj erőt és védelmet az orvosoknak és az ápolóknak, akik nem mennek haza, és vigasztald azokat, akik már elveszítettek valakit.": "Señor, traigo delante de ti a la gente de {hely}, donde se propaga una enfermedad. Sana a los enfermos, y detén la propagación, como solo tú puedes hacerlo. Da fuerza y protección a los médicos y al personal de enfermería que no vuelven a casa, y consuela a quienes ya han perdido a alguien.",
  "Nem tudjuk pontosan, mi történik ott, de Isten tudja. Imádkozz azokért, akik benne vannak.": "No sabemos exactamente qué está pasando allí, pero Dios lo sabe. Ora por quienes están en medio de ello.",
  "Uram, eléd hozom {hely} területét, ahol most baj van, és nem is tudom pontosan, milyen. Te tudod, és te látod minden embert ott. Légy velük, védd meg az életüket, és küldj segítséget időben.": "Señor, traigo delante de ti la región de {hely}, donde ahora hay una desgracia, y ni siquiera sé exactamente de qué clase. Tú lo sabes, y ves a cada persona allí. Acompáñalos, protege sus vidas, y envía ayuda a tiempo.",
});

