// ===== 2026-11-08 what's-new history v43.464 and older (Thomas 30526, card 4f0b74b5; owner TG 36991 'nem marad ki semmi') =====
Object.assign(window.PP_FORD_SZOTAR.es, {
  "Térkép: a magyar rádióamatőr átjátszók (HA2TO listája) a Rádióamatőr átjátszók rétegben; a rétegek neve a választott nyelven jelenik meg.": "Mapa: los repetidores húngaros de radioaficionado (lista de HA2TO) en la capa Repetidores de radioaficionado; los nombres de las capas aparecen en el idioma elegido.",
  "LoRa-szoba: Meshtastic®-kompatibilis nyilvános csatorna LoRa vevőegységgel, Bluetooth-on; egység nélkül tájékoztatót mutat.": "Sala LoRa: canal público compatible con Meshtastic® con una unidad LoRa, por Bluetooth; sin unidad muestra una explicación.",
  "Rezgés: Finom vagy Erős koppanás választható a Beállításokban, a Bibliában is.": "Vibración: en Ajustes puedes elegir Toque suave o Toque fuerte, también en la Biblia.",
  "Biblia: a felolvasás belépés nélkül is azonnal elindul a telefon hangján, és a versek között alapból nincs szünet.": "Biblia: la lectura en voz alta arranca al instante con la voz del teléfono, también sin iniciar sesión, y por defecto no hay pausa entre versículos.",
  "Biblia: Samuel választásakor csak a már kész könyvek szólnak; az ébresztő a még nem kész könyvet Mihály vagy Imre hangján olvassa.": "Biblia: al elegir a Samuel solo suenan los libros ya terminados; la alarma lee un libro aún no terminado con la voz de Mihály o Imre.",
  "Biblia: ujjal pöckölve a lap azonnal mozdul, és lendülettel gördül tovább.": "Biblia: al deslizar con el dedo, la página se mueve al instante y sigue desplazándose con impulso.",
  "Igetanuló: a kiválasztott igék nyomtatható kártyákra kerülnek (PDF), vágójelekkel.": "Memorizador de versículos: los versículos elegidos se imprimen en tarjetas (PDF), con marcas de corte.",
  "Tablet: a jegyzet a Biblia mellett nyílik meg; a Noé bárkája és a kirakós elfér a képernyőn.": "Tableta: la nota se abre junto a la Biblia; El arca de Noé y el rompecabezas caben en la pantalla.",
  "Helyi szobák: üzenetszerkesztés Mégse gombbal, a vissza gomb csak a szerkesztésből lép ki.": "Salas locales: edición de mensajes con botón Cancelar; el botón Atrás solo sale de la edición.",
  "Gerah: saját magadnak nem küldhetsz Gerah-t.": "Gerah: no puedes enviarte Gerah a ti mismo.",
  "Biblia: új felolvasó hang, Samuel, Imre és Mihály mellett külön választható; azokban a könyvekben szól, amelyek már elkészültek az ő hangján.": "Biblia: nueva voz de lectura, Samuel, que se puede elegir aparte junto a Imre y Mihály; suena en los libros que ya están terminados con su voz.",
  "Kezdőlap: a Biblia- és a játékcsempék képei akkor is betöltődnek, ha a telefon egy helyi (Bluetooth) szobához kapcsolódik.": "Inicio: las imágenes de los mosaicos de la Biblia y de los juegos se cargan también cuando el teléfono está conectado a una sala local (Bluetooth).",
  "Rezgés: azokon a telefonokon, amelyek a finom koppintást nem érzékeltetik, erősebb és hosszabb rezgés jelzi az érintést.": "Vibración: en los teléfonos que no reproducen el toque suave, una vibración más fuerte y larga indica el toque.",
  "Biblia: a napi időbe csak az olvasás és a felolvasás hallgatása számít bele, a jegyzetírás és a keresés nem.": "Biblia: en el tiempo diario solo cuentan la lectura y la escucha de la lectura en voz alta, no la escritura de notas ni la búsqueda.",
  "Play-ből telepített app: a Frissítés keresése gomb minden megnyomásra megkérdezi a Play áruházat, és ha van újabb változat, azonnal felajánlja.": "App instalada desde Play: el botón Buscar actualización consulta la Play Store cada vez que lo pulsas y, si hay una versión nueva, la ofrece al instante.",
  "Az app nem záródik be, ha a belső böngészője leáll (például a térképnél): újratölti a lapot, az adatok megmaradnak.": "La app no se cierra si su navegador interno se detiene (por ejemplo, en el mapa): recarga la página y los datos se conservan.",
  "Gerah: a még átadásra váró küldés visszavonható, az összeg visszakerül az egyenlegre; a jóváírás ajánlókód nélkül is megérkezik a fiók saját tárcájára.": "Gerah: un envío pendiente de entrega se puede cancelar y el importe vuelve al saldo; el abono llega al monedero propio de la cuenta también sin código de referido.",
  "Szobák: a később belépett tag is megtudja, hogy Gerah-szobában van, így neki is lehet a szobán át Gerah-t küldeni.": "Salas: un miembro que entra más tarde también sabe que está en una sala Gerah, así que también se le puede enviar Gerah a través de la sala.",
  "Szobák: kihívó kép (például fürdőruhás vagy fehérneműs) sem tölthető fel szoba- vagy profilképnek.": "Salas: tampoco se pueden subir imágenes provocativas (por ejemplo, en bañador o ropa interior) como imagen de sala o de perfil.",
  "Imacsengő: saját oldalon, mozgó háttérrel: a szentek imája füstként száll fel a csillagos égbe.": "Campana de oración: página propia con fondo animado: la oración de los santos sube como humo al cielo estrellado.",
  "Noé bárkája: minden pár egy hím és egy nőstény állat: a nőstény oroszlánnak nincs sörénye, a többi nőstényen masni van.": "El arca de Noé: cada pareja es un macho y una hembra: la leona no tiene melena y las demás hembras llevan un lazo.",
  "Játékok: a hangszóró gombbal le lehet némítani a játékokat. Némítva áthúzott hangszóró látszik, és nem szól sem a beszéd, sem a taps.": "Juegos: con el botón del altavoz puedes silenciar los juegos. En silencio se ve un altavoz tachado y no suenan ni la voz ni los aplausos.",
  "Memóriajáték: keskeny telefonon sem csúszik oldalra, és a kártyák görgetés nélkül a képernyőn maradnak.": "Juego de memoria: tampoco se desplaza hacia un lado en teléfonos estrechos, y las cartas quedan en la pantalla sin desplazarse.",
  "Gerah: egy már jóváírt nap nem szakítja meg a heti letétet; a heti kifizetés napján az érme a teljes kifizetett összeget mutatja.": "Gerah: un día ya abonado no interrumpe el depósito semanal; el día del pago semanal, la moneda muestra el importe total pagado.",
  "Szobák: a törölt szoba nem jön vissza a Vissza gombbal; az új belépési kérelem azonnal megjelenik a szoba beállításainál, az app visszatérésekor is; az elutasított tag a valódi választ látja.": "Salas: una sala eliminada no vuelve con el botón Atrás; una nueva solicitud de entrada aparece al instante en los ajustes de la sala, también al volver a la app; el miembro rechazado ve la respuesta real.",
  "Szobák: a szoba- és profilképeket a szerver ellenőrzi, szexuális tartalmú kép nem tölthető fel.": "Salas: el servidor revisa las imágenes de sala y de perfil; no se pueden subir imágenes de contenido sexual.",
  "Szobák: a névmegadás, a belépési kérelem, a sürgős üzenet és a riasztás értesítése a telefon nyelvén jelenik meg.": "Salas: el nombre, la solicitud de entrada, el mensaje urgente y la notificación de alarma aparecen en el idioma del teléfono.",
  "Kezdőlap: a csempére koppintva mindig a megérintett csempe nyílik meg; a készletmérők rövid felirata minden nyelven helyes.": "Inicio: al tocar un mosaico siempre se abre el mosaico tocado; la etiqueta corta de los indicadores de reservas es correcta en todos los idiomas.",
  "Biblia: a felolvasás fénye újra szavanként villan fel; új próféciacsoportok; a letöltőoldal a felajánlott fordítást mutatja.": "Biblia: la luz de la lectura en voz alta vuelve a destellar palabra por palabra; nuevos grupos de profecías; la página de descarga muestra la traducción ofrecida.",
  "Kalauzok: egy nyitott kalauz alatt is megnyílik a megérintett menüpont, és a kalauz nem takarja el a névmegadást.": "Guías: con una guía abierta también se abre el elemento de menú tocado, y la guía no tapa la introducción del nombre.",
  "Gerah: ha a napi célt a PrepperPapa és a Wordlight együtt, a fiókon át összeadott idővel éred el, a napi Gerah is jár (eddig csak a gratuláció jött meg).": "Gerah: si alcanzas la meta diaria con el tiempo sumado de PrepperPapa y Wordlight a través de la cuenta, también recibes el Gerah diario (hasta ahora solo llegaba la felicitación).",
  "Biblia: felolvasáskor a fény betűről betűre fut végig az éppen kimondott szón, az elöl haladó betű izzik, utána lassan halványul el.": "Biblia: durante la lectura en voz alta, la luz recorre letra a letra la palabra que se pronuncia; la letra de delante brilla y luego se desvanece lentamente.",
  "Ima: a vezetett ima az igeverset a hivatkozás nélkül olvassa fel.": "Oración: la oración guiada lee el versículo sin la cita.",
  "Wordlight: ha a PrepperPapa nincs a telefonon, a napi cél gratulációja minden Gerah-napon felajánlja a napi Gerah-t a PrepperPapa letöltésével.": "Wordlight: si PrepperPapa no está en el teléfono, la felicitación de la meta diaria ofrece cada día de Gerah el Gerah diario descargando PrepperPapa.",
  "Olvasási terv: a tervnapokért már nem jár Gerah, a terv végigolvasásakor jár ráadás; a terv szövegei ezt mondják.": "Plan de lectura: los días del plan ya no dan Gerah; al terminar el plan recibes un extra; los textos del plan lo indican.",
  "Javítások: a napi cél gratulációs lapján a gomb és a link tördelése; a helyi szobák keresése internet nélkül sem ír hibát.": "Correcciones: el ajuste del botón y del enlace en la página de felicitación de la meta diaria; la búsqueda de salas locales no da error sin internet.",
  "Újratelepítés után a telefon ugyanaz a készülék marad: nem foglal új helyet a készülékkeretben, és a szobák nem zárolódnak.": "Tras reinstalar, el teléfono sigue siendo el mismo dispositivo: no ocupa una plaza nueva en el límite de dispositivos y las salas no se bloquean.",
  "Első indítás: a menüsor bemutatója minden nyelven a helyes gombokra mutat, és nem jön elé hirdetés vagy értesítési kérdés; az értesítést belépés és a bemutató után kéri.": "Primer inicio: la presentación de la barra de menú señala los botones correctos en todos los idiomas, y no aparece antes un anuncio ni la pregunta de notificaciones; las notificaciones se piden tras iniciar sesión y después de la presentación.",
  "Wordlight: első indításkor megjelenik a Biblia súgója; az Elhivatottság oldal csak akkor kéri a PrepperPapa telepítését, ha nincs fent.": "Wordlight: en el primer inicio aparece la ayuda de la Biblia; la página Constancia solo pide instalar PrepperPapa si no está instalada.",
  "Bemutató-adatok: az autónak, a hétvégi háznak és a rejteknek is van készlete, a családtagoknak vészhelyzeti kapcsolattartója; a kezdőlapról a betöltés helyben történik.": "Datos de demostración: el coche, la casa de fin de semana y el escondite también tienen reservas, y los familiares un contacto de emergencia; desde el inicio la carga se hace en el sitio.",
  "Egy képernyőn legfeljebb egy hirdetés-kártya; a térkép súgója a Térkép-funkciók gombra mutat.": "Como máximo una tarjeta de anuncio por pantalla; la ayuda del mapa señala el botón Funciones del mapa.",
  "Megváltozott az adatkezelési tájékoztató (3.1 Készülékeid): erről egyszer szól az app, a tájékoztató linkjével.": "Ha cambiado la política de privacidad (3.1 Tus dispositivos): la app te avisa una vez, con el enlace a la política.",
  "Biblia: a PrepperPapa és a Wordlight ugyanazon a telefonon közösen használja a jegyzeteket, címkéket, kiemeléseket, könyvjelzőket, az olvasási előzményt és terveket, az Igetanulót, a játékokat, az imatémákat, a megjelenítési beállításokat és a napi célt. Az első indításkor a két app adatai összeadódnak.": "Biblia: PrepperPapa y Wordlight comparten en el mismo teléfono las notas, etiquetas, resaltados, marcadores, el historial y los planes de lectura, el Memorizador de versículos, los juegos, los motivos de oración, los ajustes de visualización y la meta diaria. En el primer inicio se suman los datos de las dos apps.",
  "Biblia: a napi idő az Igével appváltáskor azonnal átkerül a másik appba.": "Biblia: el Tiempo diario con la Palabra pasa al instante a la otra app al cambiar de app.",
  "Biblia: a háttérzene alapból hangosabban (70%-on) szól.": "Biblia: la música de fondo suena por defecto más alta (al 70%).",
  "Android: induláskor az app nem kér el egyszerre minden engedélyt; a kamerát, mikrofont, helyet és Bluetooth-t akkor kéri, amikor az adott funkciót használod.": "Android: al iniciar, la app no pide todos los permisos a la vez; pide la cámara, el micrófono, la ubicación y el Bluetooth cuando usas la función correspondiente.",
  "Javítások: a helyi szobák Bluetooth-sora minden nyelven lefordítva; a saját térkép újraépítéskor nem ürül ki azonnal.": "Correcciones: la línea de Bluetooth de las salas locales está traducida en todos los idiomas; el mapa propio no se vacía al instante al reconstruirse.",
  "Gerah: ha a telefonon a régi tesztelői PrepperPapa app is fent van, az áruházi app felajánlja a régi Gerah-tárca átvételét, ugyanazzal az azonosítóval, egyenleggel és a még függő fizetésekkel. Ehhez egyszer nyisd meg a régi appot, utána az újat.": "Gerah: si en el teléfono también está la antigua app PrepperPapa de pruebas, la app de la tienda ofrece traspasar el antiguo monedero Gerah, con el mismo identificador, saldo y pagos pendientes. Para ello abre una vez la app antigua y después la nueva.",
  "Biblia: a PrepperPapa és a Wordlight ugyanazon a telefonon közösen használja a letöltött Biblia-hangokat, imahangokat és fordításokat, nem kell kétszer letölteni.": "Biblia: PrepperPapa y Wordlight comparten en el mismo teléfono las voces de la Biblia, las voces de oración y las traducciones descargadas; no hay que descargarlas dos veces.",
  "Biblia: a felolvasás alapból zenével indul; ha még nincs letöltött zene, az első lejátszáskor letölti.": "Biblia: la lectura en voz alta empieza por defecto con música; si aún no hay música descargada, la descarga en la primera reproducción.",
  "Szobák: a tagok listájában egy tagra koppintva a Gerah küldése is elérhető.": "Salas: en la lista de miembros, al tocar un miembro también puedes enviarle Gerah.",
  "Javítások: Androidon a térkép megnyitása nem omlik össze, ha egy korábbi térképletöltés félbemaradt.": "Correcciones: en Android, abrir el mapa ya no falla si una descarga de mapa anterior quedó a medias.",
  "Ima-segéd: az ige után csend marad az imádkozásra, a világért mondott imában eseményenként szünet; koppintásra a lépés megáll, a térkép megnyitásakor a zene szól tovább; a világ-helyzetek a legfrissebb eseményekkel kezdődnek.": "Ayuda de oración: después del versículo queda un silencio para orar, y en la oración por el mundo una pausa por cada suceso; al tocar, el paso se detiene, y al abrir el mapa la música sigue sonando; las situaciones mundiales empiezan por los sucesos más recientes.",
  "Biblia: a fordításválasztóban a King James teljes neve áll, a fejlécben a rövid neve; a Strong-szótár tömörebb, elöl a szó fordítási lehetőségeivel; az Igetanulóban a verset hanggal is be lehet mondani.": "Biblia: en el selector de traducciones aparece el nombre completo de la King James, y en la cabecera su nombre corto; el diccionario Strong es más compacto, con las posibles traducciones de la palabra al principio; en el Memorizador de versículos también puedes decir el versículo en voz alta.",
  "Gyerekjátékok: Noé bárkájába az állatok csak párosával mehetnek be; a hangszóró gomb leállítja a mondatot; a memóriajáték 24 kártyáig választható, ketten felváltva, pontgyűjtéssel, és csak a képernyőre kiférő méreteket kínálja.": "Juegos infantiles: en El arca de Noé los animales solo pueden entrar por parejas; el botón del altavoz detiene la frase; el Juego de memoria permite hasta 24 cartas, para dos jugadores por turnos con puntos, y solo ofrece los tamaños que caben en la pantalla.",
  "Kalkulátor: a FortiPrep és a konzerv ára az ország saját pénznemében jelenik meg, átszámolt alapárral.": "Calculadora: el precio de FortiPrep y de las conservas aparece en la moneda del país, con el precio base convertido.",
  "Visszajelzés: megújult lap, minden felirat a választott nyelven; képernyőkép küldhető a lap mögötti oldalról.": "Comentarios: página renovada, con todos los textos en el idioma elegido; se puede enviar una captura de la página que hay detrás.",
  "Javítások: a súgó lépései a saját elemükre mutatnak; ugyanaz a hirdetés nem jön kétszer egymás után; a Beállítások gombjainak felirata nem lóg ki.": "Correcciones: los pasos de la ayuda señalan su propio elemento; el mismo anuncio no aparece dos veces seguidas; los textos de los botones de Ajustes no se salen.",
  "Biblia: a jegyzetek gomb a felolvasás gombja fölött lebeg; a jegyzet Biblia gombja visszavisz ahhoz a vershez, ahonnan jöttél; a Scofield-jegyzet rendezett magyarázatként, koppintható hivatkozásokkal jelenik meg.": "Biblia: el botón de notas flota sobre el botón de lectura en voz alta; el botón Biblia de la nota te devuelve al versículo del que venías; la Nota de Scofield aparece como explicación ordenada, con referencias que se pueden tocar.",
  "Biblia: a lebegő ablakok az alsó sáv fölött végződnek, a címük nem csúszik a bezárás gomb alá; a felolvasás minden nyelven felkínálja a Stúdióhangot.": "Biblia: las ventanas flotantes terminan por encima de la barra inferior y su título no se mete bajo el botón de cerrar; la lectura en voz alta ofrece la Voz de estudio en todos los idiomas.",
  "Biblia-játékok: Noé bárkájában az állatok a rámpán felsétálnak, bemennek az ajtón, és párosával a fedélzeten állnak; a memóriajáték rácsa minden képernyőre kifér.": "Juegos bíblicos: en El arca de Noé los animales suben por la rampa, entran por la puerta y se quedan por parejas en la cubierta; la cuadrícula del Juego de memoria cabe en cualquier pantalla.",
  "Térkép: a panelek a keresősáv üveges hátterét kapták; éjszakai módban a szintvonalak halványak; a világhelyzet jelmagyarázata rövidebb feliratot kapott.": "Mapa: los paneles tienen el fondo de cristal de la barra de búsqueda; en modo nocturno las curvas de nivel son tenues; la leyenda de la situación mundial tiene etiquetas más cortas.",
  "Készlet: javaslatok a kereső alatt, ml és l mértékegység a folyadékokhoz, a kalória mező csak az élelmiszereknél.": "Reservas: sugerencias bajo el buscador, unidades ml y l para los líquidos, el campo de calorías solo en los alimentos.",
  "Szobák: a „N készülék” a ténylegesen bent lévő telepítéseket számolja; bejelentkezés után a nyitott szoba újraindul.": "Salas: «N dispositivos» cuenta las instalaciones que están realmente dentro; tras iniciar sesión, la sala abierta se reinicia.",
  "Javítások: esés-figyelés és a tudomásulvétel jelölője együtt mozog; a Gerah küldésénél a Küldés gomb közvetlenül a címzett után áll; a mentés gombjai keskeny képernyőn is kiférnek.": "Correcciones: la detección de caídas y la marca de confirmación se mueven juntas; al enviar Gerah, el botón Enviar está justo después del destinatario; los botones de guardar caben también en pantallas estrechas.",
  "Biblia: új Igetanulmányozó. Egy fejezetet két kiválasztott fordításban mutat, telefonon versenként egymás alatt, széles képernyőn egymás mellett, az eltérő versszámozással párosítva; azonos nyelvű fordításoknál kiemeli az eltérő szavakat. Az eredeti görög és héber szöveggel is működik. Biblia prémium nélkül naponta 3 fejezet.": "Biblia: nuevo Estudio bíblico. Muestra un capítulo en dos traducciones elegidas, en el teléfono versículo a versículo una debajo de otra y en pantalla ancha una al lado de otra, emparejadas aunque la numeración de versículos difiera; en traducciones del mismo idioma resalta las palabras distintas. También funciona con el texto original griego y hebreo. Sin Biblia Premium, 3 capítulos al día.",
  "Biblia: több mint 70 új, szabadon letölthető fordítás (köztük görög, héber, latin), a fordításválasztóban országonként és nyelvenként csoportosítva; magyarul a Nyitott Újszövetség is.": "Biblia: más de 70 traducciones nuevas de descarga libre (entre ellas griego, hebreo y latín), agrupadas por país e idioma en el selector de traducciones; en húngaro también la Nyitott Újszövetség.",
  "Biblia: a keresés alatt kiválasztott szóalak pontosan arra az alakra szűr.": "Biblia: la forma de la palabra elegida bajo la búsqueda filtra exactamente por esa forma.",
  "Biblia: a lebegő ablakok (fordításválasztó, eredeti szó, versmenü, letöltés) új, csillagos égbolt arculatot kaptak, a bezárás gombja a jobb felső sarokban.": "Biblia: las ventanas flotantes (selector de traducciones, palabra original, menú del versículo, descarga) tienen un nuevo aspecto de cielo estrellado, con el botón de cerrar en la esquina superior derecha.",
  "Biblia: Stúdióhang mindenkinek, a felvételek és a zenék ingyenesek; a felolvasás, az eredeti szó és a Bibliai térkép napi kerettel ingyenes, a keret fogyását az app előre jelzi.": "Biblia: Voz de estudio para todos, las grabaciones y la música son gratuitas; la lectura en voz alta, la palabra original y el mapa bíblico son gratuitos con un límite diario, y la app avisa con antelación de cuánto queda.",
  "Biblia-játékok: Noé bárkájában 16 állat, nagyobb memóriakártyák, az Igetanuló ingyenes, az Igekvíz új válaszmezőt kapott.": "Juegos bíblicos: 16 animales en El arca de Noé, cartas más grandes en el Juego de memoria, el Memorizador de versículos es gratuito y el Quiz de versículos tiene un nuevo campo de respuesta.",
  "Térkép: új, áttetsző üveg arculat; a nagyítógombok helyett csíptetéssel nagyíthatsz; a már betöltött térképrészletek megmaradnak, nem töltődnek le újra; a földutak és ösvények turistatérkép-stílusban látszanak.": "Mapa: nuevo aspecto de cristal translúcido; en lugar de los botones de zoom, amplías pellizcando; las partes del mapa ya cargadas se conservan y no se vuelven a descargar; los caminos de tierra y senderos se ven al estilo de un mapa de senderismo.",
  "Térkép: a „Más országok térképei” listájának tetején Magyarország is ott van, és a tájegységeihez visz.": "Mapa: Hungría también aparece al principio de la lista «Mapas de otros países» y lleva a sus regiones.",
  "Kopogás: hallás utáni módban nagyobb, négyzetes betűrács, a betűre koppintva ellenőriz.": "Golpes: en el modo de oído, una cuadrícula de letras más grande y cuadrada; al tocar una letra, la comprueba.",
  "Mentés a fiókba: az app adatai a fiókodba menthetők, és új telefonon visszatölthetők.": "Guardar en la cuenta: los datos de la app se pueden guardar en tu cuenta y restaurar en un teléfono nuevo.",
  "Wordlight: a napi célidő a PrepperPapa tárcájában is Gerah-t ér, naponta egyszer.": "Wordlight: el tiempo de la meta diaria también vale Gerah en el monedero de PrepperPapa, una vez al día.",
  "A rendszer Vissza gombja a főlapra visz, nem zárja be az appot.": "El botón Atrás del sistema lleva a la página principal, no cierra la app.",
  "Javítások: a helynevek 360 képpont szélességen is kiférnek, a hirdetés nem takarja el a nyitott ablakokat, a nyilvános teszt idejére a Wordlightban is fent van a Visszajelzés gomb.": "Correcciones: los nombres de lugares caben también en 360 píxeles de ancho, el anuncio no tapa las ventanas abiertas, y durante la prueba pública Wordlight también tiene el botón Comentarios.",
  "Gyülekező: a szoba tagjai listában látszanak, névvel és jelenlét-ponttal, fiókonként egy sorban. Ha az app a háttérben fut, a jelenléted akkor is megmarad.": "Punto de reunión: los miembros de la sala aparecen en una lista, con nombre y punto de presencia, una línea por cuenta. Si la app funciona en segundo plano, tu presencia se mantiene.",
  "Felolvasás: a kiemelt szó pontosabban követi a felvett hangot.": "Lectura en voz alta: la palabra resaltada sigue con más precisión la voz grabada.",
  "iPhone: új alkalmazásikon a PrepperPapának és a Wordlightnak.": "iPhone: nuevo icono de app para PrepperPapa y Wordlight.",
  "Wordlight: a napi idő kártyája szellősebb lett; a már letöltött Károli-fordításból eltűnnek a felesleges + jelek.": "Wordlight: la tarjeta del tiempo diario es más espaciosa; en la traducción Károli ya descargada desaparecen los signos + sobrantes.",
  "Google Play és App Store: a bolti változat a tesztelői mellett is elindul ugyanazon a telefonon, és a teszt idejére abban is ott a Visszajelzés gomb.": "Google Play y App Store: la versión de la tienda también se abre junto a la de pruebas en el mismo teléfono, y durante la prueba también tiene el botón Comentarios.",
  "Wordlight: a kezdőlapon a napi idő kártyája a csempékkel együtt jelenik meg, és új indítókép fogad a világító lámpással.": "Wordlight: en el inicio, la tarjeta del tiempo diario aparece junto con los mosaicos, y te recibe una nueva pantalla de inicio con la lámpara encendida.",
  "Vezetett ima: a felolvasás az ihletet olvassa fel, a háttérzene akkor is szól tovább, ha a felolvasás véget ért, és a Folytatás gomb onnan indít, ahol abbahagytad. Két új, dob nélküli imazene (zongora és vonósok), mindkettő ingyenes.": "Oración guiada: la lectura en voz alta lee la inspiración, la música de fondo sigue sonando aunque la lectura haya terminado, y el botón Continuar retoma donde lo dejaste. Dos nuevas músicas de oración sin percusión (piano y cuerdas), ambas gratuitas.",
  "Világima: eseményenként maga a hír, egy rövid bátorítás és egy ima; a térkép gomb ugyanannál az eseménynél marad.": "Oración por el mundo: por cada suceso, la propia noticia, un breve ánimo y una oración; el botón del mapa se queda en el mismo suceso.",
  "Gyülekező: a szobák csempéi húzással rendezhetők, mint a telefon ikonjai. Ha ugyanazzal a fiókkal új telefonra telepítesz, a szobáid megmaradnak. A szobaszabályok utolsó pontja felsorolja, mit tárol a szerver.": "Punto de reunión: los mosaicos de las salas se pueden ordenar arrastrándolos, como los iconos del teléfono. Si instalas en un teléfono nuevo con la misma cuenta, conservas tus salas. El último punto de las normas de la sala enumera qué guarda el servidor.",
  "Wordlight: négyzetes kezdőcsempék, a Játékok színes rácsa és négy új képes játék gyerekeknek; a jegyzetek listájában a kereső a jegyzetekben keres; beszúrt vers után a szöveg alatta folytatódik. Az Igetanuló diktálása Wordlightban is kéri a mikrofont.": "Wordlight: mosaicos de inicio cuadrados, la cuadrícula de colores de Juegos y cuatro nuevos juegos con imágenes para niños; en la lista de notas, el buscador busca en las notas; tras un versículo insertado, el texto continúa debajo. El dictado del Memorizador de versículos también pide el micrófono en Wordlight.",
  "Felolvasás: a kiemelés azt a szót követi, amit a hang éppen kimond. Olvasási terv: a Gerah jóváírása előtt kifejezett hozzájárulást kérünk.": "Lectura en voz alta: el resaltado sigue la palabra que la voz está pronunciando. Plan de lectura: antes de abonar Gerah pedimos tu consentimiento expreso.",
  "Vagyonkezelő: a + gomb és a menüje a telefon gombsora fölött marad. Károli-fordítás: eltűntek a szövegben maradt felesleges + jelek.": "Patrimonio: el botón + y su menú se quedan por encima de la barra de botones del teléfono. Traducción Károli: han desaparecido los signos + sobrantes del texto.",
  "Gyülekező, a szoba képe: a kép választásakor kivágó nyílik a csempe arányában (húzás, két ujjas nagyítás, Kész/Mégse), és az a rész kerül fel, amit te állítasz be; a meglévő kép a Kivágás gombbal újra igazítható. Új szoba létrehozásakor ugyanez a kivágó nyílik.": "Punto de reunión, imagen de la sala: al elegir la imagen se abre un recorte con la proporción del mosaico (arrastrar, zoom con dos dedos, Hecho/Cancelar), y se sube la parte que tú ajustas; la imagen existente se puede reajustar con el botón Recortar. Al crear una sala nueva se abre el mismo recorte.",
  "Háttérzene: a Biblia prémiumhoz tartozó zenék (Gitár 1-3) lakattal jelennek meg, ha nincs feloldva, és koppintásra a feloldást nyitják; a szabad zenék (Akusztikus gitár, Kelta) változatlanul választhatók.": "Música de fondo: las músicas de Biblia Premium (Guitarra 1-3) aparecen con candado si no están desbloqueadas, y al tocarlas abren el desbloqueo; las músicas libres (Guitarra acústica, Celta) se pueden elegir como siempre.",
  "Frissítés: ha a letöltés hálózatkiesés után megáll, az app magától újraindítja és onnan folytatja, ahol tartott; a kész letöltésnél ablak kérdez: Megnyitás vagy Később, és a csík is mutatja, hogy letöltve.": "Actualización: si la descarga se detiene tras un corte de red, la app la reanuda sola desde donde iba; al terminar la descarga, una ventana pregunta: Abrir o Más tarde, y la barra también indica que está descargada.",
  "Gerah a bibliaolvasásért: a napi olvasás Gerahja mostantól letétbe kerül, és hét egymást követő olvasott nap után kerül a tárcádba; a kezdőlap napi kártyája és az összegző oldal mutatja a letétet és a hátralevő napokat. Ha kimarad egy nap, a letét elvész és a hét újraindul.": "Gerah por leer la Biblia: el Gerah de la lectura diaria pasa ahora a un depósito y llega a tu monedero tras siete días seguidos de lectura; la tarjeta diaria del inicio y la página de resumen muestran el depósito y los días que faltan. Si te saltas un día, el depósito se pierde y la semana vuelve a empezar.",
  "Kezdőképernyő-csempék: a választó menü alapból összecsukva; a telefon kezdőképernyőjére tett parancsikon a csempe saját ikonját kapja (a már kitett parancsikonokat vedd le és tedd ki újra).": "Mosaicos de la pantalla de inicio: el menú de selección está plegado por defecto; el acceso directo puesto en la pantalla de inicio del teléfono recibe el icono propio del mosaico (quita y vuelve a poner los accesos directos ya puestos).",
  "Gyülekező chat: a beírómező és a „Csak neki” sáv nem csúszik a telefon rendszer-gombjai alá.": "Chat del Punto de reunión: el campo de escritura y la barra «Solo a» no quedan debajo de los botones del sistema del teléfono.",
  "Felolvasás: a kiemelés szavanként, balról jobbra halad, az aktuális szó zöld koronafénnyel világít, a már felolvasott szöveg fehér marad, és az aktuális vers mögött halvány zöld derengés jelzi, hol tart a felolvasó.": "Lectura en voz alta: el resaltado avanza palabra por palabra, de izquierda a derecha; la palabra actual brilla con un halo verde, el texto ya leído queda blanco, y un tenue resplandor verde detrás del versículo actual indica por dónde va la lectura.",
  "Biblia: mind a 66 könyv csempéjén finom vonalas jelenetrajz jelenik meg, a fejezet- és versválasztó mögött a könyv rajza dereng zölden, és 144 fejezet-csempe a saját jelenetének rajzát kapta, a jelenet első versénél jelöléssel.": "Biblia: los mosaicos de los 66 libros muestran un fino dibujo lineal de una escena, detrás del selector de capítulo y versículo se ve en verde el dibujo del libro, y 144 mosaicos de capítulo tienen el dibujo de su propia escena, con una marca en el primer versículo de la escena.",
  "Biblia: a könyvcsempék, a fejezet- és versszámok és az Ószövetség/Újszövetség/Apokrif fejlécek új, díszes betűtípust kaptak; az orosz és ukrán felület saját, hasonló cirill betűt kap.": "Biblia: los mosaicos de los libros, los números de capítulo y versículo y las cabeceras Antiguo Testamento/Nuevo Testamento/Apócrifos tienen una nueva tipografía decorativa; las interfaces rusa y ucraniana reciben una letra cirílica propia similar.",
  "Biblia: az apokrif könyvek csempéin és a fejezet-választójuk mögött is megjelent a könyv rajza; a Wordlight fejléc-csillanása a belső oldalakon is a lámpás közepén áll; a versválasztó csempéi áttetszőbbek, átsejlik a könyv rajza.": "Biblia: el dibujo del libro aparece también en los mosaicos de los libros apócrifos y detrás de su selector de capítulos; el destello de la cabecera de Wordlight queda en el centro de la lámpara también en las páginas internas; los mosaicos del selector de versículos son más translúcidos y se transparenta el dibujo del libro.",
  "Prémium: ahol az app a prémiumot ajánlja (hirdetés bezárása, korlátok, offline térkép, zárt tudástár-cikk, Biblia-zenék és -letöltések, Vagyonkezelő), a bolti változatban egy koppintásra a Play áruházi, az App Store-változatban az App Store vásárlás nyílik; a tesztelői változatban marad a kód beváltása.": "Premium: donde la app ofrece Premium (cerrar anuncios, límites, mapa sin conexión, artículo bloqueado de la base de conocimientos, músicas y descargas de la Biblia, Patrimonio), en la versión de la tienda un toque abre la compra de Play Store, y en la versión de App Store la compra de App Store; en la versión de pruebas se mantiene el canje de código.",
  "Igetanuló: három fokozat választható (könnyű: hiányzó betűk; nehezebb: a vers első fele látszik, a másodikat te írod; nehéz: csak az igehely), és a megoldás ellenőrizhető: beírva mindkét appban, a Wordlightban mikrofonnal, hanggal bemondva is; az elírást és félrehallást az ellenőrzés tűri, és szavanként mutatja, mi tért el.": "Memorizador de versículos: puedes elegir tres niveles (fácil: letras que faltan; más difícil: se ve la primera mitad del versículo y tú escribes la segunda; difícil: solo la cita), y la solución se puede comprobar: escribiéndola en las dos apps y, en Wordlight, también diciéndola en voz alta con el micrófono; la comprobación tolera erratas y palabras mal oídas, y muestra palabra por palabra qué no coincide.",
  "Készültség: a számok napokban, nem százalékban: a gyűrű közepén és a helyszín sorában az áll, hány napra elég mindenből (víz, étel, fűtés legkevesebbje), a Víz/Étel/Fűtés/Áram sorok és a részletező is napot mutatnak, tömör jelöléssel; a gyűrű íve és színe a négy tétel egyenlő súlyú átlaga, az árammal együtt.": "Preparación: las cifras en días, no en porcentajes: en el centro del anillo y en la línea del lugar se indica para cuántos días alcanza todo (lo menor de agua, comida y calefacción); las líneas Agua/Comida/Calefacción/Electricidad y el detalle también muestran días, con una notación compacta; el arco y el color del anillo son la media, con igual peso, de los cuatro elementos, electricidad incluida.",
  "Biblia: új, kilencedik csempe, a Játékok: felnőtt és gyerek móddal, öt játékkal: az Igekvízzel, ahol találomra választott igét kell kiegészíteni vagy felmondani az Igetanuló három fokozatával; a Ki mondta? játékkal, ahol egy idézethez négy név közül kell a beszélőt eltalálni; a Hol van? játékkal, ahol egy igéhez a könyvet, felnőtt módban a fejezetet is el kell találni; az Igehely-párosítóval, ahol összekevert igéket és igehelyeket kell párba rakni; és a Könyvsorrenddel, ahol a Biblia könyveit kell sorba húzni; pontozással és sorozattal; az Igetanulóban továbbra is a saját, Tanulom-mal jelölt igéid vannak.": "Biblia: nuevo noveno mosaico, Juegos: con modo adulto e infantil y cinco juegos: el Quiz de versículos, donde completas o recitas un versículo elegido al azar con los tres niveles del Memorizador de versículos; ¿Quién lo dijo?, donde adivinas quién habla en una cita entre cuatro nombres; ¿Dónde está?, donde adivinas el libro de un versículo, y en modo adulto también el capítulo; Empareja las citas, donde emparejas versículos y citas mezclados; y Orden de los libros, donde ordenas arrastrando los libros de la Biblia; con puntuación y rachas; en el Memorizador de versículos siguen estando tus propios versículos marcados con Aprenderlo.",
  "Hirdetések: a tulajdonosi nézet „gyakorisági korlát kikapcsolva” teszt-kapcsolója egy óra után magától lejár, így a felugró hirdetés az ingyenes szinten újra a rendes ritmusban jön.": "Anuncios: el interruptor de prueba «límite de frecuencia desactivado» de la vista de propietario caduca solo al cabo de una hora, así que en el nivel gratuito el anuncio emergente vuelve a su ritmo normal.",
  "Gyülekező chat: az üzenet módosítása elvethető (Mégse a beíró fölött, vagy a Vissza gomb), üres szöveg nem menthető; módosításkor az üzenet utólag is fontosnak jelölhető, és ez a többieknél is látszik. A túl sűrű küldés korlátja készülékenként számol, és egy rövid várakozás után az app magától újrapróbálja.": "Chat del Punto de reunión: la edición de un mensaje se puede descartar (Cancelar sobre el campo de escritura, o el botón Atrás), y no se puede guardar un texto vacío; al editar, el mensaje también se puede marcar después como importante, y los demás también lo ven. El límite de envíos demasiado seguidos cuenta por dispositivo, y tras una breve espera la app lo reintenta sola.",
  "Szobák: a csatlakozott szobák sorrendje hosszú nyomással átrendezhető (nyilakkal vagy húzással, Kész-szel kilépve), és a sorrend megmarad; a szoba neve a csempén legfeljebb két sor, új szobának legfeljebb 32 karakteres név adható.": "Salas: el orden de las salas a las que te uniste se puede cambiar con una pulsación larga (con flechas o arrastrando, y saliendo con Hecho), y el orden se mantiene; el nombre de la sala ocupa como máximo dos líneas en el mosaico, y una sala nueva puede tener un nombre de 32 caracteres como máximo.",
  "Felolvasás: a felolvasott szöveg soronként szürkésből fehérré világosodik, ahogy a felolvasó halad; a köd már csak a szöveget halványítja, a hátteret nem; versváltáskor nincs késés, a kiemelés a görgetéssel együtt ér oda.": "Lectura en voz alta: el texto leído se aclara línea a línea de grisáceo a blanco a medida que avanza la lectura; la niebla ya solo atenúa el texto, no el fondo; al cambiar de versículo no hay retraso, el resaltado llega a la vez que el desplazamiento.",
  "Biblia zenék: a zárolt zenék „Biblia prémiummal” feliratára és a feloldó sorra koppintva megnyílik a feloldás a Beállításokban.": "Músicas de la Biblia: al tocar el texto «con Biblia Premium» de las músicas bloqueadas o la línea de desbloqueo, se abre el desbloqueo en Ajustes.",
  "Igetanuló: három nehézségi fokozat (könnyű: hiányos betűk; nehezebb: a vers első fele látszik, a másodikat kell befejezni; nehéz: csak az igehely látszik), a választás megmarad. A megoldás beírható és ellenőrizhető: az elírást és a félrehallott szót tűri, a hiányzó vagy eltérő szavakat kiemeli. A Wordlightban mikrofon-gombbal be is mondható.": "Memorizador de versículos: tres niveles de dificultad (fácil: letras que faltan; más difícil: se ve la primera mitad del versículo y hay que terminar la segunda; difícil: solo se ve la cita), y la elección se mantiene. La solución se puede escribir y comprobar: tolera erratas y palabras mal oídas, y resalta las palabras que faltan o difieren. En Wordlight también se puede decir con el botón del micrófono.",
  "Zöld képernyő: a háttérből újranyitott app nem marad többé üres zöld lapon, ott folytatja, ahol voltál; a belépés sem vész el, és ha a szerver mégis kiléptetne, az app maga ajánlja fel az e-mailes belépést.": "Pantalla verde: la app reabierta desde segundo plano ya no se queda en una página verde vacía, sigue donde estabas; tampoco se pierde la sesión, y si el servidor aun así la cerrara, la propia app te ofrece iniciar sesión por correo electrónico.",
  "Gombok: megnyomáskor rövid animáció a kék négyzet helyett, a PrepperPapában és a Wordlightban is.": "Botones: al pulsarlos, una breve animación en lugar del cuadrado azul, en PrepperPapa y en Wordlight.",
  "Állapotsáv: az óra, az akkumulátor és a kamera-kivágás sávja a lap háttérszínét veszi fel, nappal és éjszaka is.": "Barra de estado: la franja del reloj, la batería y el recorte de la cámara toma el color de fondo de la página, de día y de noche.",
  "Felolvasás: a köd fixen a képernyő közepén marad, elő- és eltűnéssel vált, a szöveg alatta fut, oldalt nincs sötét szél; a felolvasás-beállítások gomb minden nyelven a saját nyelvén áll és megnyílik (oroszul is); nyelvenként a jobb hang szól.": "Lectura en voz alta: la niebla se queda fija en el centro de la pantalla, cambia apareciendo y desapareciendo, el texto pasa por debajo, y no hay bordes oscuros a los lados; el botón de ajustes de lectura en voz alta aparece en cada idioma en su propio idioma y se abre (también en ruso); en cada idioma suena la mejor voz.",
  "Biblia: versszámra koppintva kijelölhető a vers (jegyzetbe beszúráshoz); a Charon-letöltés sora és a számlálója javítva; a vezetett ima zenével és felolvasással külön is indítható; a linkből kapott feloldókód nem ragad be; a nyitókép kilenc csempés; Androidon a főoldali csempék a telefon kezdőképernyőjére tehetők.": "Biblia: al tocar el número de un versículo se puede seleccionar el versículo (para insertarlo en una nota); corregidos la línea de descarga de Charon y su contador; la oración guiada se puede iniciar aparte con música y lectura en voz alta; el código de desbloqueo recibido por enlace ya no se queda atascado; la pantalla de inicio tiene nueve mosaicos; en Android, los mosaicos de la página principal se pueden poner en la pantalla de inicio del teléfono.",
  "Térkép: indulási dátum-idő mező az útvonal-tervezőben; elhúzás után egy percig nem húz vissza a GPS-re; háttér-navigáció kikapcsolt kijelzővel, hangos utasítással (Android); keresőmező más országok térképéhez; offline térképek országonként csoportosítva, a letöltés leállítható, a törlés azonnal látszik, egy gombbal az egész ország törölhető; a letöltött külföldi alaptérkép kirajzolódik; a külföldi turistautak kis zoomon nem akasztják meg a térképet; Megosztás gomb az Új pont ablakban; a „Pont ide, ahol vagyok” gomb nem ragad be; a vissza-gesztus a panelt zárja, nem lép ki.": "Mapa: campo de fecha y hora de salida en el planificador de rutas; tras arrastrar, durante un minuto no vuelve al GPS; navegación en segundo plano con la pantalla apagada y con indicaciones por voz (Android); campo de búsqueda para los mapas de otros países; mapas sin conexión agrupados por país, la descarga se puede detener, el borrado se ve al instante y con un botón se borra todo el país; el mapa base extranjero descargado se dibuja; los senderos extranjeros no bloquean el mapa con poco zoom; botón Compartir en la ventana Nuevo punto; el botón «Punto aquí, donde estoy» ya no se queda atascado; el gesto de volver cierra el panel, no sale.",
  "SOS: mentőkártya fényképpel, QR-kóddal és a mentőknek fontos adatokkal egy blokkban.": "SOS: tarjeta para los servicios de emergencia con foto, código QR y los datos importantes para los sanitarios en un solo bloque.",
  "Gerah: a jóváírásról értesítés érkezik a telefonra; a Biblia prémium bolti vásárlása előkészítve (a gomb még nem látszik, a kódos feloldás változatlan).": "Gerah: llega una notificación al teléfono cuando se abona; la compra en tienda de Biblia Premium está preparada (el botón aún no se ve, el desbloqueo con código no cambia).",
  "Egyéb: a rendszer felugró ablakai helyett mindenhol az app saját ablakai; Központ: jelentkezések; profilkép-kivágó; a fejléc gombjai mindenhol koppinthatók; Noé-jelenlét felirat javítva; Számlázz-kód szűkítés.": "Otros: en lugar de las ventanas emergentes del sistema, en todas partes las ventanas propias de la app; Centro: solicitudes; recorte de foto de perfil; los botones de la cabecera se pueden tocar en todas partes; corregido el texto de presencia de Noé; filtro de códigos de Számlázz.",
  "Igetanuló: új csempe a Biblia főoldalán, a szavak lépésről lépésre tűnnek el, az ismétlés napok múlva visszatér; prémium, ingyen hetente egy új ige. A kiemelések a Jegyzeteim alatt maradnak.": "Memorizador de versículos: nuevo mosaico en la página principal de la Biblia, las palabras desaparecen paso a paso y el repaso vuelve al cabo de unos días; Premium, gratis un versículo nuevo por semana. Los resaltados se quedan en Mis notas.",
  "Jegyzetek: nyomtatható és PDF-be menthető jegyzet; a beszúrt igéknél is megjelenik a jegyzet-jel a fejezetben.": "Notas: notas que se pueden imprimir y guardar en PDF; la marca de nota también aparece en el capítulo en los versículos insertados.",
  "Fejléc minden oldalon: a felső sáv görgetésre elhalványul, a tartalom fölé csúszik, és az oldal feje a legtetejéig ér; a PrepperPapa felirat és a Készlet szűrői nem vágódnak le keskeny telefonon.": "Cabecera en todas las páginas: la barra superior se atenúa al desplazarse, se desliza sobre el contenido y la cabecera de la página llega hasta arriba del todo; el texto PrepperPapa y los filtros de Reservas no se cortan en teléfonos estrechos.",
  "Imaszoba: újra egyben, lefelé görgethető a teljes ima a huszonnyolc imával; a háttérzene és a felolvasás a felolvasó panelből indul; minden imában egy saját imatémád is megjelenik.": "Sala de oración: de nuevo en una sola pieza, se puede desplazar hacia abajo toda la oración con las veintiocho oraciones; la música de fondo y la lectura en voz alta se inician desde el panel de lectura; en cada oración aparece también uno de tus motivos de oración.",
  "Felolvasás: a hangválasztó (telefon hangja vagy PrepperPapa-hang) minden nyelven látszik, nem csak magyarul.": "Lectura en voz alta: el selector de voz (voz del teléfono o voz PrepperPapa) se ve en todos los idiomas, no solo en húngaro.",
  "Könyvválasztó: nyelvváltás után a könyvek csempéi is az új fordítást mutatják; az apokrif könyvek felirata ugyanakkora, mint a bibliai könyveké.": "Selector de libros: tras cambiar de idioma, los mosaicos de los libros también muestran la nueva traducción; el texto de los libros apócrifos tiene el mismo tamaño que el de los libros bíblicos.",
  "Biblia-csempék és napi panel: új, egységes ikonkészlet, áttetsző csempék és halványzöld feliratok, mint a kezdőlapon.": "Mosaicos de la Biblia y panel diario: nuevo conjunto de iconos uniforme, mosaicos translúcidos y textos verde claro, como en el inicio.",
  "Wordlight: a fejléc lámpásában a kereszt ragyog, minden harmadik felfénylésnél megcsillan.": "Wordlight: en la lámpara de la cabecera brilla la cruz, y destella en cada tercer resplandor.",
  "Háztartás: élénkebb csempék generált, zöld tónusú háttérképpel és nagy darabszámmal; a tagok fényképe feltöltéskor nagyítható és beállítható, mint a szobák képe; a csempék tartalma középre igazítva.": "Hogar: mosaicos más vivos con imagen de fondo generada en tonos verdes y un número grande; la foto de los miembros se puede ampliar y ajustar al subirla, como la imagen de las salas; el contenido de los mosaicos está centrado.",
  "Gerah: a tárcában kisebb érme, arany Gerah felirat és egyenleg; a napelem ikonján új napsugarak.": "Gerah: en el monedero, moneda más pequeña, texto Gerah y saldo en dorado; nuevos rayos de sol en el icono del panel solar.",
  "Irattárca: gomb a fejlécben; Noah a Tudástár tetején egy sorban, nem csempeként.": "Cartera de documentos: botón en la cabecera; Noah en una línea arriba de la Base de conocimientos, no como mosaico.",
  "Kezdőlap fejléce: a Frissítés keresése gomb helyén Noah gombja áll; a frissítés keresése a Beállításokban és a Több menüben érhető el, az automatikus frissítés változatlan. A fejléc gombjai görgetés nélkül újra reagálnak.": "Cabecera del inicio: en lugar del botón Buscar actualización está el botón de Noah; la búsqueda de actualizaciones está en Ajustes y en el menú Más, y la actualización automática no cambia. Los botones de la cabecera vuelven a responder sin desplazarse.",
  "iPhone: ütemezett értesítések és imaemlékeztető; felolvasás zárolt képernyőn is, zárképernyős gombokkal; bibliai, túra- és SOS-ébresztő; háttér-hely, légnyomás-mintavétel és térkép-letöltés a háttérben.": "iPhone: notificaciones programadas y recordatorio de oración; lectura en voz alta también con la pantalla bloqueada, con botones en la pantalla de bloqueo; alarma bíblica, de excursión y SOS; ubicación en segundo plano, muestreo de presión atmosférica y descarga de mapas en segundo plano.",
  "iPhone: esés-észlelés és SOS, tükör, riasztó, Face ID a tárca-PIN-hez, megosztás és megosztás-fogadás, mesh Bluetooth-on, nyomtatás.": "iPhone: detección de caídas y SOS, espejo, alarma, Face ID para el PIN del monedero, compartir y recibir contenido compartido, mesh por Bluetooth, impresión.",
  "Gerah: minden nyelven ez a neve, és a napi Biblia-cél sávos: 10, 20 és 30 perc olvasásért 1, 2, illetve 3 Gerah.": "Gerah: este es su nombre en todos los idiomas, y la meta diaria de la Biblia es por tramos: 1, 2 o 3 Gerah por 10, 20 y 30 minutos de lectura.",
  "Imaszoba: 28 vezetett ima négyhetes körben, útmutatással és szó szerinti imával, külön lépés a világért; lépésenként egy oldal, ujjal lapozható, halk háttérzenével.": "Sala de oración: 28 oraciones guiadas en un ciclo de cuatro semanas, con orientación y una oración literal, y un paso aparte por el mundo; una página por paso, que se pasa con el dedo, con música de fondo suave.",
  "Jegyzetek: alacsonyabb fejléc, Biblia-gomb a jegyzetből az igére és jegyzet-gomb a fejezetnézetben, egysoros címkeszűrő.": "Notas: cabecera más baja, botón Biblia de la nota al versículo y botón de nota en la vista del capítulo, filtro de etiquetas en una línea.",
  "Wordlight: soha nincs reklám; az országodhoz tartozó imatéma naponta legfeljebb egyszer, csendben ajánlkozik.": "Wordlight: nunca hay publicidad; el motivo de oración de tu país se ofrece en silencio como máximo una vez al día.",
  "Wordlight: görgetésnél a fejléc tömör marad, csak a logó és a gombok halványulnak.": "Wordlight: al desplazarse, la cabecera se queda opaca; solo se atenúan el logotipo y los botones.",
  "Felolvasás: a választott hang nem áll vissza az alapra navigálás vagy kilépés után.": "Lectura en voz alta: la voz elegida no vuelve a la predeterminada tras navegar o salir.",
  "Fordítások: az angol és a többi nyelvű felületen maradt magyar feliratok javítva (tárca, Vagyonkezelő, felolvasás).": "Traducciones: corregidos los textos en húngaro que quedaban en la interfaz inglesa y de otros idiomas (monedero, Patrimonio, lectura en voz alta).",
  "iPhone: a helymeghatározás engedélykérése az app nevével jelenik meg.": "iPhone: la solicitud de permiso de ubicación aparece con el nombre de la app.",
  "Biblia: a kommentárok helyett jegyzetek, címkékkel és csoportos kereséssel.": "Biblia: notas en lugar de comentarios, con etiquetas y búsqueda agrupada.",
  "Biblia: új Imaszoba, vezetett imával, saját imatémákkal és napi ima-emlékeztetővel.": "Biblia: nueva Sala de oración, con oración guiada, motivos de oración propios y recordatorio diario de oración.",
  "Biblia-kereső: egy találatból visszalépve a találati listára jutsz, ugyanott, ahol abbahagytad.": "Buscador de la Biblia: al volver de un resultado llegas a la lista de resultados, en el mismo punto donde la dejaste.",
  "Felolvasás: a hangok állandó betűjelet kapnak (A hang, B hang…), mindegyiket meg lehet hallgatni; a választott hang tényleg felolvas.": "Lectura en voz alta: las voces reciben una letra fija (Voz A, Voz B...), todas se pueden escuchar, y la voz elegida lee de verdad.",
  "Bibliai ébresztő: köszöntéssel, csengő nélkül, lassan felhangosodva indul; az időválasztó ujjal húzható.": "Alarma bíblica: empieza con un saludo, sin timbre, subiendo poco a poco el volumen; el selector de hora se arrastra con el dedo.",
  "Olvasási terv: a ténylegesen elolvasott tervnapokért Gerah jár.": "Plan de lectura: los días del plan realmente leídos dan Gerah.",
  "Elhivatottság: rendezett fejléc, nincs üres sáv a kártyák fölött.": "Constancia: cabecera ordenada, sin franja vacía sobre las tarjetas.",
  "Fordítások: a Biblia-beállítások és a vészhelyzeti igék címei minden nyelven; angolul a Gerah neve Gerah.": "Traducciones: los títulos de los ajustes de la Biblia y de los versículos de emergencia en todos los idiomas; en inglés, el nombre de Gerah es Gerah.",
  "Gerah-érme: zöld olajág a galamb csőrében.": "Moneda Gerah: una rama de olivo verde en el pico de la paloma.",
  "Biblia prémium: a tulajdonosi be/ki kapcsolók újra látszanak, és nem lehet őket kívülről átállítani.": "Biblia Premium: los interruptores de propietario vuelven a verse y no se pueden cambiar desde fuera.",
  "Biblia: a fekete sáv az olvasónézet szélén megszűnt.": "Biblia: ha desaparecido la franja negra del borde de la vista de lectura.",
  "Biblia-kereső: szóváltozatok a mező alatt, ékezet nélkül is talál.": "Buscador de la Biblia: variantes de palabras bajo el campo, y encuentra también sin acentos.",
  "Biblia: nagyobb könyvcsempék, az előzmények napok szerint.": "Biblia: mosaicos de libros más grandes, historial por días.",
  "Napi olvasási idő: 90 másodperc tétlenség után megáll.": "Tiempo de lectura diario: se detiene tras 90 segundos de inactividad.",
  "Wordlight: az olvasási terv újraindítás után is a terv napjára nyílik; a cél sáv színe javítva.": "Wordlight: el plan de lectura se abre en el día del plan también tras reiniciar; corregido el color de la barra de la meta.",
  "Térkép: a műholdkép tovább nagyítható szürke „nincs adat” mező nélkül.": "Mapa: la imagen de satélite se puede ampliar más sin el campo gris «sin datos».",
  "Visszajelzés: egy képernyőn elfér; a „Még mindig hibás” saját ablakot nyit szövegmezővel; a morze-nézet mérési adatokat csatol.": "Comentarios: cabe en una pantalla; «Sigue fallando» abre su propia ventana con un campo de texto; la vista Morse adjunta datos de medición.",
  "Wordlight: a kezdőlapon a csempék alatt megjelenik a napi olvasási cél sávja.": "Wordlight: en el inicio aparece bajo los mosaicos la barra de la meta diaria de lectura.",
  "Biblia-kereső: a keresett szó kiemelt színnel látszik a találatokban.": "Buscador de la Biblia: la palabra buscada se ve resaltada en color en los resultados.",
  "Biblia-térkép: internettel a világtérkép letöltése nélkül is látszik az alaptérkép (pl. Midián alatt a tenger, a part és a városok).": "Mapa bíblico: con internet, el mapa base se ve también sin descargar el mapa del mundo (por ejemplo, el mar, la costa y las ciudades bajo Madián).",
  "Hirdetések: ha a telefon tárolójában hibás vagy üres kép maradt, az app újra letölti.": "Anuncios: si en el almacenamiento del teléfono quedó una imagen dañada o vacía, la app la vuelve a descargar.",
  "Frissítés: ha az app nem éri el a frissítési listát, 30 másodperc múlva újra próbálja, és a hibát naplózza.": "Actualización: si la app no puede acceder a la lista de actualizaciones, lo vuelve a intentar a los 30 segundos y registra el error.",
  "Biblia: a felolvasó panelen a háttérzene gombjain a feliratok kiférnek, a panel nem csúszik oldalra.": "Biblia: en el panel de lectura, los textos de los botones de música de fondo caben, y el panel no se desplaza hacia un lado.",
  "Biblia: hosszú, több fejezeten át tartó olvasásnál a szöveg alja nem homályosodik el.": "Biblia: en lecturas largas que abarcan varios capítulos, la parte inferior del texto no se difumina.",
  "Biblia: új olvasási tervek: Ószövetség és Újszövetség párhuzamosan (napi egy-egy fejezet), Próféciák 41 nap alatt, Jézus példázatai, A Biblia imádságai, Pál levelei 30 nap alatt.": "Biblia: nuevos planes de lectura: Antiguo y Nuevo Testamento en paralelo (un capítulo de cada al día), Profecías en 41 días, Las parábolas de Jesús, Las oraciones de la Biblia, Las cartas de Pablo en 30 días.",
  "Biblia: új elhivatottság-oldal a statisztikákkal; a PrepperPapa kezdőlapján a Biblia csempék alatt a napi olvasási idő, a fejezetnézetben kerek lebegő gyűrű; az aktuális könyvet vastag zöld keret jelöli.": "Biblia: nueva página de constancia con estadísticas; en el inicio de PrepperPapa, el tiempo de lectura diario bajo los mosaicos de la Biblia, y en la vista del capítulo un anillo flotante redondo; el libro actual se marca con un marco verde grueso.",
  "Wordlight: az első megnyitáskor a nyitókép tovább látszik, és lágy áttűnéssel adja át a helyét a Bibliának.": "Wordlight: en la primera apertura, la pantalla de inicio se ve más tiempo y da paso a la Biblia con una transición suave.",
  "Frissítés: ha a telefon a Wi-Fi-t „internet nélkülinek” látja, és a letöltés nem indul el, az app 20 másodperc után maga tölti le a frissítést.": "Actualización: si el teléfono considera el Wi-Fi «sin internet» y la descarga no empieza, la app descarga ella misma la actualización a los 20 segundos.",
  "Biblia: a felolvasás beállításai átláthatóbb sorrendben: előbb a hang, aztán a versek közti szünet, végül a háttérzene; a panel nem átlátszó.": "Biblia: los ajustes de lectura en voz alta en un orden más claro: primero la voz, luego la pausa entre versículos y por último la música de fondo; el panel no es transparente.",
  "Biblia: a felolvasott vers körüli köd széle lágyabb és kerekebb.": "Biblia: el borde de la niebla alrededor del versículo leído es más suave y redondeado.",
  "Biblia: az automatikus görgetés felolvasás közben lágyan gyorsul és lassul.": "Biblia: el desplazamiento automático acelera y frena suavemente durante la lectura en voz alta.",
  "Biblia: új „Ébresztő kipróbálása” gomb az ébresztő oldalán, és zene-előhallgatás a felolvasó panelen.": "Biblia: nuevo botón «Probar la alarma» en la página de la alarma, y vista previa de la música en el panel de lectura.",
  "Biblia: hat új háttér- és ébresztőzene (Epikus 4-6, Gitár 1-3) a Biblia prémiumhoz.": "Biblia: seis nuevas músicas de fondo y de alarma (Épica 4-6, Guitarra 1-3) para Biblia Premium.",
  "Gerah: minden nap, amikor eléred a napi bibliaolvasási célt, Gerah-t bányászol (10 perces céltól 1, 20 perctől 2, 30 perctől 3 gerah-t), Biblia prémium nélkül is; a tárcában leírás mutatja, hogyan gyűjthetsz Gerah-t.": "Gerah: cada día que alcanzas la meta diaria de lectura de la Biblia minas Gerah (1 gerah con la meta de 10 minutos, 2 desde 20 minutos, 3 desde 30 minutos), también sin Biblia Premium; en el monedero, una descripción muestra cómo puedes reunir Gerah.",
  "Beállítások: feliratkozhatsz a hírlevélre; a Wordlightban a fiók és a hírlevél is itt érhető el. A fiók törlése a hírlevélről is leiratkoztat.": "Ajustes: puedes suscribirte al boletín; en Wordlight, la cuenta y el boletín también están aquí. Al eliminar la cuenta también te das de baja del boletín.",
  "Belépés: a belépőkódot hozó levélben egy gomb egyből megnyitja az appot.": "Inicio de sesión: en el correo con el código de acceso, un botón abre directamente la app.",
  "Helyi szobák (Wi-Fi, Bluetooth): egy üzenetet vagy tagot hosszan nyomva jelenteni vagy letiltani lehet; a letiltottak a Beállításokban oldhatók fel.": "Salas locales (Wi-Fi, Bluetooth): manteniendo pulsado un mensaje o un miembro puedes denunciarlo o bloquearlo; los bloqueados se desbloquean en Ajustes.",
  "A riasztó helyett egyszerű Hanggenerátor: söprő vagy folyamatos hang, állítható frekvenciával.": "En lugar de la alarma, un sencillo Generador de tonos: tono de barrido o continuo, con frecuencia ajustable.",
  "Térkép: területet csak a saját térképről lehet előre letölteni; a felirat „© OpenStreetMap contributors”.": "Mapa: solo se pueden descargar zonas por adelantado desde el mapa propio; el texto es «© OpenStreetMap contributors».",
  "Térkép: ha a saját térkép üresen maradna, az app magától helyreállítja.": "Mapa: si el mapa propio se quedara vacío, la app lo restaura sola.",
  "Esésérzékelés: kikapcsolt képernyőnél is pontosan méri a zuhanás idejét.": "Detección de caídas: mide con precisión el tiempo de caída también con la pantalla apagada.",
  "Prémiummal soha nem jelenik meg felugró ablakos ajánlat.": "Con Premium nunca aparece una oferta en ventana emergente.",
  "Névjegy: új link az app adatkezelési tájékoztatójához, a PrepperPapában és a Wordlightban is.": "Acerca de: nuevo enlace a la política de privacidad de la app, en PrepperPapa y en Wordlight.",
  "Wordlight: csak azokat az engedélyeket kéri, amelyeket ténylegesen használ.": "Wordlight: solo pide los permisos que realmente usa.",
  "iPhone: a helymeghatározás engedélykérő szövege pontosan leírja, hogy SOS-nál és a Helyzetem küldésénél a szoba tagjai megkapják a helyzetet.": "iPhone: el texto de la solicitud de permiso de ubicación explica con precisión que, con SOS y con Enviar mi posición, los miembros de la sala reciben la posición.",
  "Biblia: a fogaskerék körüli napi olvasásidő-gyűrű újra a hátralévő időt mutatja: reggel tele, olvasás és hallgatás közben fogy, a napi célnál arany.": "Biblia: el anillo de tiempo de lectura diario alrededor del engranaje vuelve a mostrar el tiempo restante: lleno por la mañana, se va vaciando al leer y escuchar, y dorado al llegar a la meta diaria.",
  "Napi idő az Igével: a gyűrű, a napi cél és a gratuláció Biblia prémium nélkül is működik, alapból 5 perces céllal.": "Tiempo diario con la Palabra: el anillo, la meta diaria y la felicitación funcionan también sin Biblia Premium, con una meta de 5 minutos por defecto.",
  "Térkép: nagyítás és mozgatás közben a túraútvonalak már nem tűnnek el egy pillanatra.": "Mapa: al ampliar y mover, las rutas de senderismo ya no desaparecen por un instante.",
  "Biblia: a reggeli ébresztő felolvasása is beleszámít a napi olvasásidőbe és a Gerah-ba.": "Biblia: la lectura en voz alta de la alarma matutina también cuenta en el tiempo de lectura diario y en el Gerah.",
  "Wordlight: az app a tesztidőszaki zár nélkül nyílik meg.": "Wordlight: la app se abre sin el bloqueo del periodo de prueba.",
  "Wordlight: a Kód beváltása a Wordlight saját beállításaiban is működik.": "Wordlight: Canjear código también funciona en los ajustes propios de Wordlight.",
  "Wordlight: bejelentkezés nélkül a kódbeváltás és a hangminta a bejelentkező ablakot, illetve egy Belépés gombot mutat, nem „hamarosan” feliratot.": "Wordlight: sin iniciar sesión, el canje de código y la muestra de voz muestran la ventana de inicio de sesión o un botón Iniciar sesión, no el texto «próximamente».",
  "Wordlight: első indításkor nem kér mozgás- és fitnesz-engedélyt (a légnyomásmérő nem indul el).": "Wordlight: en el primer inicio no pide permiso de movimiento y actividad física (el barómetro no se inicia).",
  "Wordlight: a Névjegy a Wordlight adatait mutatja.": "Wordlight: Acerca de muestra los datos de Wordlight.",
  "Wordlight: havonta egyszer jelzi, hány Gerah-t kaphattál volna a PrepperPapában a teljesített olvasási napjaidért.": "Wordlight: una vez al mes indica cuántos Gerah podrías haber recibido en PrepperPapa por tus días de lectura cumplidos.",
  "Biblia: az automatikus görgetés lágyan indul, lágyan vált sebességet és lágyan áll meg; koppintásra a szöveg finoman lefékez, húzásra azonnal megáll.": "Biblia: el desplazamiento automático empieza suavemente, cambia de velocidad suavemente y se detiene suavemente; al tocar, el texto frena con delicadeza, y al arrastrar se detiene al instante.",
  "Biblia: mind a nyolc csempe új, egységes vonalas ikont kapott, nagyobb méretben, a PrepperPapában és a Wordlightban is.": "Biblia: los ocho mosaicos tienen un nuevo icono lineal uniforme, más grande, en PrepperPapa y en Wordlight.",
  "Biblia: a napi cél gyűrűje a fogaskerék gomb lekerekített négyzetét követi.": "Biblia: el anillo de la meta diaria sigue el cuadrado redondeado del botón del engranaje.",
  "Wordlight: az app neve mindenhol Wordlight, új indítóikon lámpás nélkül, alatta BIBLIA felirattal.": "Wordlight: el nombre de la app es Wordlight en todas partes, con un nuevo icono de inicio sin lámpara y el texto BIBLIA debajo.",
  "Wordlight: a nyitólapon nincs ébresztő és fogaskerék; az ébresztő az olvasási tervnél, a beállítások az olvasásból érhetők el.": "Wordlight: en la página de inicio no hay alarma ni engranaje; la alarma está en el plan de lectura y los ajustes se abren desde la lectura.",
  "Wordlight: a beállításokból kikerültek a PrepperPapa készlet- és teszt-adat gombjai.": "Wordlight: se han quitado de los ajustes los botones de reservas y de datos de prueba de PrepperPapa.",
  "iPhone: a fióktörlés megerősítő ablaka nem csúszik a menüsor mögé, és lapváltáskor bezárul.": "iPhone: la ventana de confirmación de eliminación de la cuenta no se mete detrás de la barra de menú y se cierra al cambiar de página.",
  "A nyelvválasztóban a magyar minden nyelven Magyar néven szerepel.": "En el selector de idioma, el húngaro aparece en todos los idiomas como Magyar.",
  "Felolvasás: a köd sarkai lekerekítve, nincs szögletes sarok.": "Lectura en voz alta: las esquinas de la niebla están redondeadas, sin esquinas en ángulo.",
  "Felolvasás: a köd alatt minden betű teljes színen áll, és a köd csak a szöveg szélétől kifelé halványul el, oldalt is.": "Lectura en voz alta: bajo la niebla todas las letras tienen su color completo, y la niebla solo se desvanece hacia fuera desde el borde del texto, también a los lados.",
  "A felolvasott vers ködös kiemelése oldalt is lágyan elhalványul, nincs éles széle.": "El resaltado con niebla del versículo leído también se desvanece suavemente a los lados, sin borde marcado.",
  "Biblia-ébresztő: az ébresztő beállításainál egy ige mutatja, miért jó az Igével kelni (Zsoltárok 143,8), minden nyelven a saját Bibliájából.": "Alarma bíblica: en los ajustes de la alarma, un versículo muestra por qué es bueno despertar con la Palabra (Salmos 143:8), en cada idioma de su propia Biblia.",
  "Kalkulátorok: minden kalkulátor tetején keskeny fejléc-szalag a saját képével.": "Calculadoras: en la parte superior de cada calculadora, una estrecha cinta de cabecera con su propia imagen.",
  "Egyes telefonokon (például Huawei P20) induláskor láthatatlan maradt a belépő képernyő, és nem reagáltak az ikonok: a belépő réteg és az oldal most kényszerítve rajzolódik ki indításkor és visszatéréskor.": "En algunos teléfonos (por ejemplo, Huawei P20) la pantalla de acceso se quedaba invisible al iniciar y los iconos no respondían: la capa de acceso y la página se dibujan ahora de forma forzada al iniciar y al volver.",
  "Biblia-ébresztő: ha a csengőhang nem indulna el, tartalék hang szól a riasztási hangerőn, így rezgő telefonon is hallható.": "Alarma bíblica: si el tono de llamada no arrancara, suena un sonido de reserva al volumen de alarma, así que se oye también con el teléfono en vibración.",
  "Ébresztő bekapcsolásakor az app azonnal szól, ha hiányzik hozzá egy engedély (értesítés, pontos ébresztő, teljes képernyős értesítés), és egy gombbal a beállításhoz visz.": "Al activar la alarma, la app avisa al instante si le falta un permiso (notificaciones, alarma exacta, notificación a pantalla completa), y con un botón te lleva al ajuste.",
  "Biblia-ébresztő: rezgő vagy néma telefonon is megszólal (a hang a riasztási hangerőn szól), a PrepperPapában és a Wordlight Bibliában is.": "Alarma bíblica: suena también con el teléfono en vibración o en silencio (el sonido va al volumen de alarma), en PrepperPapa y en la Biblia de Wordlight.",
  "Fiók törlése: a Profil > Fiók kártyán véglegesen törölheted a fiókodat; előtte biztonsági mentést készíthetsz.": "Eliminar cuenta: en la tarjeta Perfil > Cuenta puedes eliminar tu cuenta definitivamente; antes puedes hacer una copia de seguridad.",
  "Napi Gerah: minden nap, amikor eléred a napi Ige-célodat, egy Gerah-t kapsz; a reggeli ébresztő felolvasása is beleszámít.": "Gerah diario: cada día que alcanzas tu meta diaria con la Palabra recibes un Gerah; la lectura en voz alta de la alarma matutina también cuenta.",
  "A felolvasott vers ködös kiemelése most egyben átcsúszik a következő versre, és minden betű teljesen a ködön van.": "El resaltado con niebla del versículo leído pasa ahora de una sola vez al versículo siguiente, y todas las letras quedan completamente dentro de la niebla.",
  "A jó minőségű felvett hang angolul a teljes Bibliára letölthető, a többi nyelven a Jelenések könyvére; más nyelven két hang közül választhatsz: a telefon hangja vagy a felvett hang.": "La voz grabada de alta calidad se puede descargar en inglés para toda la Biblia, y en los demás idiomas para el Apocalipsis; en otros idiomas puedes elegir entre dos voces: la voz del teléfono o la voz grabada.",
  "A nyelvválasztóban minden nyelv a saját nevén szerepel.": "En el selector de idioma, cada idioma aparece con su propio nombre.",
  "Biblia: az eredeti szó (Strong-szótár) mostantól mind a nyolc nyelv saját Bibliáján működik; a szócikk magyarul és németül fordítva, a többi nyelven angolul.": "Biblia: la palabra original (diccionario Strong) funciona ahora en la Biblia propia de los ocho idiomas; la entrada está traducida al húngaro y al alemán, y en los demás idiomas está en inglés.",
  "Napi idő az Igével: a cél elérésekor teljes képernyős gratuláció, és a reggeli ébresztő felolvasása is beleszámít a napi időbe.": "Tiempo diario con la Palabra: al alcanzar la meta, felicitación a pantalla completa, y la lectura en voz alta de la alarma matutina también cuenta en el tiempo diario.",
  "Wordlight: a beállítások alján ajánló a teljes PrepperPapa alkalmazásról.": "Wordlight: al final de los ajustes, una recomendación de la app PrepperPapa completa.",
  "PrepperPapa Biblia: a beállítások alján rövid ismertető a Biblia prémiumról (csak ingyenes felhasználóknak).": "Biblia de PrepperPapa: al final de los ajustes, una breve presentación de Biblia Premium (solo para usuarios gratuitos).",
  "Napi idő az Igével: a fejléc alatti csík helyett halvány gyűrű a Biblia fogaskereke körül, koppintásra mutatja a perceket; a fejezetek végén egy halk sor a mai időről.": "Tiempo diario con la Palabra: en lugar de la franja bajo la cabecera, un anillo tenue alrededor del engranaje de la Biblia, que al tocarlo muestra los minutos; al final de los capítulos, una línea discreta con el tiempo de hoy.",
  "A „Napi idő az Igével” beállítás a Biblia beállítások saját helyére került, a hangok közül kivéve.": "El ajuste «Tiempo diario con la Palabra» tiene ahora su propio lugar en los ajustes de la Biblia, fuera de las voces.",
  "A felolvasott vers ködös kiemelése most minden oldalán elhalványul, éles szél nélkül.": "El resaltado con niebla del versículo leído se desvanece ahora por todos sus lados, sin borde marcado.",
  "A PrepperPapa Bibliája görgetéskor ugyanazt a zöld fényvonalat kapja a fejléc alatt, mint a Wordlight.": "Al desplazarse, la Biblia de PrepperPapa recibe bajo la cabecera la misma línea de luz verde que Wordlight.",
  "Felolvasáskor a telefon lejátszója a Biblia lámpás képét mutatja.": "Durante la lectura en voz alta, el reproductor del teléfono muestra la imagen de la lámpara de la Biblia.",
  "A felolvasó hangválasztó sok hang esetén is olvasható.": "El selector de voz de lectura se puede leer también cuando hay muchas voces.",
  "Biblia felolvasás: a felolvasott vers zöld kiemelése már nem éles szélű doboz, hanem a betűk szélétől lágyan elhalványul.": "Lectura en voz alta de la Biblia: el resaltado verde del versículo leído ya no es un recuadro de bordes marcados, sino que se desvanece suavemente desde el borde de las letras.",
  "A PrepperPapa Bibliája is csillagos égbolt hátteret kapott, mint a Wordlight alkalmazás (nappali módban).": "La Biblia de PrepperPapa también tiene fondo de cielo estrellado, como la app Wordlight (en modo diurno).",
  "Napi idő az Igével. Beállítható napi cél (5-60 perc), a fejléc alatti vonal mutatja, mennyi van hátra, a cél elérésekor gratuláció.": "Tiempo diario con la Palabra. Meta diaria ajustable (5-60 minutos), la línea bajo la cabecera muestra cuánto queda, y al alcanzar la meta, una felicitación.",
  "Biblia alkalmazás (Wordlight): a nyitóoldalon a fogaskerék és a súgó gomb feljebb, a jobb felső sarokba került, nem takarja a feliratot.": "App de la Biblia (Wordlight): en la página de inicio, el engranaje y el botón de ayuda han subido a la esquina superior derecha y no tapan el texto.",
  "Nagyobb betűméretnél a kezdőlap csempéin a hosszú egyszavas feliratok (pl. Kommunikáció, Vagyonkezelő) nem törnek két sorba.": "Con un tamaño de letra mayor, los textos largos de una sola palabra de los mosaicos del inicio (por ejemplo, Comunicación, Patrimonio) no se parten en dos líneas.",
  "Nagyobb betűméretnél a tájoló tárcsája már nem lóg ki a képernyőről, és a fejlécben az app neve és verziója sem csonkul.": "Con un tamaño de letra mayor, el disco de la brújula ya no se sale de la pantalla, y el nombre y la versión de la app en la cabecera tampoco se cortan.",
  "Kezdőlap: a Tudástár csempe fölött ugyanakkora a hézag, mint a csempék között.": "Inicio: el espacio sobre el mosaico de la Base de conocimientos es igual que entre los mosaicos.",
  "Visszajelzés: ha a képernyőkép fekete lenne, nem csatolja, hanem felajánlja a kép kézi feltöltését.": "Comentarios: si la captura de pantalla saliera negra, no la adjunta, sino que ofrece subir la imagen a mano.",
  "Biblia alkalmazás (Wordlight): a nyitóoldalon középen a lámpás, alatta a Wordlight és a Biblia felirat; a lámpás nagyobb és közelebb a felirathoz; görgetéskor a fejléc lassan elhalványul.": "App de la Biblia (Wordlight): en la página de inicio, la lámpara en el centro, y debajo los textos Wordlight y Biblia; la lámpara es más grande y está más cerca del texto; al desplazarse, la cabecera se atenúa lentamente.",
  "Térkép: a letöltött saját térkép azonnal megjelenik, nem vár előbb a szerver válaszára (gyenge hálózaton eddig sokáig üres maradt, miközben a GPS-pont már látszott).": "Mapa: el mapa propio descargado aparece al instante, sin esperar antes la respuesta del servidor (con red débil se quedaba vacío mucho tiempo, aunque el punto GPS ya se veía).",
  "Biblia alkalmazás (Wordlight): ott nyílik meg, ahol legutóbb olvastál, a fejezetnél és a versnél; ha a nyitólapra léptél vissza, a nyitólappal indul.": "App de la Biblia (Wordlight): se abre donde leíste por última vez, en el capítulo y el versículo; si volviste a la página de inicio, empieza por la página de inicio.",
  "A felugró kérdés- és üzenetablakok már nem átlátszók, a mögöttük lévő szöveg nem zavarja az olvasást.": "Las ventanas emergentes de preguntas y mensajes ya no son transparentes, y el texto que hay detrás no estorba la lectura.",
  "Helyi szoba: a háttérben futó figyelő is hitelesítve kapcsolódik a központhoz, így az üzenet-, vészjelzés- és panelriasztás-ébresztés a szigorú védelem bekapcsolása után is működik.": "Sala local: el vigilante que funciona en segundo plano también se conecta autenticado al centro, así que el despertar por mensajes, alertas de emergencia y alarmas del panel funciona también tras activar la protección estricta.",
  "Biblia: ha a Biblia beállításaiban nyelvet váltasz, a Biblia azonnal átvált az új nyelvre, és a jegyzetek (Scofield, mértékegységek) is bekapcsolhatók.": "Biblia: si cambias de idioma en los ajustes de la Biblia, la Biblia pasa al instante al nuevo idioma, y las notas (Scofield, unidades de medida) también se pueden activar.",
  "Biblia alkalmazás (Wordlight): a fejlécben a verziószám balra, a Biblia felirat jobbra igazodik, a felirat közelebb van a lámpáshoz.": "App de la Biblia (Wordlight): en la cabecera, el número de versión se alinea a la izquierda y el texto Biblia a la derecha, y el texto está más cerca de la lámpara.",
  "Biblia: az olvasási terv oldal a terveid listájával nyílik, a listáról belépsz egy tervbe és folytatod; az új terv nem rejti el a régieket.": "Biblia: la página del plan de lectura se abre con la lista de tus planes; desde la lista entras en un plan y continúas; un plan nuevo no oculta los anteriores.",
  "Biblia alkalmazás (Wordlight): sötétebb ikon, és a fejlécben a Biblia felirat a Wordlight jobb széléhez igazodik.": "App de la Biblia (Wordlight): icono más oscuro, y en la cabecera el texto Biblia se alinea con el borde derecho de Wordlight.",
  "Biblia prémium, eredeti szó: a Strong-szótár szócikke magyarul jelenik meg (gépi fordítás).": "Biblia Premium, palabra original: la entrada del diccionario Strong aparece en húngaro (traducción automática).",
  "Biblia: Jézus szavai világosabb színnel; a kikapcsolója a Biblia beállításaiban van.": "Biblia: las palabras de Jesús en un color más claro; el interruptor para desactivarlo está en los ajustes de la Biblia.",
  "Biblia alkalmazás (Wordlight): minden beállítás (nyelv, adatkezelés, feloldás, névjegy) a saját Biblia-beállításaiban, a PrepperPapa beállításai nem nyílnak meg.": "App de la Biblia (Wordlight): todos los ajustes (idioma, privacidad, desbloqueo, Acerca de) están en sus propios ajustes de la Biblia, y los ajustes de PrepperPapa no se abren.",
  "Biblia alkalmazás (Wordlight): a fejléc felirata a megtervezett betűvel jelenik meg.": "App de la Biblia (Wordlight): el texto de la cabecera aparece con la tipografía diseñada.",
  "Biblia: ha nyitva van a Strong-szótár vagy egy versmenü, a háttérben a Biblia már nem mozdul el.": "Biblia: si está abierto el diccionario Strong o un menú de versículo, la Biblia del fondo ya no se mueve.",
  "Biblia alkalmazás (Wordlight): a térképen csak az alaptérkép, a műhold és a világhelyzet választható.": "App de la Biblia (Wordlight): en el mapa solo se pueden elegir el mapa base, el satélite y la situación mundial.",
  "Biblia alkalmazás (Wordlight): nincs benne tesztelési visszajelzés és napi tesztfeladat.": "App de la Biblia (Wordlight): no incluye comentarios de prueba ni tarea de prueba diaria.",
  "Biblia: Jézus szavai alapból piros színnel jelennek meg (a Beállításokban kikapcsolható).": "Biblia: las palabras de Jesús aparecen por defecto en rojo (se puede desactivar en Ajustes).",
  "Biblia alkalmazás (Wordlight): a nyelvválasztó a Beállításokba került, a fejlécből kikerült.": "App de la Biblia (Wordlight): el selector de idioma ha pasado a Ajustes y ya no está en la cabecera.",
  "Biblia alkalmazás (Wordlight): a fejléc a csillagos háttér része lett, görgetéskor egy halvány zöld fénycsík és a lámpás jelzi, hogy a szöveg alá csúszik.": "App de la Biblia (Wordlight): la cabecera forma parte del fondo estrellado; al desplazarse, una tenue franja de luz verde y la lámpara indican que el texto pasa por debajo.",
  "Biblia alkalmazás: saját helyi címen fut, így ha a PrepperPapa is telepítve van, egyik app sem nyílik meg többé üresen a másik miatt.": "App de la Biblia: funciona en su propia dirección local, así que si PrepperPapa también está instalada, ninguna de las dos apps vuelve a abrirse vacía por culpa de la otra.",
  "Biblia alkalmazás (Wordlight): saját logó a fejlécben, halvány csillagos háttér, és a fejlécből közvetlenül váltható a nyelv.": "App de la Biblia (Wordlight): logotipo propio en la cabecera, fondo estrellado tenue, y el idioma se cambia directamente desde la cabecera.",
  "Biblia alkalmazás: a csak PrepperPapához tartozó ablakok és gombok már nem jelennek meg benne.": "App de la Biblia: ya no aparecen en ella las ventanas y botones que solo pertenecen a PrepperPapa.",
  "Gerah: ha a fizető telefonja nem kapja meg időben a nyugtát, az üzenet most a helyes QR-irányt mondja meg.": "Gerah: si el teléfono del que paga no recibe a tiempo el recibo, el mensaje indica ahora la dirección correcta del QR.",
  "Helyi szoba: a bázis panel saját képet kapott, és a szoba gazdáját a telefon helyesen ismeri fel.": "Sala local: el panel base tiene imagen propia, y el teléfono reconoce correctamente al anfitrión de la sala.",
  "Biblia alkalmazás: új ikon (lámpás kereszt-lánggal).": "App de la Biblia: nuevo icono (lámpara con llama en forma de cruz).",
  "Helyi szoba: a szobának küldött kéréseket a telefon mostantól aláírja, így egy idegen eszköz nem adhatja ki magát tagnak.": "Sala local: el teléfono firma ahora las solicitudes enviadas a la sala, así que un dispositivo ajeno no puede hacerse pasar por miembro.",
  "Biblia: a Jelenések könyve jó minőségű, felvett hanggal mindenkinek ingyenesen letölthető, és internet nélkül is hallgatható; a többi könyv jó minőségű hangja Biblia prémiummal tölthető le. A telefon saját felolvasója továbbra is ingyenes.": "Biblia: el Apocalipsis, con voz grabada de alta calidad, se puede descargar gratis para todos y escuchar también sin internet; la voz de alta calidad de los demás libros se descarga con Biblia Premium. La lectura en voz alta propia del teléfono sigue siendo gratuita.",
  "Biblia: ritkán, bezárhatóan megjelenik egy rövid ajánló arról, mit ad a Biblia prémium; felolvasás közben soha.": "Biblia: de vez en cuando, y con opción de cerrarla, aparece una breve recomendación de lo que ofrece Biblia Premium; nunca durante la lectura en voz alta.",
  "Fordítások: néhány felirat a térképen, az imaidőzítőben és a heti olvasási terveknél most már minden nyelven megjelenik.": "Traducciones: algunos textos del mapa, del temporizador de oración y de los planes de lectura semanales aparecen ahora en todos los idiomas.",
  "Biblia: a bekapcsolt ébresztőt már nem narancs pötty jelzi (ami üzenetnek tűnt), hanem a gomb zölden kiemelve.": "Biblia: la alarma activada ya no se indica con un punto naranja (que parecía un mensaje), sino con el botón resaltado en verde.",
  "Biblia prémium: a magyar Károliban egy szóra koppintva megjelenik az eredeti héber, arámi vagy görög szó, átírással, Strong-számmal és jelentéssel. Ahol nincs biztos egyezés, ezt kiírja.": "Biblia Premium: en la Károli húngara, al tocar una palabra aparece la palabra original hebrea, aramea o griega, con transliteración, Número Strong y significado. Donde no hay una correspondencia segura, lo indica.",
  "Biblia prémium: a Jelenések könyve felvett hanggal letölthető, és internet nélkül is hallgatható. A Bibliában ritkán, bezárhatóan megjelenik egy rövid ajánló arról, mit ad a prémium.": "Biblia Premium: el Apocalipsis se puede descargar con voz grabada y escuchar también sin internet. En la Biblia aparece de vez en cuando, con opción de cerrarla, una breve recomendación de lo que ofrece Premium.",
  "iPhone: a fémdetektor most már értéket mutat; a tájoló és az esésérzékelő nem kér többé angol nyelvű engedélyt; a számológép alsó sora nem csúszik a menüsor alá; az engedélykérő szövegek ékezetesek.": "iPhone: el detector de metales ya muestra un valor; la brújula y el detector de caídas ya no piden permiso en inglés; la fila inferior de la calculadora no se mete bajo la barra de menú; los textos de solicitud de permisos llevan acentos.",
  "Térkép: nagyításkor és görgetéskor nincsenek többé szürke vagy fekete foltok, a térkép nem töltődik újra minden megnyitáskor, és a turistapontok nem villognak el mozgatás közben.": "Mapa: al ampliar y desplazar ya no hay manchas grises o negras, el mapa no se recarga cada vez que se abre, y los puntos de senderismo no parpadean al moverlo.",
  "Térkép: a háttér gyorsabban, kb. egy másodperc alatt rajzolódik ki nagyítás után; a szintvonalak csak utána töltődnek.": "Mapa: el fondo se dibuja más rápido, en un segundo aproximadamente tras ampliar; las curvas de nivel se cargan después.",
  "Nyelvek: a Mit pakoljak? lista, a tájoló felvett iránya és égtájai, az SOS vészkártya-szöveg, a Biblia könyvrövidítései és letöltési állapota, a lámpa és a térkép feliratai mostantól minden nyelven a saját nyelvükön jelennek meg.": "Idiomas: la lista ¿Qué llevo?, la dirección registrada y los puntos cardinales de la brújula, el texto de la tarjeta de emergencia SOS, las abreviaturas de los libros de la Biblia y su estado de descarga, y los textos de la Lámpara y del mapa aparecen ahora en todos los idiomas en su propio idioma.",
  "Mit pakoljak?: idegen nyelvű felületen a vízi, téli, őszi és nyári túrához tartozó tételek eddig kimaradtak a listából, most bekerülnek.": "¿Qué llevo?: en la interfaz en otros idiomas faltaban en la lista los elementos de las excursiones acuáticas, de invierno, de otoño y de verano; ahora se incluyen.",
  "Helyi szoba: a szoba gazdájának telefonja mostantól mindig a saját szobáját szolgálja ki, és nem próbál Bluetooth-on egy másik készüléken lévő másolathoz kapcsolódni (ettől állt a szoba 25 másodpercig „a gazda nem válaszol” hibával a gazda saját telefonján).": "Sala local: el teléfono del anfitrión atiende ahora siempre su propia sala y no intenta conectarse por Bluetooth a una copia en otro dispositivo (por eso la sala se quedaba 25 segundos con el error «el anfitrión no responde» en el propio teléfono del anfitrión).",
  "iPhone: a Bluetooth-szoba azonosítója és a helyi szoba előzménye mostantól megmarad az app újraindítása után (eddig az iPhone minden indításkor új tagnak látszott a Bluetooth-szobákban).": "iPhone: el identificador de la sala Bluetooth y el historial de la sala local se conservan ahora tras reiniciar la app (hasta ahora, en cada inicio el iPhone aparecía como un miembro nuevo en las salas Bluetooth).",
  "Helyi szoba: ha a telefon nem éri el a szoba gazdáját, az app pontosabban feljegyzi, mit lát a hálózaton (saját cím, hallott szobák), hogy a hibát meg lehessen találni.": "Sala local: si el teléfono no llega al anfitrión de la sala, la app registra con más precisión lo que ve en la red (dirección propia, salas detectadas), para poder encontrar el fallo.",
  "iPhone: az engedély-kapu a bejelentkezés után megnyílik, újraindítás után is nyitva marad, kijelentkezve zárva (az app saját fájljai a Library mappába kerültek).": "iPhone: la puerta de permisos se abre tras iniciar sesión, sigue abierta tras reiniciar y queda cerrada al cerrar sesión (los archivos propios de la app han pasado a la carpeta Library).",
  "Szoba-riasztás előreugrása: az eszköz-riasztás (például a bázis panel riasztója) oldala akkor is előreugrik, ha épp a telefont használod, nem csak lezárt képernyőn. Ehhez a rendszer egy egyszeri engedélyt kér: a szoba beállításaiban megjelenik egy „Megjelenítés más alkalmazások felett” gomb, amíg nincs megadva. Ugyanott látszik, ha az értesítés vagy a teljes képernyős értesítés hiányzik.": "Alarma de sala en primer plano: la página de una alarma de dispositivo (por ejemplo, la alarma del panel base) salta al frente también cuando estás usando el teléfono, no solo con la pantalla bloqueada. Para ello el sistema pide un permiso único: en los ajustes de la sala aparece un botón «Mostrar sobre otras apps» mientras no se haya concedido. Ahí mismo se ve si faltan las notificaciones o la notificación a pantalla completa.",
  "Biblia, Scofield-jegyzetek magyarul: a magyar Bibliánál mostantól az eredeti magyar kiadás jegyzetei jelennek meg (Scofield Magyarázó jegyzetek a Bibliához, Evangéliumi Kiadó, a kiadó engedélyével), a korábbi saját fordítás helyett. A könyvek bevezetője az első fejezet első versénél, a jegyzetek előtt áll. A forrás a jegyzetek alatt, apró betűvel látszik. A többi nyelv jegyzetei nem változtak.": "Biblia, notas de Scofield en húngaro: en la Biblia húngara aparecen ahora las notas de la edición húngara original (Scofield Magyarázó jegyzetek a Bibliához, Evangéliumi Kiadó, con permiso de la editorial), en lugar de la traducción propia anterior. La introducción de cada libro está en el primer versículo del primer capítulo, antes de las notas. La fuente se ve en letra pequeña bajo las notas. Las notas de los demás idiomas no han cambiado.",
  "Gerah, érintéses fizetés egyszerűbben: a fizetésnél elég az összeg és a miért, a címzett és az azonosító mezői csak az „Érintés nélkül” gombbal nyílnak le (QR-kód, szobatárs). A „Fizetés érintéssel” gombon NFC-jel van, és ha az NFC vagy a Bluetooth ki van kapcsolva, a tárca megnyitásakor rögtön felajánlja a bekapcsolását. Sikeres érintés után a nyugta QR-kódja eltűnik, csak egy „Kész” üzenet marad, és a gombok felirata nem lóg ki.": "Gerah, pago por contacto más sencillo: para pagar basta con el importe y el motivo; los campos del destinatario y del identificador solo se despliegan con el botón «Sin contacto» (código QR, compañero de sala). El botón «Pagar por contacto» lleva el símbolo NFC, y si el NFC o el Bluetooth están desactivados, al abrir el monedero ofrece activarlos enseguida. Tras un contacto correcto, el código QR del recibo desaparece, solo queda un mensaje «Hecho», y los textos de los botones no se salen.",
  "Gerah, fizetés érintéssel (az appban): a fogadó a „Fogadás érintéssel” gombot nyomja meg, a fizető beírja az összeget, és a „Fizetés érintéssel” gombot. Egy összeérintéssel átmegy a fogadó azonosítója, utána az aláírt fizetés, végül vissza a nyugta; a fizetés csak akkor készül el és csak akkor vonódik le, amikor a fogadó azonosítója már megérkezett. Mindkét telefon lépésenként kiírja, hol tart, és ha nem történik semmi, megmondja, mit kell a másik telefonon megnyomni. A QR-kódos út változatlanul megmarad.": "Gerah, pago por contacto (en la app): quien recibe pulsa el botón «Recibir por contacto», y quien paga escribe el importe y pulsa «Pagar por contacto». Con un solo contacto pasa el identificador de quien recibe, después el pago firmado y por último, de vuelta, el recibo; el pago solo se crea y solo se descuenta cuando ya ha llegado el identificador de quien recibe. Los dos teléfonos indican paso a paso por dónde van y, si no ocurre nada, dicen qué hay que pulsar en el otro teléfono. La vía del código QR se mantiene sin cambios.",
  "Gerah, „átadásra vár” tétel: a Mozgások között az ilyen tételnél „Újra átadás” gomb van. Ugyanazt az aláírt fizetést adja át újra (QR-kóddal vagy érintéssel), nem újat; a fogadónál másodszor nem íródik jóvá, csak a nyugta készül el újra, így a tétel lezárulhat.": "Gerah, elemento «pendiente de entrega»: en Movimientos, estos elementos tienen un botón «Entregar de nuevo». Entrega otra vez el mismo pago firmado (con código QR o por contacto), no uno nuevo; a quien recibe no se le abona una segunda vez, solo se vuelve a crear el recibo, así que el elemento puede cerrarse.",
  "Szobák: csatlakozáskor és később a szoba beállításaiban szobánként beállíthatod, hogy az SOS-jelzésed oda is menjen-e, és ha igen, látszik-e benne a GPS-helyzeted és a vércsoportod. Ahol az SOS ki van kapcsolva, oda semmi nem megy; ahol a hely vagy a vércsoport ki van kapcsolva, abból a szobának szánt üzenetből már a telefonon kimarad. A meglévő szobákban mindhárom be van kapcsolva, ahogy eddig. A helyi (internet nélküli) szobákra is vonatkozik.": "Salas: al unirte y después en los ajustes de la sala puedes decidir, sala por sala, si tu alerta SOS se envía también allí y, en ese caso, si incluye tu posición GPS y tu grupo sanguíneo. Donde el SOS está desactivado no se envía nada; donde la ubicación o el grupo sanguíneo están desactivados, se quitan ya en el teléfono del mensaje destinado a esa sala. En las salas existentes las tres opciones están activadas, como hasta ahora. También se aplica a las salas locales (sin internet).",
  "Barométer és Napkelte, napnyugta: a Tájoló alól átkerültek az Eszközök közé, mindkettő saját lapon nyílik. A légnyomás előzménye, a riasztás és az értesítés beállítása, valamint a nap- és holdidők számítása változatlan; a légnyomás-értesítés koppintásra a Barométert nyitja. A Tájolón az irány, a hangvezetés és a kamerás nap-pálya marad.": "Barómetro y Amanecer, atardecer: han pasado de Orientación a Herramientas, y cada uno se abre en su propia página. El historial de presión atmosférica, los ajustes de alarma y notificación y el cálculo de las horas del sol y la luna no cambian; al tocar la notificación de presión atmosférica se abre el Barómetro. En Orientación quedan la dirección, la guía por sonido y la trayectoria del sol con la cámara.",
  "Térkép, útvonaltervezés: a tervezés kártyáján megadhatod az indulás napját és idejét (alapból most). A kártya kiírja a napnyugtát és a sötétedést, hogy napnyugta előtt vagy után érkezel, és ha az út a sötétedés után is tart, mennyi marad sötétben. Az útvonalon jel mutatja, hol leszel napnyugtakor és sötétedéskor, a lépéslistában pedig minden lépés mellett ott a várható időpont. Internet nélkül számol, a menetidővel azonos tempóval.": "Mapa, planificación de rutas: en la tarjeta de planificación puedes indicar el día y la hora de salida (por defecto, ahora). La tarjeta indica la puesta de sol y el anochecer, si llegas antes o después de la puesta de sol y, si el trayecto sigue después del anochecer, cuánto queda a oscuras. En la ruta, una marca muestra dónde estarás a la puesta de sol y al anochecer, y en la lista de pasos aparece junto a cada paso la hora prevista. Calcula sin internet, al mismo ritmo que el tiempo de trayecto.",
  "Morze vétel hangból (mikrofon): a hang végét az app most az adott hang saját erősségéhez méri. Így a szoba visszhangja, a hangszóró utózengése és a telefon zajszűrője okozta lecsengés vagy rövidülés kevésbé keveri össze a pontot és a vonást, a betűk nem folynak egybe, a sebesség-csúszka és a kalibráció a valódi tempót mutatja. A visszajelzésbe az app beleteszi, hogy a telefon ténylegesen kikapcsolta-e a mikrofon zajszűrését és hangerő-szabályzását.": "Recepción de Morse por sonido (micrófono): la app mide ahora el final del tono según la intensidad propia de ese tono. Así, la reverberación de la habitación, la resonancia del altavoz y el decaimiento o acortamiento causado por el filtro de ruido del teléfono confunden menos el punto y la raya, las letras no se juntan, y el control de velocidad y la calibración muestran el ritmo real. En los comentarios, la app incluye si el teléfono desactivó realmente la reducción de ruido y el control de volumen del micrófono.",
  "Visszajelzés ablak: a beírt szöveg és a kiválasztott típus, modul magától piszkozatként megmarad, ha az ablak véletlenül bezárul. Újranyitáskor visszakerül, és csak sikeres küldés után törlődik.": "Ventana de comentarios: el texto escrito y el tipo y módulo elegidos se guardan solos como borrador si la ventana se cierra por accidente. Al volver a abrirla se recuperan, y solo se borran tras un envío correcto.",
  "Bibliai térkép: az összecsukott információs sáv alja már nem vágódik le, a gombok és a szöveg középen állnak, fent és lent egyforma a térköz.": "Mapa bíblico: la parte inferior de la barra de información plegada ya no se corta, los botones y el texto están centrados, y el espacio arriba y abajo es igual.",
  "Profil: az „A neved” mező az app újraindítása után is a mentett nevet mutatja (eddig üresnek látszott, amíg a Szobák képernyőt meg nem nyitottad). Az üresnek látszó mezőbe írt, majd kitörölt karakter már nem törli a mentett nevet. Ha a név mégis elveszett, az app induláskor visszaveszi a profilból készült Gerah-azonosítóból.": "Perfil: el campo «Tu nombre» muestra el nombre guardado también tras reiniciar la app (hasta ahora parecía vacío hasta que abrías la pantalla Salas). Un carácter escrito y luego borrado en el campo que parecía vacío ya no borra el nombre guardado. Si el nombre aun así se perdió, la app lo recupera al iniciar a partir del identificador Gerah creado con el perfil.",
  "A bibliai térkép a kiválasztott helyet a térkép látható részének közepére teszi, nem az információs ablak alá.": "El mapa bíblico coloca el lugar elegido en el centro de la parte visible del mapa, no debajo de la ventana de información.",
  "Az információs ablak a jobb felső sarokban lévő nyíllal összecsukható, ilyenkor csak az ige és a hely neve látszik; újabb koppintásra kinyílik. A térkép mindkét esetben a helyre igazodik.": "La ventana de información se pliega con la flecha de la esquina superior derecha, y entonces solo se ven el versículo y el nombre del lugar; con otro toque se despliega. En ambos casos el mapa se ajusta al lugar.",
  "A bibliai térképen a helyek jól látható, nagyobb jelölőt kaptak, a nevük olvashatóbb, és az egymáshoz közeli helyek feliratai nem takarják egymást. Műholdképen, alaptérképen és éjszakai módban is.": "En el mapa bíblico, los lugares tienen marcadores más grandes y bien visibles, sus nombres se leen mejor, y los textos de lugares cercanos no se tapan entre sí. También con imagen de satélite, mapa base y modo nocturno.",
  "Az app felkészült arra, hogy a jövőben frissítés nélkül, távolról is megjelenhessen egy-egy „Hirdetés” jelölésű ajánló egyes képernyők alján. Alapból sehol nincs bekapcsolva, a képernyők változatlanok.": "La app está preparada para que en el futuro pueda aparecer a distancia, sin actualizar, una recomendación marcada como «Anuncio» al pie de algunas pantallas. Por defecto no está activada en ninguna parte, y las pantallas no cambian.",
  "A Kockázatelemzés mindig a helyszínek áttekintésével nyílik meg, nem a legutóbb megnézett helyszín részleteivel. A részletek a helyszín kártyájára koppintva nyílnak meg.": "El Análisis de riesgos se abre siempre con la vista general de los lugares, no con los detalles del último lugar consultado. Los detalles se abren al tocar la tarjeta del lugar.",
  "Az „Ajánld egy barátodnak” kártya most megmutatja a jutalmat: minden barátodért, aki aktiválja a profilját, 10 gerah-t kapsz, ha prémiumot választ, további 50-et.": "La tarjeta «Recomiéndalo a un amigo» muestra ahora la recompensa: por cada amigo que active su perfil recibes 10 gerah, y si elige Premium, 50 más.",
  "Gerah: érintéses fizetésnél a fogadó telefon magától várja a fizetést, miután a fizető érintéssel átvette a kódját – nem kell megnyomni a Beolvasás gombot, csak újra összetartani a két telefont. Ha a QR-kódot kamerával olvassátok be, marad a Beolvasás gomb.": "Gerah: en el pago por contacto, el teléfono que recibe espera el pago solo, después de que quien paga haya recogido su código por contacto: no hace falta pulsar el botón Escanear, basta con volver a juntar los dos teléfonos. Si leéis el código QR con la cámara, se mantiene el botón Escanear.",
  "A választólisták és felugró ablakok bezáródnak, ha másik oldalra lépsz, és az Android Vissza gomb először a nyitott listát zárja be.": "Las listas de selección y las ventanas emergentes se cierran al pasar a otra página, y el botón Atrás de Android cierra primero la lista abierta.",
  "Offline térkép: letölthető egy választható világtérkép (az egész Föld áttekintő nagyításban, kb. 190 MB).": "Mapa sin conexión: se puede descargar un mapa del mundo opcional (toda la Tierra con zoom de vista general, unos 190 MB).",
  "Offline térkép: az egész Magyarország letöltésénél a Megszakítás csak a saját területeit állítja le, a többi letöltést (például a világtérképet) nem.": "Mapa sin conexión: al descargar toda Hungría, Cancelar solo detiene sus propias zonas, no las demás descargas (por ejemplo, el mapa del mundo).",
  "Biztonsági mentés: a teljes mentést egy saját mentési kulcs védi, amit mentéskor te adsz meg, és érdemes felírnod. A mentésben benne van a Token tárca és a Gerah is; visszatöltés után a tárca a régi PIN-kóddal nyílik. A saját fényképezett térképek is a mentésbe kerülnek, és visszatöltés előtt az app rákérdez, ha a telefonon már vannak saját adataid.": "Copia de seguridad: la copia completa está protegida por una clave de copia propia que indicas tú al guardar, y conviene que la anotes. La copia incluye la Cartera de tokens y el Gerah; tras restaurarla, el monedero se abre con el PIN anterior. Los mapas propios fotografiados también entran en la copia, y antes de restaurar la app te pregunta si ya tienes datos propios en el teléfono.",
  "Gerah: fizetés érintéssel. Androidon a két telefon összeérintésével (NFC), iPhone-nal Bluetooth-on, ha a két telefon szinte összeér. A QR-kód továbbra is mindenhol működik.": "Gerah: pago por contacto. En Android juntando los dos teléfonos (NFC), y con iPhone por Bluetooth, si los dos teléfonos casi se tocan. El código QR sigue funcionando en todas partes.",
  "Offline térkép: a letöltés akkor is folytatódik, ha másik oldalra lépsz, kikapcsol a képernyő vagy másik appot nyitsz; megszakadt kapcsolat után onnan folytatja, ahol abbahagyta. Egyszerre több területet is kijelölhetsz letöltésre.": "Mapa sin conexión: la descarga continúa aunque pases a otra página, se apague la pantalla o abras otra app; tras una conexión interrumpida, sigue desde donde lo dejó. Puedes marcar varias zonas para descargar a la vez.",
  "Térkép: a kórház, a temető, a menedékház, a szálláshely, a bolt és a posta saját ikont kapott nagy kerek jelölőben; koppintásra jön fel az adatlap. Egy saját pont jelölőjének cseréjénél a választó már nyitva marad, és a buborék linkjeit könnyebb eltalálni.": "Mapa: el hospital, el cementerio, el refugio, el alojamiento, la tienda y la oficina de correos tienen icono propio en un marcador grande y redondo; al tocarlo aparece la ficha. Al cambiar el marcador de un punto propio, el selector ahora se queda abierto, y es más fácil acertar en los enlaces de la burbuja.",
  "Légnyomás: kevesebb energiával mér, a gyors változásoknál sűrűbben. Új kapcsoló: „Autóban ne riasszon” – járműben ülve nem jön viharriasztás.": "Presión atmosférica: mide con menos energía, y con más frecuencia ante cambios rápidos. Nuevo interruptor: «Sin alarma en un vehículo»: si vas en un vehículo no llega la alarma de tormenta.",
  "Frissítés: a letöltés kikapcsolt képernyővel és másik appra váltva is folytatódik, megszakadt hálózat után onnan megy tovább, ahol abbahagyta. Ha közben nem az app van elöl, értesítés szól, hogy telepíthető.": "Actualización: la descarga continúa también con la pantalla apagada y al cambiar a otra app, y tras un corte de red sigue desde donde lo dejó. Si mientras tanto la app no está en primer plano, una notificación avisa de que se puede instalar.",
  "Gyülekező: a fórumban is látszik az alsó menüsáv, a felső „× Gyülekező” sáv eltűnt. A vissza gomb előbb a fórumon belül lép vissza.": "Punto de reunión: en el foro también se ve la barra de menú inferior, y ha desaparecido la barra superior «× Punto de reunión». El botón Atrás primero retrocede dentro del foro.",
  "Térkép: új pont létrehozásakor 11 kategóriából saját jelölőt lehet választani (víz, menedék, gyülekezőhely, veszély, tűzrakóhely és a többi), később is módosítható. Az alaptérkép jelölői (vízvételi hely, csúcsok és a többi) árnyékot kaptak.": "Mapa: al crear un punto nuevo puedes elegir un marcador propio entre 11 categorías (agua, refugio, punto de reunión, peligro, lugar para hacer fuego y otras), que también se puede cambiar después. Los marcadores del mapa base (punto de agua, cumbres y otros) tienen sombra.",
  "Térkép: a keresőbe koordinátát is be lehet írni (például 47,4778349, 19,4234878 vagy 47.4778 19.4234). Az első találatra koppintva a térkép odaugrik és ideiglenes jelölőt tesz le; a buborék „Mentés pontként” gombjával lehet belőle saját pont.": "Mapa: en el buscador también puedes escribir coordenadas (por ejemplo, 47,4778349, 19,4234878 o 47.4778 19.4234). Al tocar el primer resultado, el mapa salta allí y coloca un marcador temporal; con el botón «Guardar como punto» de la burbuja puedes convertirlo en un punto propio.",
  "Térkép: kevesebb memóriát használ, ezért hosszabb használat után sem tűnik el a jobb felső gomb ikonja, és nem maradnak ki csempék a térkép szélén.": "Mapa: usa menos memoria, así que tampoco tras un uso prolongado desaparece el icono del botón superior derecho, ni faltan mosaicos en el borde del mapa.",
  "Internetes szobák: egy üzenetet (hosszan nyomva) vagy egy tagot (a taglistában hosszan nyomva) be lehet jelenteni a PrepperPapa csapatának, okkal és megjegyzéssel. A bejelentett üzenet nálad azonnal eltűnik, a többieknél ellenőrzésig összecsukva marad.": "Salas por internet: puedes denunciar un mensaje (manteniéndolo pulsado) o un miembro (manteniéndolo pulsado en la lista de miembros) al equipo de PrepperPapa, con motivo y comentario. El mensaje denunciado desaparece al instante para ti, y para los demás queda plegado hasta su revisión.",
  "Internetes szobák: egy felhasználót le lehet tiltani. Az üzeneteit nálad elrejtjük, és privát üzenetet nem küldhet neked; a letiltást a Beállításokban lehet feloldani.": "Salas por internet: puedes bloquear a un usuario. Ocultamos sus mensajes para ti y no puede enviarte mensajes privados; el bloqueo se quita en Ajustes.",
  "Gyülekező: az alkalmazásban a fórum az appon belül nyílik meg, saját képernyőn, bezáró gombbal; a bejelentkezés megmarad. Androidon az első megnyitáskor egyszer felajánlja, hogy a Gyülekezőt kiteszi a kezdőképernyőre, és az is az appban nyitja meg.": "Punto de reunión: en la app, el foro se abre dentro de la app, en su propia pantalla, con un botón de cerrar; la sesión se mantiene. En Android, la primera vez ofrece una vez poner el Punto de reunión en la pantalla de inicio, y también se abre en la app.",
  "Helyi szoba: az esés miatti SOS üzenet a szobában a szövegével jelenik meg, nem olvashatatlan kódként.": "Sala local: el mensaje SOS por caída aparece en la sala con su texto, no como un código ilegible.",
  "Helyi szoba: a gépi üzenetek (Gerah-könyv, névjegy) nem küldenek többé üres értesítést.": "Sala local: los mensajes automáticos (libro Gerah, tarjeta de contacto) ya no envían notificaciones vacías.",
  "Kommunikáció: a Helyi szoba (MESH) mellett ismét a LoRa-jel áll.": "Comunicación: junto a Sala local (MESH) vuelve a estar el símbolo LoRa.",
  "Térkép, tűzgyújtási tilalom: a külföldi hivatalos tilalmak (Kanada, Egyesült Államok, Portugália) országonként saját jelet kapnak távolról, nem a magyar jelbe olvadnak; a buborékuk a tilalom fajtáját, a területet, a hivatalos szöveget mutatja, és jelzi, hogy a helyi (községi) tilalmakat a forrás nem tartalmazza.": "Mapa, prohibición de hacer fuego: las prohibiciones oficiales extranjeras (Canadá, Estados Unidos, Portugal) tienen de lejos un símbolo propio por país, sin fundirse con el símbolo húngaro; su burbuja muestra el tipo de prohibición, la zona y el texto oficial, e indica que la fuente no incluye las prohibiciones locales (municipales).",
  "Helyi szoba: nem jelenik meg többé „Zárt üzenet” a saját neveden, amit nem te írtál. A telefon a Gerah-könyvét magától átküldi a szobába, és a szoba gazdájának telefonja eddig a hosszú üzenetet 3000 karakternél levágta, így senki nem tudta kinyitni. Most vágás nélkül átmegy (16 000 karakterig, fölötte a küldés hibát jelez és később újra próbálja), és a gépi üzenetek akkor sem látszanak, ha nem nyílnak ki. A korábban levágott csomagok is eltűnnek az előzményből.": "Sala local: ya no aparece un «Mensaje cerrado» con tu nombre que no escribiste tú. El teléfono envía solo su libro Gerah a la sala, y hasta ahora el teléfono del anfitrión cortaba ese mensaje largo en 3000 caracteres, así que nadie podía abrirlo. Ahora pasa sin cortes (hasta 16 000 caracteres; por encima, el envío da error y se reintenta más tarde), y los mensajes automáticos no se ven aunque no se abran. Los paquetes cortados anteriormente también desaparecen del historial.",
  "Térkép: könnyebb lett. A világhelyzet csak a képernyő környékén levő eseményeket rajzolja ki, nem az egész bolygót minden mozdulatnál; a turistautak tájegységei és a külföldi főút-csempék csak akkor vannak a térképen, ha a képernyő közelében járunk, a régieket elengedi a memóriából; húzás és nagyítás után egyszer frissít, a mozdulat végén. Kicsinyítve (Európa-nézet) a túraútvonalak nem maradnak a háttérben.": "Mapa: es más ligero. La situación mundial solo dibuja los sucesos cercanos a la pantalla, no todo el planeta en cada movimiento; las regiones de los senderos y los mosaicos de carreteras principales extranjeras solo están en el mapa cuando estamos cerca de la pantalla, y los antiguos se liberan de la memoria; tras arrastrar y ampliar se actualiza una vez, al final del gesto. Con el zoom alejado (vista de Europa), las rutas de senderismo no se quedan en segundo plano.",
  "Térkép: a tűzgyújtási tilalom saját réteg lett a turistautak mellett (eddig a világhelyzet része volt). Aki a világhelyzetet bekapcsolva tartotta, annál ez is be van kapcsolva. A megjelenés ugyanaz: távolról egy jel Magyarország fölött a megyék listájával, közelítve megyénként narancs fátyol.": "Mapa: la prohibición de hacer fuego es ahora una capa propia junto a las rutas de senderismo (antes formaba parte de la situación mundial). Si tenías activada la situación mundial, esta también está activada. El aspecto es el mismo: de lejos, un símbolo sobre Hungría con la lista de condados, y al acercarse un velo naranja por condado.",
  "Térkép: a fátyol és a térkép alja nem vágódik le egy egyenes vonalnál, ha a térkép mérete menet közben változik.": "Mapa: el velo y la parte inferior del mapa no se cortan en una línea recta si el tamaño del mapa cambia mientras tanto.",
  "Térkép: a tűzgyújtási tilalom fátyla egyenletes lett, a megyék határán nem sötétebb, a körvonalak lekerekítettek, nem szögletesek.": "Mapa: el velo de la prohibición de hacer fuego es ahora uniforme, no más oscuro en los límites de los condados, y los contornos son redondeados, no angulosos.",
  "Térkép: a frissítés kijelzése kis üveg-kapszula lett (óra és „29 perce”), pár másodperc után csak az óra marad; koppintásra kinyílik a teljes szöveg, a jelmagyarázat és a források.": "Mapa: el indicador de actualización es ahora una pequeña cápsula de cristal (hora y «hace 29 min»), y tras unos segundos solo queda la hora; al tocarla se despliegan el texto completo, la leyenda y las fuentes.",
  "Légnyomás: ha a mérésekben hézag van, a trend és az előrejelzés-ikon a hézag előtti utolsó mérésből számol (közelítő trendként jelölve), nem tűnik el.": "Presión atmosférica: si hay un hueco en las mediciones, la tendencia y el icono de previsión se calculan a partir de la última medición anterior al hueco (marcada como tendencia aproximada), en lugar de desaparecer.",
  "Helyi szoba: az üzenet-beíró kapszula nem lóg ki jobbra, a küldés gomb teljesen látszik. Nagyobb (115%) betűméretnél a szobák képernyője nem nyúlik a menüsor alá, a beíró sor a helyén marad.": "Sala local: la cápsula de escritura de mensajes no se sale por la derecha y el botón de enviar se ve entero. Con un tamaño de letra mayor (115%), la pantalla de salas no se mete bajo la barra de menú y la línea de escritura se queda en su sitio.",
  "Kommunikáció: a Helyi szoba (MESH) mellett semleges hálózat-ikon áll a korábbi LoRa-jel helyett.": "Comunicación: junto a Sala local (MESH) hay un icono de red neutro en lugar del anterior símbolo LoRa.",
  "Fax: a cím és a csempe újra „Fax (SSTV)”. Bibliai térkép: a forrássor mellett újra a teljes mondat áll, hogy a területhatárok közelítő rekonstrukciók.": "Fax: el título y el mosaico vuelven a ser «Fax (SSTV)». Mapa bíblico: junto a la línea de la fuente vuelve a aparecer la frase completa de que los límites de los territorios son reconstrucciones aproximadas.",
  "Víztisztítás számoló: a magasság-választóban az alsó lehetőség neve egyszerűen „2000 m alatt”, országnév nélkül, minden nyelven.": "Calculadora de potabilización del agua: en el selector de altitud, la opción inferior se llama simplemente «Por debajo de 2000 m», sin nombre de país, en todos los idiomas.",
  "Víztisztítás számoló: a víz fajtájánál a hideg víz helyett „Zavaros, színes vagy jéghideg (pl. olvadt hó, jeges patak)” áll, a számítás nem változott. A magasságot nem méterben kell beírni, hanem két lehetőség közül választani: 2000 m alatt vagy 2000 m felett. A számoló eredménye mostantól az app nyelvén jelenik meg (eddig más nyelven is magyarul állt).": "Calculadora de potabilización del agua: en el tipo de agua, en lugar de agua fría aparece «Turbia, con color o helada (por ejemplo, nieve derretida, arroyo helado)»; el cálculo no ha cambiado. La altitud no se escribe en metros, sino que se elige entre dos opciones: por debajo de 2000 m o por encima de 2000 m. El resultado de la calculadora aparece ahora en el idioma de la app (hasta ahora salía en húngaro también en otros idiomas).",
  "Biblia beállítások: rendezettebb lett. A könyvszínek neve Színes és Egyszínű (a választásod megmaradt). A kereszthivatkozások, a Scofield-jegyzet és a mértékegységek egy blokkban, „Megjelenítés az igék mellett” címmel kapcsolhatók. A felolvasó hang egy listából választható (a telefon hangja, Imre, Charon), a letöltés egy sorban, egy gombbal indul és állítható meg; a könyvenkénti lista a „Könyvenként” alatt maradt.": "Ajustes de la Biblia: más ordenados. Los colores de los libros se llaman En color y Monocromo (tu elección se mantiene). Las referencias cruzadas, la Nota de Scofield y las unidades de medida se activan en un solo bloque, titulado «Mostrar junto a los versículos». La voz de lectura se elige en una lista (voz del teléfono, Imre, Charon), y la descarga se inicia y se detiene en una sola línea, con un solo botón; la lista por libros sigue en «Por libro».",
  "Biblia, ébresztő: az olvasási terv oldaláról kikerült az ébresztő doboz, helyette a Biblia fejlécében egy kis ébresztőóra ikon nyitja az ébresztők oldalát (pötty jelzi, ha van bekapcsolt). Több ébresztő is beállítható, mindegyiknél kiválasztható, melyik olvasási terv mai olvasmányát olvassa fel. Ha az ébresztő végigolvassa a napi olvasmányt, az a nap magától elolvasottnak számít; ha közben leállítod, nem. A korábbi ébresztőd átkerült az új listába.": "Biblia, alarma: la caja de la alarma ha desaparecido de la página del plan de lectura; en su lugar, un pequeño icono de despertador en la cabecera de la Biblia abre la página de alarmas (un punto indica si hay alguna activada). Puedes configurar varias alarmas, y en cada una elegir de qué plan de lectura lee la lectura de hoy. Si la alarma lee entera la lectura del día, ese día cuenta solo como leído; si la detienes antes, no. Tu alarma anterior ha pasado a la nueva lista.",
  "Visszajelzés ablak: tömörebb, felülről nyílik le, és felfelé söpörve vagy az alján levő Bezárás fogóval zárható. Amit beküldesz, az nem változott.": "Ventana de comentarios: más compacta, se despliega desde arriba y se cierra deslizando hacia arriba o con el tirador Cerrar de abajo. Lo que envías no ha cambiado.",
  "Hirdetések: a tesztidőszakra a prémium fiókban is bekapcsolható a felugró hirdetés, ugyanazokkal a korlátokkal, mint az ingyenes változatban (minden második megnyitáskor, naponta legfeljebb ötször). A prémium funkciók ettől nem változnak, mind nyitva maradnak.": "Anuncios: durante el periodo de prueba, el anuncio emergente también se puede activar en la cuenta Premium, con los mismos límites que en la versión gratuita (cada segunda apertura, como máximo cinco veces al día). Las funciones Premium no cambian por ello y siguen todas abiertas.",
  "Gyülekező: a főoldali csempe új ikont kapott, a fórum logójának tüzét, zöldben, mint a többi gomb.": "Punto de reunión: el mosaico de la página principal tiene un nuevo icono, el fuego del logotipo del foro, en verde, como los demás botones.",
  "Noah minden nyelven jobban ért: a lejárt készletre vonatkozó kérdést, a „nézd meg jobban” kérést egy bibliai válasz után, és a betűvel írt számokat (például „négy fő”) az app mind a nyolc nyelvén felismeri. A Noah-nak adott utasítások és a beállításai (letöltés, Rólam, a válasz alatti mérés) is az app nyelvén jelennek meg.": "Noah entiende mejor en todos los idiomas: reconoce en los ocho idiomas de la app la pregunta sobre reservas caducadas, la petición «míralo mejor» tras una respuesta bíblica y los números escritos con letras (por ejemplo, «cuatro personas»). Las instrucciones dadas a Noah y sus ajustes (descarga, Sobre mí, la medición bajo la respuesta) también aparecen en el idioma de la app.",
  "Prémium kód: a kódot tartalmazó linkre koppintva megnyílik az app, a Beállítások Feloldás részén a kód már be van írva, és csak a „Kód beváltása” gombra kell koppintani. Ha előbb be kell lépned, a kód a belépés után is ott marad.": "Código Premium: al tocar el enlace con el código se abre la app, el código ya está escrito en la sección Desbloquear de Ajustes, y solo hay que tocar el botón «Canjear código». Si primero tienes que iniciar sesión, el código sigue ahí después.",
  "Eszközök: új Napelem-beállítás. Megadod a helyet (helymeghatározással vagy kézzel) és a napot (dátum, vagy egy gombbal a téli és nyári napforduló, a tavaszi és őszi napéjegyenlőség, ma), és megmutatja a nap aznapi járását ábrán, a napkeltét, a delelést és a napnyugtát, hogy merre nézzen a panel, mennyire dőljön aznapra, arra az évszakra és egész évre fixen, és hány óra napsütés várható derült égnél. A panel teljesítményét megadva nagyjából kiszámolja a napi termelést (becslés, felhő nélkül). Egy gombbal a tájoló kamerás nézete nyílik, a választott nap pályájával, hogy a panelt a helyére igazítsd.": "Herramientas: nuevo Ajuste del panel solar. Indicas el lugar (con geolocalización o a mano) y el día (fecha, o con un botón el solsticio de invierno y de verano, el equinoccio de primavera y de otoño, hoy), y muestra en un gráfico el recorrido del sol ese día, el amanecer, el mediodía solar y la puesta de sol, hacia dónde debe mirar el panel, cuánto debe inclinarse para ese día, para esa estación y fijo para todo el año, y cuántas horas de sol se esperan con cielo despejado. Si indicas la potencia del panel, calcula aproximadamente la producción diaria (estimación, sin nubes). Con un botón se abre la vista con cámara de la brújula, con la trayectoria del sol del día elegido, para colocar el panel en su sitio.",
  "Térkép, offline: ha a szerveren egy már letöltött tájegység térképe újabb, a tájegység sorában „Frissítés (méret)” gomb jelenik meg, és a Teljes Magyarország letöltése is hiányzónak számolja. Eddig a telefon a régi letöltött térképet mutatta, és semmi nem jelezte, hogy van újabb.": "Mapa sin conexión: si en el servidor el mapa de una región ya descargada es más reciente, en la línea de la región aparece un botón «Actualizar (tamaño)», y la descarga de toda Hungría también la cuenta como pendiente. Hasta ahora el teléfono mostraba el mapa antiguo descargado y nada indicaba que hubiera uno más nuevo.",
  "Teszt-adatok: a főoldali négy kártya egyike az autó helyett a hétvégi ház, saját készlettel, így valódi százalékokat mutat.": "Datos de prueba: una de las cuatro tarjetas de la página principal es la casa de fin de semana en lugar del coche, con reservas propias, así que muestra porcentajes reales.",
  "Helyi szoba: a saját üzeneteid a saját telefonodon sosem jelennek meg „Zárt üzenet”-ként. A telefon minden kulcsot megjegyez, amivel valaha küldött, és ha két szoba között váltasz, miközben az üzenetek még nyílnak, egyik szoba kulcsa sem kerül át a másikba.": "Sala local: tus propios mensajes nunca aparecen como «Mensaje cerrado» en tu propio teléfono. El teléfono recuerda todas las claves con las que ha enviado alguna vez, y si cambias entre dos salas mientras los mensajes aún se están abriendo, la clave de una sala no pasa a la otra.",
  "Helyi szoba: a zárt üzenet buborékja rövid („Zárt üzenet”), nem nyúlik szélesebbre a többi üzenetnél.": "Sala local: la burbuja del mensaje cerrado es corta («Mensaje cerrado») y no se hace más ancha que los demás mensajes.",
  "Helyi szoba: ha a telefon a közös Wi-Fi-n nem éri el a szoba gazdáját (például mert a router nem engedi, hogy a telefonok egymással beszéljenek), és a gazda Bluetooth-on a közelben van, a telefon magától átvált Bluetooth-ra, és ezt egy sorban ki is írja. Ha a Wi-Fi később újra eléri a gazdát, visszavált rá.": "Sala local: si el teléfono no llega al anfitrión de la sala por el Wi-Fi común (por ejemplo, porque el router no deja que los teléfonos se comuniquen entre sí) y el anfitrión está cerca por Bluetooth, el teléfono cambia solo a Bluetooth y lo indica en una línea. Si más tarde el Wi-Fi vuelve a llegar al anfitrión, vuelve a él.",
  "Helyi szoba Bluetooth-on: a szoba borítóképe és a tagok profilképe kis méretben ott is megjelenik (egyszer töltődik le, utána a telefon megjegyzi). A nagy kép továbbra sem megy Bluetooth-on, hogy ne lassítsa el a kapcsolatot.": "Sala local por Bluetooth: la imagen de portada de la sala y las fotos de perfil de los miembros también aparecen allí en tamaño pequeño (se descargan una vez y luego el teléfono las recuerda). La imagen grande sigue sin enviarse por Bluetooth, para no ralentizar la conexión.",
  "Térkép, offline: a tájegységek saját, teljes képernyős oldalon nyílnak meg (Térkép-funkciók > Tájegységek letöltése), nem egy kis görgethető ablakban. Egy tájegység letöltése mindig együtt hozza az alaptérképet, a turistautakat és a turistapontokat; ha egy tájegységről csak az alaptérkép van a telefonon, a „Hiányzó részek letöltése” pótolja a többit.": "Mapa sin conexión: las regiones se abren en su propia página a pantalla completa (Funciones del mapa > Descargar regiones), no en una pequeña ventana con desplazamiento. La descarga de una región trae siempre juntos el mapa base, los senderos y los puntos de senderismo; si de una región solo tienes el mapa base en el teléfono, «Descargar las partes que faltan» completa el resto.",
  "Tájoló, hangvezetés: az egész hangskála feljebb került, a jó irány hangja jobban hallható. A ritmus és a logika ugyanaz: a jó irányban a legmélyebb, nyugodt kettős sípolás, eltérésnél egyre magasabb és sűrűbb.": "Orientación, guía por sonido: toda la escala de sonido ha subido, y el sonido de la dirección correcta se oye mejor. El ritmo y la lógica son los mismos: en la dirección correcta, el doble pitido más grave y tranquilo, y al desviarse, cada vez más agudo y seguido.",
  "Újdonságok ablak: görgetéskor a szöveg nem csúszik át a címen, a bezáró gomb kerek, a cím mellett.": "Ventana de Novedades: al desplazarse, el texto no pasa por encima del título, y el botón de cerrar es redondo, junto al título.",
  "Helyi szoba: ha a szoba gazdája közben új jelszót adott meg, a vendég telefonja a legújabb üzenetek kulcsával küld. Eddig az előzmény legrégebbi üzenetének kulcsánál ragadhatott, és az így küldött üzenetek a gazdánál (és később nála is) „Zárt üzenet”-ként jelentek meg. A régi kulccsal írt üzenetek olvashatók maradnak.": "Sala local: si mientras tanto el anfitrión de la sala ha puesto una contraseña nueva, el teléfono del invitado envía con la clave de los mensajes más recientes. Hasta ahora podía quedarse con la clave del mensaje más antiguo del historial, y los mensajes enviados así aparecían como «Mensaje cerrado» para el anfitrión (y después también para el invitado). Los mensajes escritos con la clave antigua siguen siendo legibles.",
  "Helyi szoba: a beíró sor nem takarja el a lap alján lévő gombokat (például „Vissza a saját szobámba”); ha nem fér ki minden, a lap görgethető.": "Sala local: la línea de escritura no tapa los botones del pie de la página (por ejemplo, «Volver a mi sala»); si no cabe todo, la página se puede desplazar.",
  "Kommunikáció és Helyi szobák listája: a profilod a fejlécben, a kérdőjel mellett, ugyanúgy, mint a Szobáknál (koppintásra a Profil nyílik); a Kommunikáció tetején álló külön sor megszűnt.": "Lista de Comunicación y de Salas locales: tu perfil aparece en la cabecera, junto al signo de interrogación, igual que en Salas (al tocarlo se abre el Perfil); ha desaparecido la línea aparte de arriba de Comunicación.",
  "Helyi szoba, súgó (?): elmondja, mire jó a helyi szoba (internet nélkül, egy Wi-Fi-n, például áramszünetben vagy otthon a családdal), és lépésenként végigvezet: szoba nyitása az egyik telefonon, belépés a másikról, mit jelentenek a pontok, és mit tegyél, ha a gazda nem érhető el.": "Sala local, ayuda (?): explica para qué sirve la sala local (sin internet, en un mismo Wi-Fi, por ejemplo durante un apagón o en casa con la familia), y te guía paso a paso: abrir la sala en un teléfono, entrar desde el otro, qué significan los puntos y qué hacer si no se puede llegar al anfitrión.",
  "Helyi szoba: a szobához csatlakozás nem várakozik többé a szoba kulcsának ellenőrzésére. Ha az lassú vagy elakad, a kapcsolat akkor is felépül, és legfeljebb 4 másodperc után a meglévő kulccsal megy tovább.": "Sala local: la conexión a la sala ya no espera a que se compruebe la clave de la sala. Si eso es lento o se atasca, la conexión se establece igualmente, y como máximo a los 4 segundos continúa con la clave existente.",
  "Helyi szoba: ha háromszor egymás után nem éri el a szoba gazdáját, rövid ideig újra keresi a hálózaton (ha a gazda új címet kapott, átáll rá és megjegyzi), és kiírja, mit érdemes ellenőrizni: ugyanaz a Wi-Fi, a router elszigetelheti a készülékeket, mobiladat ki; mellette a saját és a szoba címe, eltérő hálózatnál külön figyelmeztetéssel.": "Sala local: si tres veces seguidas no llega al anfitrión de la sala, lo vuelve a buscar brevemente en la red (si el anfitrión tiene una dirección nueva, cambia a ella y la recuerda), e indica qué conviene comprobar: el mismo Wi-Fi, que el router puede aislar los dispositivos, los datos móviles desactivados; al lado, la dirección propia y la de la sala, con un aviso aparte si la red es distinta.",
  "Helyi szobák: egy hatótávon kívüli szoba (például az Eszközök) koppintásra a saját nevével nyílik meg, és kiírja, hogy a gazdája most nem érhető el; eddig az előzőleg megnyitott szoba neve állt a fejlécben. A lista fejléce mindig a lista címe.": "Salas locales: una sala fuera de alcance (por ejemplo, Herramientas) se abre al tocarla con su propio nombre, e indica que su anfitrión no está disponible ahora; hasta ahora la cabecera mostraba el nombre de la sala abierta antes. La cabecera de la lista es siempre el título de la lista.",
  "Helyi szoba: a technikai adatok (a másik telefon címe, a Bluetooth-számlálók) egy kis „Részletek” sor alá kerültek.": "Sala local: los datos técnicos (la dirección del otro teléfono, los contadores de Bluetooth) están ahora bajo una pequeña línea «Detalles».",
  "Kommunikáció: a lap tetején a profilod (kép és név), koppintásra a Profil nyílik; ha még nincs, „Hozd létre a profilodat”. Profil nélkül a Kommunikáció és a Helyi szoba egyszer felkínálja a beállítását, a bemutató után.": "Comunicación: arriba de la página aparece tu perfil (foto y nombre), y al tocarlo se abre el Perfil; si aún no lo tienes, «Crea tu perfil». Sin perfil, Comunicación y Sala local ofrecen una vez configurarlo, después de la presentación.",
  "Mit vigyek?: rendezettebb lap. A résztvevők egyforma kártyákon, mellettük, hányan mennek; az utazás módja és a víz kétállású kapcsoló, az út típusa gombsor, a napok száma mínusz-plusz léptető.": "¿Qué llevo?: página más ordenada. Los participantes en tarjetas iguales, con cuántos van al lado; el modo de viaje y el agua son interruptores de dos posiciones, el tipo de viaje una fila de botones, y el número de días un selector con menos y más.",
  "Noah: az útvonal-válaszban a helyek alcíme (saját pont, helyszín és típusa, település, turistapont és magassága) az app nyelvén jelenik meg.": "Noah: en la respuesta de ruta, el subtítulo de los lugares (punto propio, lugar y su tipo, localidad, punto de senderismo y su altitud) aparece en el idioma de la app.",
  "Noah: minden válasza alatt „Válasz jelentése” gomb. Ha egy válasz sértő, veszélyes vagy téves, egy koppintással jelezheted nekünk; ilyenkor csak a kérdés és a válasz szövege jut el hozzánk. Internet nélkül a jelentés elmentődik, és magától elmegy, amint lesz kapcsolat.": "Noah: bajo cada respuesta, un botón «Denunciar esta respuesta». Si una respuesta es ofensiva, peligrosa o errónea, puedes avisarnos con un toque; en ese caso solo nos llega el texto de la pregunta y de la respuesta. Sin internet, la denuncia se guarda y se envía sola en cuanto haya conexión.",
  "Noah: a beállításai alatt új „Noah névjegye” rész: a Google Gemma 4 nyílt modellel működik (Apache 2.0 licenc), a licenc linkjével.": "Noah: en sus ajustes, nueva sección «Acerca de Noah»: funciona con el modelo abierto Google Gemma 4 (licencia Apache 2.0), con el enlace a la licencia.",
  "Noah reggeli összefoglalója: minden reggel 7:00-kor (a beállításainál átállítható vagy kikapcsolható) értesítés a készlet hiányairól, a készenléti szintről, egy igével és egy felkészülési tanáccsal. Noah-t megnyitva kártyaként is látod.": "Resumen matutino de Noah: cada mañana a las 7:00 (se puede cambiar o desactivar en sus ajustes), una notificación sobre lo que falta en las reservas, el nivel de preparación, con un versículo y un consejo de preparación. Al abrir Noah también lo ves como tarjeta.",
  "Noah az app nyelvén beszél: a bemutatkozás, a képességei, a kiszámolt válaszok (készenlét, hiányok, lejáratok, háztartás, napkelte) és a gépi válaszok is az app nyelvén jönnek; a Bibliában az adott nyelv saját fordításában keres.": "Noah habla el idioma de la app: la presentación, sus capacidades, las respuestas calculadas (preparación, faltas, caducidades, hogar, amanecer) y las respuestas automáticas llegan en el idioma de la app; en la Biblia busca en la traducción propia de ese idioma.",
  "Tájoló: álló, kamerás nézetben a nap mai járása vonalként a képen, napkeltétől napnyugtáig, órajelekkel és a nap mostani helyével, hogy a napelemet hozzá tudd igazítani. Éjszaka és helyzet nélkül kiírja, miért nincs vonal.": "Orientación: en la vista vertical con cámara, el recorrido del sol de hoy aparece como una línea en la imagen, del amanecer a la puesta de sol, con marcas horarias y la posición actual del sol, para que puedas orientar el panel solar. De noche y sin ubicación, indica por qué no hay línea.",
  "Frissítés: a letöltés és a telepítés állapota egyetlen sorban látszik a képernyő tetején (Letöltés 47% → Telepítés… → Erősítsd meg a rendszer ablakában, hiba esetén Újra gomb). Megszűnt a fejléc alatti külön sárga doboz, ami eltakarta a logót, és a százalék sem jelenik meg kétszer.": "Actualización: el estado de la descarga y la instalación se ve en una sola línea arriba de la pantalla (Descarga 47% → Instalando… → Confírmalo en la ventana del sistema, y en caso de error un botón Reintentar). Ha desaparecido el recuadro amarillo aparte bajo la cabecera que tapaba el logotipo, y el porcentaje ya no aparece dos veces.",
  "Visszajelzés: a mezők rendezettebbek (felirat a mező fölött, nagyobb távolság). Az appban egy gombnyomással csatolható a képernyőkép arról a képernyőről, ahonnan a visszajelzést megnyitottad; a kép feltöltése a galériából is megmaradt. A csatolt képnél bélyegkép és × törlés.": "Comentarios: los campos están más ordenados (etiqueta sobre el campo, más separación). En la app, con un botón se adjunta la captura de la pantalla desde la que abriste los comentarios; también se mantiene la subida de imagen desde la galería. La imagen adjunta tiene miniatura y × para borrarla.",
  "Térkép, offline: a Magyarország tájegységei fölött új „Teljes Magyarország letöltése” gomb. Előtte kiírja, mennyit tölt le, mennyi van már a telefonon, és mennyi a szabad hely; ha nincs elég hely, szól és nem indul el. Tájegységenként halad, megszakítható, és a Folytatás onnan folytatja.": "Mapa sin conexión: sobre las regiones de Hungría, nuevo botón «Descargar toda Hungría». Antes indica cuánto va a descargar, cuánto hay ya en el teléfono y cuánto espacio libre queda; si no hay espacio suficiente, avisa y no empieza. Avanza región por región, se puede interrumpir, y Continuar sigue desde ahí.",
  "Térkép: a külföldi és magyar turistaút-tervező hálózat kisebb lett (kb. harmadával kevesebb letöltés), ugyanazokkal az útvonalakkal.": "Mapa: la red de planificación de senderos extranjeros y húngaros es más pequeña (aproximadamente un tercio menos de descarga), con las mismas rutas.",
  "Helyi szoba: nem jelennek meg többé „Zárt üzenet”-ként a saját és a többiek üzenetei, ha a szoba kulcsa két helyen eltérően volt eltárolva, vagy ha újra beírtad a jelszót: az előző kulcsot is megőrzi, és a régi üzenetek olvashatók maradnak. A tagok profilképe is megjelenik.": "Sala local: tus mensajes y los de los demás ya no aparecen como «Mensaje cerrado» si la clave de la sala estaba guardada de forma distinta en dos sitios o si volviste a escribir la contraseña: también conserva la clave anterior, y los mensajes antiguos siguen siendo legibles. También aparecen las fotos de perfil de los miembros.",
  "Saját térkép: megjelennek a fontos helyek, új, saját ikonokkal: kórház, orvos, gyógyszertár, rendőrség, tűzoltóság, benzinkút, turistaház és menedék, kemping, ivóvíz, élelmiszerbolt, templom, iskola, posta, szállás, étterem, vár és rom, múzeum, látnivaló, állomás, komp, parkoló és még sok más. Az ikon mellett a hely neve áll; a fontosabbak már távolabbi nézetben, a kisebb boltok közelebb nagyítva jelennek meg, egymást nem takarják.": "Mapa propio: aparecen los lugares importantes, con iconos nuevos y propios: hospital, médico, farmacia, policía, bomberos, gasolinera, refugio de montaña y refugio, camping, agua potable, tienda de alimentación, iglesia, escuela, oficina de correos, alojamiento, restaurante, castillo y ruinas, museo, lugar de interés, estación, ferry, aparcamiento y mucho más. Junto al icono figura el nombre del lugar; los más importantes aparecen ya en vistas más lejanas y las tiendas pequeñas al acercarse, sin taparse entre sí.",
  "Saját térkép: a hegycsúcsok nevét és magasságát is kiírja (például Kékes 1014 m).": "Mapa propio: también muestra el nombre y la altitud de las cumbres (por ejemplo, Kékes 1014 m).",
  "Saját térkép: új rétegek: településhatár (halvány szaggatott vonal), városrészek neve közeli nézetben, kompjáratok (kék szaggatott vonal), csatornák, vizenyős terület (mintával), szikla, sportpálya, kert, óvoda, vasúti terület, peron, gát; nagy védett területek, hegységek és tavak neve dőlt betűvel. Éjszakai módban is.": "Mapa propio: nuevas capas: límite municipal (línea discontinua tenue), nombres de barrios en vista cercana, líneas de ferry (línea discontinua azul), canales, zonas pantanosas (con trama), roca, campo deportivo, jardín, guardería, zona ferroviaria, andén, presa; los nombres de grandes áreas protegidas, sierras y lagos en cursiva. También en modo nocturno.",
  "Frissítés: telepítés közben a felső sáv egysoros („Telepítés folyamatban…”), nem foglal el több helyet a képernyőből.": "Actualización: durante la instalación, la barra superior ocupa una sola línea («Instalación en curso…») y no ocupa más espacio de la pantalla.",
  "Frissítés: a telepítés után az app magától újra megnyílik. Ahol az Android ezt nem engedi (Android 10-től, ha épp használod a telefont), egy értesítés jelenik meg, egy koppintással megnyitja.": "Actualización: tras la instalación, la app se vuelve a abrir sola. Donde Android no lo permite (desde Android 10, si estás usando el teléfono), aparece una notificación que la abre con un toque.",
  "Vércsoport-kalkulátor: nincs többé „Mutasd” gomb, az eredmény a vércsoport kiválasztásakor azonnal megjelenik. A kalkulátorból egy gombbal megnyitható a Tudástár 3.6 (Vércsoport) cikke.": "Calculadora de grupo sanguíneo: ya no hay botón «Mostrar», el resultado aparece al instante al elegir el grupo sanguíneo. Desde la calculadora, un botón abre el artículo 3.6 (Grupo sanguíneo) de la Base de conocimientos.",
  "Frissítés: az új verzió letöltése már csak akkor indul el, ha megnyomod a frissítés gombot a fejlécben (vagy a frissítési képernyőn). Magától, éjszaka sem tölt le és nem telepít semmit.": "Actualización: la descarga de la nueva versión solo empieza cuando pulsas el botón de actualizar en la cabecera (o en la pantalla de actualización). Por sí sola, tampoco de noche, no descarga ni instala nada.",
  "Frissítés: a gomb megnyomása után látszik, mi történik: keresés, letöltés százalékban, telepítés, és ha valami nem sikerül, érthető hibaüzenet és Újra gomb.": "Actualización: después de pulsar el botón se ve qué ocurre: búsqueda, descarga en porcentaje, instalación y, si algo falla, un mensaje de error comprensible y un botón Reintentar.",
  "Frissítési képernyő: a „Most a régi verzióval folytatom (30 perc)” lehetőség már az első megjelenéskor ott van, nem csak egy sikertelen telepítés után.": "Pantalla de actualización: la opción «Por ahora sigo con la versión antigua (30 minutos)» ya está desde la primera vez que aparece, no solo tras una instalación fallida.",
  "Biblia: a Scofield-jegyzetek, a mértékegységek és az apokrif könyvek (Énok könyveivel együtt) most a Bibliával együtt töltődnek le, külön letöltés nélkül. A Biblia beállításaiban csak a megjelenítésük kapcsolható ki és be.": "Biblia: las notas de Scofield, las unidades de medida y los libros apócrifos (junto con los libros de Enoc) se descargan ahora con la Biblia, sin descarga aparte. En los ajustes de la Biblia solo se activa y desactiva su visualización.",
  "Biblia felolvasás: ha egy könyv új, jobb minőségű hangja teljesen letöltődött a telefonra, a régi gépi hang ugyanannak a könyvnek a felvételét az app magától törli, hogy helyet szabadítson fel.": "Lectura en voz alta de la Biblia: cuando la nueva voz de mejor calidad de un libro se ha descargado por completo en el teléfono, la app borra sola la grabación de la antigua voz sintética de ese mismo libro, para liberar espacio.",
  "Tudástár 3.6 (Vércsoport): a cikkből egy gombbal megnyitható a Vércsoport-kalkulátor, és két új kép került a cikkbe.": "Base de conocimientos 3.6 (Grupo sanguíneo): desde el artículo, un botón abre la Calculadora de grupo sanguíneo, y se han añadido dos imágenes nuevas al artículo.",
  "Gerah: a tárca képernyőjén, ahol az induló egyenleg megjelenik, ott áll a tájékoztatás is: a Gerah jutalom, nem pénz.": "Gerah: en la pantalla del monedero, donde aparece el saldo inicial, también figura la aclaración: Gerah es una recompensa, no dinero.",
  "Ajánld egy barátodnak (Beállítások): egyetlen rendezett kártya. Az „Ajánlói linkem megosztása” gomb a saját ajánlói linkedet küldi el; aki azzal érkezik, annál a kód magától beváltódik, nem kell beírni. A kézi beírás a „Van ajánlókódod?” alatt van.": "Recomiéndalo a un amigo (Ajustes): una sola tarjeta ordenada. El botón «Compartir mi enlace de recomendación» envía tu propio enlace de recomendación; a quien llega con él se le canjea el código solo, sin tener que escribirlo. La introducción manual está en «¿Tienes un código de recomendación?».",
  "Ajánlói jutalom: a barátod prémium-vásárlása utáni 50 gerah 14 nap elteltével kerül jóváírásra (visszatérített vásárlás után nem jár); fiókonként összesen legfeljebb 50 ajánlás után jár jutalom.": "Recompensa por recomendación: los 50 gerah por la compra Premium de tu amigo se abonan pasados 14 días (no se dan si la compra se reembolsa); por cuenta, hay recompensa como máximo por 50 recomendaciones en total.",
  "Gerah: mindenki 20 gerah induló egyenleget kap a PrepperPapától, egyszer, amikor a Gerah-tárcája elkészül (a meglévő tárcák is).": "Gerah: todos reciben de PrepperPapa un saldo inicial de 20 gerah, una vez, cuando se crea su monedero Gerah (también los monederos existentes).",
  "Tudástár: a cikkekben a forrás-linkek koppintásra megnyílnak, és a hosszú cím nem lóg ki a képernyőről.": "Base de conocimientos: en los artículos, los enlaces a las fuentes se abren al tocarlos, y los títulos largos no se salen de la pantalla.",
  "Biblia: olvasás, könyv- és fejezetválasztás közben eltűnt a fejlécből a „?” gomb (ott nem a Bibliához tartozó súgót mutatta).": "Biblia: al leer y al elegir libro y capítulo, ha desaparecido de la cabecera el botón «?» (ahí no mostraba la ayuda de la Biblia).",
  "Eszközök szoba: ha a bázis panel kb. három és fél percig nem jelez (például áramszünet vagy kihúzták), a szobában megjelenik: „megszűnt a tápellátás, a panel nem jelez”; amikor újra jelez: „újra él”. Állapotváltásonként egy üzenet.": "Sala Herramientas: si el panel base no da señal durante unos tres minutos y medio (por ejemplo, por un apagón o porque lo desenchufaron), en la sala aparece: «se ha cortado la alimentación, el panel no da señal»; cuando vuelve a dar señal: «vuelve a funcionar». Un mensaje por cada cambio de estado.",
  "Tudástár: új ingyenes cikk, 3.6 Vércsoport: ki kinek adhat vért, és ki kitől kaphat.": "Base de conocimientos: nuevo artículo gratuito, 3.6 Grupo sanguíneo: quién puede dar sangre a quién y quién puede recibirla de quién.",
  "Súgó (Beállítások): ha az app sötét vagy üres marad, engedélyezd a vírusirtóban (például Avast), vagy használd a böngészős változatot; a Play-áruházban vett prémium 48 órán belül visszakérhető.": "Ayuda (Ajustes): si la app se queda oscura o vacía, permítela en el antivirus (por ejemplo, Avast) o usa la versión de navegador; el Premium comprado en Play Store se puede reembolsar en 48 horas.",
  "Biblia, olvasási terv: a tervválasztó nyitómondata most minden nyelven lefordítva jelenik meg.": "Biblia, plan de lectura: la frase inicial del selector de planes aparece ahora traducida en todos los idiomas.",
  "Tájoló, légnyomás: kis időjárás-kép (napos, változékony, eső, vihar) és trend-nyíl a légnyomás elmúlt órákbeli változásából. Becslés: a félgömb, az évszak és a földrajzi szélesség szerint igazítva, szelet és felhőzetet nem lát.": "Orientación, presión atmosférica: una pequeña imagen del tiempo (soleado, variable, lluvia, tormenta) y una flecha de tendencia según el cambio de la presión en las últimas horas. Es una estimación, ajustada al hemisferio, la estación y la latitud; no ve el viento ni las nubes.",
  "Akkumulátor: a légnyomás-érzékelő csak a Tájoló képernyőn mér folyamatosan; máskor negyedóránként egyszer mér (ebből áll az előzmény és a vihar-riasztás), közben kikapcsol.": "Batería: el sensor de presión atmosférica solo mide de forma continua en la pantalla Orientación; el resto del tiempo mide una vez cada cuarto de hora (de ahí salen el historial y la alarma de tormenta), y entre medias se apaga.",
  "Szobák: egy korábban megnyitott internetes szoba azonnal megjelenik a legutóbbi üzenetekkel, az újak és a változások (javítás, törlés, reakció) a kapcsolódás után érkeznek.": "Salas: una sala por internet abierta anteriormente aparece al instante con los últimos mensajes; los nuevos y los cambios (correcciones, borrados, reacciones) llegan tras conectarse.",
  "Szobák: a szobák borítóképe megmarad a telefonon, ezért azonnal látszik, és hálózatváltáskor (wifi és mobilnet között) sem tűnik el; ha egyszer nem töltődött be, a kapcsolat visszatérésekor újra próbálja. A megváltozott borítóképet a következő listafrissítés lecseréli.": "Salas: la imagen de portada de las salas se guarda en el teléfono, así que se ve al instante y no desaparece al cambiar de red (entre wifi y datos móviles); si una vez no se cargó, lo vuelve a intentar cuando vuelve la conexión. Una imagen de portada cambiada se sustituye en la siguiente actualización de la lista.",
  "Biblia, apokrif könyvek: az első csoport címe „Ószövetségi apokrifek” lett (a korábbi „Deuterokanonikus könyvek” helyett).": "Biblia, libros apócrifos: el título del primer grupo es ahora «Apócrifos del Antiguo Testamento» (en lugar del anterior «Libros deuterocanónicos»).",
  "Akkumulátor: a térkép vagy a tájoló elhagyása után az iránytű-érzékelő leáll, eddig a többi képernyőn is tovább futott.": "Batería: al salir del mapa o de la brújula, el sensor de la brújula se detiene; hasta ahora seguía funcionando también en las demás pantallas.",
  "Biblia: olvasás közben a vissza-nyíl és a telefon Vissza gombja (oldalra söprés) ismét egyenesen a Biblia könyveihez visz, nem a fejezetekhez.": "Biblia: durante la lectura, la flecha atrás y el botón Atrás del teléfono (deslizar hacia el lado) vuelven a llevar directamente a los libros de la Biblia, no a los capítulos.",
  "Megosztás: más appból megosztott szöveget (linket, jegyzetet) is el lehet küldeni a PrepperPapába: csak a szobát kell kiválasztani.": "Compartir: también puedes enviar a PrepperPapa texto compartido desde otra app (un enlace, una nota): solo tienes que elegir la sala.",
  "Eszközök szoba: a LED-szalag és a lámpák állapota érthetően jelenik meg (be/ki, fehér vagy színes fény, szín neve, fényerő), az IR-adónál a tanuló mód; ismeretlen jel és nyers kód nem jelenik meg.": "Sala Herramientas: el estado de la tira LED y de las lámparas aparece de forma comprensible (encendido/apagado, luz blanca o de color, nombre del color, brillo), y en el emisor IR el modo de aprendizaje; no se muestran señales desconocidas ni códigos en bruto.",
  "Biblia: a fejléc vissza-nyila (és a telefon Vissza gombja) szintenként lép: a szövegből a fejezetekhez, onnan a könyvekhez a keresővel.": "Biblia: la flecha atrás de la cabecera (y el botón Atrás del teléfono) retrocede por niveles: del texto a los capítulos, y de ahí a los libros con el buscador.",
  "Biblia térkép: a helyek neve az app nyelvén jelenik meg (oroszul, ukránul cirill betűvel), a nevet az adott nyelvű Biblia szövegéből vesszük.": "Mapa bíblico: los nombres de los lugares aparecen en el idioma de la app (en ruso y ucraniano con letras cirílicas); el nombre se toma del texto de la Biblia en ese idioma.",
  "Biblia térkép: mindig műholdképen, közelről nyílik, és ilyenkor a turistautak, turistapontok, a világhelyzet és az átjátszók nem töltődnek be (kevesebb memória). A térkép elhagyásakor visszaállnak.": "Mapa bíblico: se abre siempre en imagen de satélite y de cerca, y entonces no se cargan los senderos, los puntos de senderismo, la situación mundial ni los repetidores (menos memoria). Al salir del mapa se restablecen.",
  "Súgó: a Biblia súgójában jelezzük, hogy az app bibliaolvasót tartalmaz, és a lelki felkészültség rész keresztény szemszögből készült.": "Ayuda: en la ayuda de la Biblia indicamos que la app incluye un lector de la Biblia y que la parte de preparación espiritual está hecha desde una perspectiva cristiana.",
  "Tájoló: a zöld háromszög (felvett irány) ismét fixen áll a számlapon, és pontosan együtt fordul vele.": "Orientación: el triángulo verde (dirección registrada) vuelve a estar fijo en la esfera y gira exactamente con ella.",
  "Tájoló: a tű folyamatosan, simán fordul (képkockánként), nyugalomban nem remeg; a fokszám csak akkor vált, ha tényleg elfordultál.": "Orientación: la aguja gira de forma continua y suave (fotograma a fotograma) y no tiembla en reposo; los grados solo cambian cuando de verdad has girado.",
  "Tájoló: a felvett irány befogásakor a rezzenés azonnal jön, nem késve.": "Orientación: al fijar la dirección registrada, la vibración llega al instante, sin retraso.",
  "Tájoló hangvezetés: az Android appban indításkor felhangosítja a telefont, leállításkor visszaállítja (fülhallgatóval nem hangosít); minden sípolást egy apró rezzenés kísér, ha a rezgés be van kapcsolva.": "Guía por sonido de Orientación: en la app de Android, al iniciarla sube el volumen del teléfono y al detenerla lo restablece (con auriculares no lo sube); cada pitido va acompañado de una pequeña vibración si la vibración está activada.",
  "Biblia-térkép: a sávban minden igehely (a vers, a további versek, a megjegyzésben álló hivatkozás) koppintható, és pontosan arra a versre visz a Bibliában.": "Mapa bíblico: en la barra, todas las citas (el versículo, los versículos adicionales, la referencia de la nota) se pueden tocar y llevan exactamente a ese versículo en la Biblia.",
  "Biblia-térkép: a sáv bal felső sarkában vissza-nyíl áll a × helyett; ugyanoda visz, mint a telefon Vissza gombja: a vershez, ahonnan jöttél.": "Mapa bíblico: en la esquina superior izquierda de la barra hay una flecha atrás en lugar de ×; lleva al mismo sitio que el botón Atrás del teléfono: al versículo del que venías.",
  "Tudástár: a már letöltött prémium témák is megkapják a térkép-letöltésről szóló javított mondatot.": "Base de conocimientos: los temas Premium ya descargados también reciben la frase corregida sobre la descarga de mapas.",
  "Vagyonkezelő: a lenyitható soroknál a nyíl a sor elejére került, a törlés (×) a másik szélén maradt, így nem lehet véletlenül a törlésre koppintani.": "Patrimonio: en las filas desplegables, la flecha ha pasado al principio de la fila y el borrado (×) se ha quedado en el otro extremo, así que no se puede tocar el borrado por accidente.",
  "Vagyonkezelő: a felső sáv jobb oldalán a havi mérleg és alatta a folyó hónap tervezett kiadása áll.": "Patrimonio: a la derecha de la barra superior aparecen el balance mensual y, debajo, el gasto previsto del mes en curso.",
  "Tájoló: a tű és a fokszám nyugalomban nem remeg, valódi fordulásnál azonnal követ.": "Orientación: la aguja y los grados no tiemblan en reposo, y siguen al instante un giro real.",
  "Eszközök szoba: a kapcsolók állapota érthető szöveggel jelenik meg (be- vagy kikapcsolva, mi történik áramszünet után) a nyers kódok helyett.": "Sala Herramientas: el estado de los interruptores aparece con un texto comprensible (encendido o apagado, qué ocurre tras un apagón) en lugar de los códigos en bruto.",
  "Tudástár: a térkép offline letöltéséről szóló mondat most az „Offline térkép” csoportra mutat (tájegység vagy ország); a Terület letöltése gomb csak a látható részt menti, legfeljebb 400 csempét.": "Base de conocimientos: la frase sobre la descarga sin conexión del mapa señala ahora el grupo «Mapa sin conexión» (región o país); el botón Descargar la zona solo guarda la parte visible, como máximo 400 mosaicos.",
  "Biblia beállítások: a lap mindig azonnal megjelenik. Eddig előfordult, hogy üres maradt, ha a telefon egy háttér-lekérdezésre nem válaszolt.": "Ajustes de la Biblia: la página aparece siempre al instante. Hasta ahora podía quedarse vacía si el teléfono no respondía a una consulta en segundo plano.",
  "Biblia, „Új” könyvszínek: a Zsoltárok és a Példabeszédek saját színt kapott (mélykék és olíva), nappal és éjszaka is.": "Biblia, colores de libros «Nuevo»: Salmos y Proverbios tienen color propio (azul oscuro y oliva), de día y de noche.",
  "Visszajelzés űrlap: megnyitáskor nem ugrik fel a billentyűzet, előbb körülnézhetsz, és te koppintasz a szövegmezőbe.": "Formulario de comentarios: al abrirlo no salta el teclado; primero puedes mirar, y eres tú quien toca el campo de texto.",
  "Vagyonkezelő: a menü a felső sávban marad görgetéskor is, és az új tétel űrlapja mentés után bezárul.": "Patrimonio: el menú se queda en la barra superior también al desplazarse, y el formulario de nuevo elemento se cierra tras guardar.",
  "A prémium kód legfeljebb két készüléken működik, ahogy korábban.": "El código Premium funciona como máximo en dos dispositivos, como antes.",
  "Ingyenes fiók: egyszerre egy készüléken használható. Ha egy második készüléken lépsz be, az app felajánlja, hogy válaszd le az elsőt (ugyanúgy, mint a Beállítások, Készülékeim listában), és utána ott működnek a szobák. Az app többi része minden készüléken használható.": "Cuenta gratuita: se puede usar en un dispositivo a la vez. Si inicias sesión en un segundo dispositivo, la app te ofrece desvincular el primero (igual que en la lista Ajustes, Mis dispositivos), y después las salas funcionan allí. El resto de la app se puede usar en todos los dispositivos.",
  "Készülékeim: leválasztás fiókonként 30 naponta egyszer.": "Mis dispositivos: desvinculación una vez cada 30 días por cuenta.",
  "Biblia: a beállításokban (fogaskerék, a Betűméret alatt) választható a könyvek színe. „Új”: az Ószövetség csoportjai is saját színt kapnak (Mózes könyvei, történeti, bölcsességi könyvek, nagy- és kispróféták), az Újszövetség a mostani színeit tartja, és a fejezetválasztó a könyv színét kapja. „Régi”: a korábbi zöld árnyalatok.": "Biblia: en los ajustes (engranaje, bajo Tamaño de letra) puedes elegir el color de los libros. «Nuevo»: los grupos del Antiguo Testamento también tienen color propio (libros de Moisés, históricos, sapienciales, profetas mayores y menores), el Nuevo Testamento mantiene sus colores actuales y el selector de capítulos toma el color del libro. «Antiguo»: los tonos verdes anteriores.",
  "Biblia olvasó: a fejléc tömör, és a felcsúszott kereső már nem lóg ki mellette. Az árnyék a lap tetején és alján csak a szöveget halványítja, a háttéren nincs fekete sáv.": "Lector de la Biblia: la cabecera es opaca y el buscador deslizado ya no se sale a su lado. La sombra de arriba y abajo de la página solo atenúa el texto; en el fondo no hay franja negra.",
  "Biblia térkép: a hely alatt bővebb leírás az OpenBible adataiból (a hely fajtája, mai azonosítása, más nevei, további versek). A „Vissza az igéhez” gomb helyett a Vissza gomb és az oldalra söprés visz pontosan ugyanahhoz a vershez; a bezárás a kis × a sarokban.": "Mapa bíblico: bajo el lugar, una descripción más amplia con datos de OpenBible (tipo de lugar, identificación actual, otros nombres, versículos adicionales). En lugar del botón «Volver al versículo», el botón Atrás y el deslizamiento lateral llevan exactamente al mismo versículo; se cierra con la pequeña × de la esquina.",
  "Biblia versmenü: oldalra söpréssel is bezárul, a „Mégse” sor kikerült, a Kiemelés sorban a 4 legutóbb használt szín egy koppintással kiemel.": "Menú del versículo: también se cierra deslizando hacia el lado, la línea «Cancelar» ha desaparecido, y en la línea Subrayar los 4 colores usados más recientemente subrayan con un toque.",
  "Morze vétel kamerával: a vevő most a fényjeleknél is magától követi a beérkező tempót, és a „Vétel sebesség” csúszkát is odaállítja. A kamera képkockáinak pontos idejével számol, így a villogás lassan és gyorsan is helyes betűket ad. Kézzel is állíthatod, onnan követi tovább.": "Recepción de Morse con la cámara: el receptor sigue ahora solo el ritmo entrante también con las señales de luz, y coloca ahí el control «Velocidad de recepción». Calcula con el tiempo exacto de los fotogramas de la cámara, así que el parpadeo da letras correctas tanto lento como rápido. También puedes ajustarlo a mano, y a partir de ahí sigue el ritmo.",
  "Tudástár, 10.3: a cikk végén a fél tank szabályra mutató hivatkozás most a jó cikkre, a 10.1-re visz, minden nyelven.": "Base de conocimientos, 10.3: al final del artículo, la referencia a la regla del medio depósito lleva ahora al artículo correcto, el 10.1, en todos los idiomas.",
  "Noah: a segéd beállításai kiírják, mennyi memóriát jelent a telefon, ez kb. hány GB-os telefon, melyik modell fér bele, és ha egyik sem, miért nem. Noah kb. 8 GB-os telefontól fut.": "Noah: los ajustes del asistente indican cuánta memoria tiene el teléfono, a qué teléfono de cuántos GB equivale aproximadamente, qué modelo cabe y, si no cabe ninguno, por qué. Noah funciona a partir de teléfonos de unos 8 GB.",
  "Beállítások, Készülékeim: látod, melyik készülékeiden aktív a prémium (típus, app vagy böngésző, utoljára mikor jelentkezett, és melyik az, amelyiket épp fogod). Amelyik már nem kell, például egy régi tablet, azt két koppintással leválaszthatod, és a helye felszabadul. Leválasztás 30 naponta egyszer.": "Ajustes, Mis dispositivos: ves en qué dispositivos está activo el Premium (tipo, app o navegador, cuándo se conectó por última vez y cuál es el que tienes en la mano). El que ya no necesites, por ejemplo una tableta antigua, lo puedes desvincular con dos toques, y su plaza queda libre. Desvinculación una vez cada 30 días.",
  "Morze vétel hangból: a vevő magától követi a beérkező jel tempóját, lassút és gyorsat is, és a „Vétel sebesség” csúszkát is odaállítja. Kézzel is állíthatod, onnan követi tovább. Az első betűk is helyesen jönnek, ha a csúszka nem a jó tempón állt.": "Recepción de Morse por sonido: el receptor sigue solo el ritmo de la señal entrante, tanto lento como rápido, y coloca ahí el control «Velocidad de recepción». También puedes ajustarlo a mano, y a partir de ahí sigue el ritmo. Las primeras letras también salen bien aunque el control no estuviera en el ritmo correcto.",
  "Vészsíp és hanggenerátor a telefonos appban: a lapjukon a hangerő magától maximumra áll, kilépéskor visszaáll a korábbira, és a hang a telefon hangszóróján szól akkor is, ha fülhallgató vagy Bluetooth-eszköz csatlakozik.": "Silbato de emergencia y generador de tonos en la app del teléfono: en su página el volumen sube solo al máximo, al salir vuelve al anterior, y el sonido sale por el altavoz del teléfono aunque haya conectados auriculares o un dispositivo Bluetooth.",
  "Biblia könyvválasztó: az Újszövetség csoportjai (evangéliumok, Apostolok cselekedetei, Pál levelei, általános levelek, Jelenések) saját, jól elkülönülő színt kaptak.": "Selector de libros de la Biblia: los grupos del Nuevo Testamento (evangelios, Hechos de los Apóstoles, cartas de Pablo, cartas generales, Apocalipsis) tienen un color propio y bien diferenciado.",
  "Az „Ajánld egy barátodnak” a tesztidőszakban egyelőre nem látszik.": "«Recomiéndalo a un amigo» de momento no se ve durante el periodo de prueba.",
  "Biblia olvasás közben: a kereső az előzményekkel fent, a fejléc alatt van; lefelé görgetve felcsúszik, visszahúzva előjön. Olvasáskor a PrepperPapa fejléc nem látszik, a Biblia-fejléc kicsit magasabb lett, alatta finom árnyék a könyv- és fejezetválasztón is.": "Durante la lectura de la Biblia: el buscador con el historial está arriba, bajo la cabecera; al desplazarte hacia abajo se esconde y al tirar hacia atrás vuelve a aparecer. Al leer no se ve la cabecera de PrepperPapa, la cabecera de la Biblia es un poco más alta, y debajo hay una sombra fina, también en el selector de libros y capítulos.",
  "Biblia könyvválasztó: olvasás után a kereső újra teljesen látszik, nem csúszik a fejléc alá.": "Selector de libros de la Biblia: después de leer, el buscador vuelve a verse entero y no se mete bajo la cabecera.",
  "Frissítés: ha egy frissítés nem fejeződik be, az app névtelenül feljegyzi, hol akadt el, hogy javítani tudjuk. A telepítés jóváhagyása megbízhatóbban nyílik meg.": "Actualización: si una actualización no termina, la app registra de forma anónima dónde se atascó, para que podamos corregirlo. La aprobación de la instalación se abre de forma más fiable.",
  "Biblia olvasás közben: vékonyabb fejléc, kevesebb szöveget takar. Alul ott a kereső az előzményekkel; lefelé görgetve elbújik, visszahúzva újra előjön.": "Durante la lectura de la Biblia: cabecera más fina, que tapa menos texto. Abajo está el buscador con el historial; al desplazarte hacia abajo se esconde y al tirar hacia atrás vuelve a aparecer.",
  "Ajánlók: ha egy helyen több ajánló is van, az app váltogatja őket, nem mindig ugyanazt mutatja.": "Recomendaciones: si en un lugar hay varias recomendaciones, la app las va alternando en lugar de mostrar siempre la misma.",
  "Noah: a kérdés elküldése után azonnal látszik, hogy gondolkodik (a három pötty), nem marad üresen a válaszbuborék.": "Noah: tras enviar la pregunta se ve al instante que está pensando (los tres puntos), y la burbuja de respuesta no se queda vacía.",
  "Biblia: a lengyel UBG 2017 szövegében a kiadó hibajegyzéke szerinti három javítás (4Mózes 26,31, Nehémiás 12,35, Júdás 11). A már letöltött lengyel Biblia magától frissül.": "Biblia: en el texto polaco UBG 2017, tres correcciones según la fe de erratas de la editorial (Números 26:31, Nehemías 12:35, Judas 11). La Biblia polaca ya descargada se actualiza sola.",
  "Biblia: a lengyel fordítás ismét az Uwspółcześniona Biblia Gdańska (UBG 2017), most már a kiadó (Fundacja Wrota Nadziei) írásos engedélyével. A versek számozása nem változott, a könyvjelzők, kiemelések és jegyzetek ugyanott maradnak; a már letöltött lengyel Biblia magától cserélődik.": "Biblia: la traducción polaca vuelve a ser la Uwspółcześniona Biblia Gdańska (UBG 2017), ahora con permiso escrito de la editorial (Fundacja Wrota Nadziei). La numeración de los versículos no ha cambiado, y los marcadores, subrayados y notas se quedan en el mismo sitio; la Biblia polaca ya descargada se sustituye sola.",
  "Fortiprep-kalkulátor: a kedvezményes ajánlat a számítás eredménye után jelenik meg.": "Calculadora FortiPrep: la oferta con descuento aparece después del resultado del cálculo.",
  "Fortiprep-kalkulátor: az ajánlat a lap alján jól láthatóan, nagy kuponkóddal (egy koppintással másolható) és kiemelt vásárlás gombbal.": "Calculadora FortiPrep: la oferta aparece bien visible al pie de la página, con un código de cupón grande (se copia con un toque) y un botón de compra destacado.",
  "A Fortiprep-kalkulátor csempéje az alkalmazás saját vonalas ikonstílusában jelenik meg.": "El mosaico de la Calculadora FortiPrep aparece con el estilo de iconos lineales propio de la app.",
  "Új kalkulátor: Fortiprep vagy konzerv. Ugyanannyi kalóriára és ugyanarra az időszakra kiszámolja, mennyibe kerül a tartalék, a konzerv lejárat miatti cseréjével együtt.": "Nueva calculadora: FortiPrep o conservas. Para las mismas calorías y el mismo periodo calcula cuánto cuesta la reserva, incluida la sustitución de las conservas por caducidad.",
  "A képernyő alján megjelenő hibakereső állapotsor kikerült.": "Se ha quitado la barra de estado de depuración que aparecía al pie de la pantalla.",
  "Szobák: ha az alkalmazásba visszatérve egy háttér-ellenőrzés nem kapott választ, az elakadt kérések feltorlódhattak, és utána a szoba üres maradhatott (szürke pont, nem jöttek az üzenetek). Az ellenőrzés most egyszerre csak egyszer fut, és a válasz nélküli kérés 10 másodperc után megszakad.": "Salas: si al volver a la app una comprobación en segundo plano no recibía respuesta, las solicitudes atascadas podían acumularse, y después la sala podía quedarse vacía (punto gris, no llegaban los mensajes). Ahora la comprobación solo se ejecuta una vez a la vez, y una solicitud sin respuesta se interrumpe a los 10 segundos.",
  "Bibliai ébresztő: a frissítés nem szakítja meg többé a reggeli felolvasást. Ha ébresztéskor új változat érhető el, a frissítés megvárja az „Áldott napot” zárást, és csak utána indul el magától.": "Alarma bíblica: la actualización ya no interrumpe la lectura matutina. Si al despertar hay una versión nueva disponible, la actualización espera al cierre «¡Que tengas un día bendecido!» y solo después empieza sola.",
  "Biblia: fordításváltáskor most ugyanarra a versre jutsz, nem csak ugyanarra a fejezetre, a más számozású helyeken is (a címes zsoltárok, Jóel 3–4, Malakiás 4 és 3,19–24, 3Mózes 5–6 a német Bibliában, az orosz Biblia zsoltárszámozása).": "Biblia: al cambiar de traducción llegas ahora al mismo versículo, no solo al mismo capítulo, también en los pasajes con otra numeración (los salmos con título, Joel 3-4, Malaquías 4 y 3:19-24, Levítico 5-6 en la Biblia alemana, la numeración de los salmos de la Biblia rusa).",
  "Biblia: a kereszthivatkozások a címes zsoltároknál és a más számozású fordításokban is a jó versre mutatnak, és az orosz Bibliában is bekapcsolhatók.": "Biblia: las referencias cruzadas señalan el versículo correcto también en los salmos con título y en las traducciones con otra numeración, y también se pueden activar en la Biblia rusa.",
  "Biblia: a kiemelések, kommentárok és könyvjelzők minden fordításban ugyanannál a versnél látszanak, akármelyikben jelölted őket.": "Biblia: los subrayados, comentarios y marcadores se ven en el mismo versículo en todas las traducciones, sea cual sea en la que los marcaste.",
  "Biblia: a német, a lengyel és a román jegyzetek (Scofield-jegyzetek, mértékegységek) kiemelt szavai és igeidézetei mostantól az app saját Bibliájának szövegét idézik (Luther 1912, Gdańskai Biblia 1881, Biblia 1914). A már letöltött jegyzetcsomag magától frissül.": "Biblia: las palabras destacadas y las citas bíblicas de las notas alemanas, polacas y rumanas (notas de Scofield, unidades de medida) citan ahora el texto de la Biblia propia de la app (Luther 1912, Biblia de Gdańsk 1881, Biblia 1914). El paquete de notas ya descargado se actualiza solo.",
  "Tudástár: a román „Remény a felkészülés határán” cikk a Példabeszédek 27,12-t idézi (a 22,3 helyett, amely az 1914-es román Bibliában mást mond).": "Base de conocimientos: el artículo rumano «Esperanza en el umbral de la preparación» cita Proverbios 27:12 (en lugar de 22:3, que en la Biblia rumana de 1914 dice otra cosa).",
  "Biblia: a román fordítás mostantól az 1914-es Szent Szinódusi Biblia (ortodox, közkincs). A versek számozása nem változott, a könyvjelzők, kiemelések és jegyzetek ugyanott maradnak; ahol ez a Szeptuagintán alapuló kiadás egy verset nem tartalmaz, a helyén rövid megjegyzés áll.": "Biblia: la traducción rumana es ahora la Biblia del Santo Sínodo de 1914 (ortodoxa, de dominio público). La numeración de los versículos no ha cambiado, y los marcadores, subrayados y notas se quedan en el mismo sitio; donde esta edición basada en la Septuaginta no contiene un versículo, en su lugar figura una breve nota.",
  "Hirdetések: az app névtelenül számolja, hányszor jelenik meg és hányszor nyitják meg az egyes hirdetéseket. Személyhez és eszközhöz nem kötött, ugyanúgy, mint a meglévő névtelen használati napló.": "Anuncios: la app cuenta de forma anónima cuántas veces se muestra y cuántas veces se abre cada anuncio. No está vinculado a personas ni dispositivos, igual que el registro de uso anónimo existente.",
  "Tudástár: a német és a lengyel „Remény a felkészülés határán” cikk igeversei mostantól az app saját Bibliájából (Luther 1912, Gdańskai Biblia 1881) szó szerint idéznek.": "Base de conocimientos: los versículos de los artículos alemán y polaco «Esperanza en el umbral de la preparación» citan ahora literalmente la Biblia propia de la app (Luther 1912, Biblia de Gdańsk 1881).",
  "Biblia: a Vészhelyzeti igék és a Próféciák listája minden nyelven teljes (eddig a magyaron kívül csak néhány tétel jelent meg), és a zsoltárok versszámát a választott fordítás számozásához igazítja.": "Biblia: las listas de Versículos para emergencias y de Profecías están completas en todos los idiomas (hasta ahora, fuera del húngaro solo aparecían algunos elementos), y el número de versículo de los salmos se ajusta a la numeración de la traducción elegida.",
  "Biblia: fordításváltáskor a Malakiás 4. és a Jóel 3. fejezet a német Bibliában a megfelelő helyen nyílik meg (Malakiás 3,19, illetve Jóel 4), és vissza.": "Biblia: al cambiar de traducción, Malaquías 4 y Joel 3 se abren en el lugar correspondiente de la Biblia alemana (Malaquías 3:19 y Joel 4, respectivamente), y viceversa.",
  "Biblia: a német fordítás mostantól a Luther-Biblia 1912-es kiadása, a lengyel a Gdańskai Biblia 1881-es kiadása (mindkettő közkincs). A versek számozása nem változott, a könyvjelzők, kiemelések és jegyzetek ugyanott maradnak. Akinek a régi le volt töltve, annál az app magától kicseréli.": "Biblia: la traducción alemana es ahora la edición de 1912 de la Biblia de Lutero, y la polaca la edición de 1881 de la Biblia de Gdańsk (ambas de dominio público). La numeración de los versículos no ha cambiado, y los marcadores, subrayados y notas se quedan en el mismo sitio. Si tenías descargada la antigua, la app la sustituye sola.",
  "SOS: a hívás gomb és az újraélesztés-ütem „Mentő” sora is annak az országnak a segélyhívó számát mutatja, ahol a telefon van; ha ez nem biztos, „Segélyhívás (az EU-ban 112)”, és a gomb a 112-t hívja. Magyarul változatlanul 112.": "SOS: el botón de llamada y la línea «Ambulancia» del ritmo de reanimación muestran también el número de emergencias del país donde está el teléfono; si no es seguro, «Llamada de emergencia (en la UE, 112)», y el botón llama al 112. En húngaro sigue siendo 112.",
  "Szobák: az internetes szobába küldött kép is titkosítva megy, a szoba kulcsával, ugyanúgy, mint a szöveg. A korábban küldött képek továbbra is látszanak. Ha a titkosítás nem sikerül, a kép nem megy el, és csatolva marad.": "Salas: las imágenes enviadas a una sala por internet también van cifradas, con la clave de la sala, igual que el texto. Las imágenes enviadas antes se siguen viendo. Si el cifrado falla, la imagen no se envía y queda adjunta.",
  "Helyi szoba: a nagyobb képek is elmennek (eddig a 100 kB körüli vagy nagyobb kép titkosítása elakadt).": "Sala local: también se envían las imágenes más grandes (hasta ahora se atascaba el cifrado de imágenes de unos 100 kB o más).",
  "SOS és esés-érzékelés: a nem magyar nyelvű szövegek annak az országnak a segélyhívó számát írják, ahol a telefon van (például 911, 999, 000, 111); ha ez nem biztos, „a helyi segélyhívó számot (az EU-ban 112)”. Magyarul változatlanul 112.": "SOS y detección de caídas: los textos en idiomas distintos del húngaro indican el número de emergencias del país donde está el teléfono (por ejemplo, 911, 999, 000, 111); si no es seguro, «el número de emergencias local (en la UE, 112)». En húngaro sigue siendo 112.",
  "Esés-érzékelés: aki már korábban bekapcsolta, egyszer megkapja a tudnivalót, és az „Elolvastam, értem.” pipával elfogadja; az esés-érzékelés közben bekapcsolva marad.": "Detección de caídas: quien ya la había activado recibe una vez la información y la acepta con la casilla «Lo he leído y lo entiendo.»; mientras tanto, la detección de caídas sigue activada.",
  "Token tárca: a „Könyvek összefésülése” részen látszik, mikor ellenőrizte utoljára magától a telefon (két percenként), mikor küldött változást és mikor kapott könyvet. Ha nincs elérhető Gerah-szoba, ezt írja ki.": "Cartera de tokens: en la sección «Conciliar libros» se ve cuándo lo comprobó el teléfono solo por última vez (cada dos minutos), cuándo envió un cambio y cuándo recibió un libro. Si no hay ninguna sala Gerah disponible, lo indica.",
  "Frissítés: a telepítő megnyitása után eltűnik a „Letöltés és telepítés” gomb, helyette egy sor jelzi, hogy a telepítés folyamatban van. Ha nem fejeződik be, a gomb visszajön.": "Actualización: tras abrir el instalador desaparece el botón «Descargar e instalar», y en su lugar una línea indica que la instalación está en curso. Si no termina, el botón vuelve.",
  "Kockázatelemzés: az „Eszközök a helyszíneken” lista helyszínenként csoportosít, eszközönként egy sorban; az áthelyezés a sor végi kis gombbal megy.": "Análisis de riesgos: la lista «Equipo en los lugares» se agrupa por lugar, con una línea por equipo; el traslado se hace con el pequeño botón al final de la línea.",
  "Irattárca és Token tárca: a zárolt képernyőn az „Ujjlenyomattal” felirat helyett egy ujjlenyomat-ikon van a Belépés mellett, így minden nyelven elfér.": "Cartera de documentos y Cartera de tokens: en la pantalla bloqueada, en lugar del texto «Con huella» hay un icono de huella junto a Iniciar sesión, así que cabe en todos los idiomas.",
  "SOS és esés-érzékelés: bekapcsolás előtt egy tudnivalót kell elolvasni és bejelölni (az app nem hív mentőt, életveszélyben a 112-t hívd). A Vészkártya adatai (vércsoport, allergia, gyógyszer, betegség, kontakt) csak akkor mennek az SOS-szal, ha ezt külön bejelölöd; alapból nem mennek. A szobatársak értesítése is a 112-re figyelmeztet.": "SOS y detección de caídas: antes de activarlos hay que leer y marcar una información (la app no llama a una ambulancia; en peligro de muerte, llama al 112). Los datos de la Tarjeta de emergencia (grupo sanguíneo, alergias, medicamentos, enfermedades, contacto) solo se envían con el SOS si lo marcas aparte; por defecto no se envían. La notificación a los compañeros de sala también recuerda el 112.",
  "Szobák: ha egy üzenet titkosítása nem sikerül (például ezen a telefonon hiányzik a szoba kulcsa), az üzenet nem megy el titkosítatlanul. Az app pirossal kiírja, hogy nem ment el, a szöveg a mezőben marad, és újra be kell lépni a szobába. Ugyanez áll a módosításra, a képre és a megosztott képre is.": "Salas: si falla el cifrado de un mensaje (por ejemplo, porque en este teléfono falta la clave de la sala), el mensaje no se envía sin cifrar. La app indica en rojo que no se ha enviado, el texto se queda en el campo y hay que volver a entrar en la sala. Lo mismo vale para las ediciones, las imágenes y las imágenes compartidas.",
  "Irattárca és Token tárca: az ujjlenyomatos feloldás újra bekapcsolható. Ha a saját PIN beállításakor kikapcsolt, a nyitott tárcában az „Ujjlenyomat bekapcsolása” gombbal, a PIN megadása után visszakapcsolod, és a zárolt képernyőn újra ott az „Ujjlenyomattal” gomb.": "Cartera de documentos y Cartera de tokens: el desbloqueo con huella se puede volver a activar. Si se desactivó al configurar tu propio PIN, en la cartera abierta lo reactivas con el botón «Activar desbloqueo con huella», tras introducir el PIN, y en la pantalla bloqueada vuelve a estar el botón «Con huella».",
  "Irattárca és tárca: a tudomásulvétel helyett egy „Fontos tudnivaló” képernyő jelenik meg a tárca létrehozásakor (meglévő tárcánál egyszer, a következő megnyitáskor). A pipa és a Tovább gomb a szöveg végén van. A Gerah-ról szóló bekezdés a Gerah első megnyitásakor is megjelenik.": "Cartera de documentos y monedero: en lugar de la confirmación, al crear el monedero aparece una pantalla de «Información importante» (en un monedero existente, una vez, en la siguiente apertura). La casilla y el botón Siguiente están al final del texto. El párrafo sobre Gerah también aparece la primera vez que se abre Gerah.",
  "Tudástár: Noah sora egyetlen keskeny sorba került, így alatta több téma fér el.": "Base de conocimientos: la línea de Noah ocupa ahora una sola línea estrecha, así que debajo caben más temas.",
  "Újranyitás: ha az app üres zöld képernyővel jönne vissza, magától újratölti a lapot, nem kell bezárni és újranyitni.": "Reapertura: si la app volviera con una pantalla verde vacía, recarga la página sola, sin necesidad de cerrarla y volver a abrirla.",
  "Esés-SOS: ha egy szoba titkosítása nem sikerül, oda az SOS nem megy el titkosítatlanul. Az app pirossal kiírja, hogy az SOS nem ment el, és hogy életveszélyben hívd a 112-t. A vészsíp ilyenkor is szól.": "SOS por caída: si falla el cifrado de una sala, el SOS no se envía allí sin cifrar. La app indica en rojo que el SOS no se ha enviado y que, en peligro de muerte, llames al 112. El silbato de emergencia suena también en ese caso.",
  "Irattárca és Token tárca: új tárca létrehozásakor tudomásul kell venni, hogy a kulcsokat (PIN, helyreállító kód, seed phrase) csak te ismered; a meglévő tárcáknál ez egyszer, a következő megnyitáskor jelenik meg.": "Cartera de documentos y Cartera de tokens: al crear un monedero nuevo hay que confirmar que las claves (PIN, código de recuperación, seed phrase) solo las conoces tú; en los monederos existentes esto aparece una vez, en la siguiente apertura.",
  "Ki vagyok?: a kép azonnal a helyén van, nem töltődik be később.": "¿Quién soy?: la imagen está en su sitio al instante, no se carga más tarde.",
  "Irattárca és Token tárca: az első megnyitáskor a saját PIN-kódodat állítod be (nincs előre megadott PIN), a mezőben nincsenek előre kitett pöttyök.": "Cartera de documentos y Cartera de tokens: en la primera apertura configuras tu propio PIN (no hay PIN predeterminado), y el campo no tiene puntos ya puestos.",
  "Elfelejtett PIN: a beállításkor kapsz egy mentési kódot (írd le papírra), és megadhatsz egy emlékeztető mondatot. Az „Elfelejtettem a PIN-t” alatt a mentési kóddal vagy ujjlenyomattal új PIN-t állíthatsz be, az adataid megmaradnak.": "PIN olvidado: al configurarlo recibes un código de recuperación (anótalo en papel) y puedes indicar una frase recordatoria. En «He olvidado el PIN» puedes configurar un PIN nuevo con el código de recuperación o con la huella, y tus datos se conservan.",
  "Feloldó kód: a tesztelői kód is a fiókodhoz tartozik. Ugyanazzal a belépéssel legfeljebb két készüléken működik, a második készüléken nem kell újra beírni. Harmadik készüléken nem oldódik fel.": "Código de desbloqueo: el código de probador también pertenece a tu cuenta. Con el mismo inicio de sesión funciona como máximo en dos dispositivos, y en el segundo no hay que volver a escribirlo. En un tercer dispositivo no se desbloquea.",
  "Akkumulátor: a helyi szobák háttérszolgáltatása 30 perc csend után leáll, a Bluetooth- és hálózati keresés csak akkor fut, amikor a helyi szobákat nézed vagy egy helyi szoba épp aktív, és takarékos módban keres. A közeli szobák a megnyitás után pár másodperccel jelennek meg; ha hosszabb csend után érkezik helyi üzenet a háttérben, késhet.": "Batería: el servicio en segundo plano de las salas locales se detiene tras 30 minutos de silencio, la búsqueda por Bluetooth y por red solo funciona cuando miras las salas locales o hay una sala local activa, y busca en modo de ahorro. Las salas cercanas aparecen unos segundos después de abrir; si llega un mensaje local en segundo plano tras un silencio largo, puede retrasarse.",
  "Kezdőlap: a tudástár- és bibliai ajánló között véletlenszerűen egy termékajánló is sorra kerül, ugyanakkora kártyán, a készleted és a „Mi hiányzik?” alapján (például ha energia vagy víz hiányzik, vagy lejáró tétel van).": "Inicio: entre las recomendaciones de la base de conocimientos y de la Biblia aparece también, al azar, una recomendación de producto, en una tarjeta del mismo tamaño, según tus reservas y la lista ¿Qué falta? (por ejemplo, si falta energía o agua, o hay un artículo que caduca).",
  "Felugró ajánló: két felugró között legalább 30 perc telik el. A tulajdonosi teszt-kapcsoló felirata egyértelműbb lett.": "Recomendación emergente: entre dos ventanas emergentes pasan como mínimo 30 minutos. El texto del interruptor de prueba del propietario es más claro.",
  "Térkép: egy kapott GPS-hivatkozás, Google Térkép-pont vagy koordinátás szöveg megnyitható a PrepperPapa térképén (Android: „Megnyitás ezzel” vagy Megosztás > PrepperPapa). A pont a térkép közepére kerül, a neve kitöltve, a Mentéssel saját pont lesz belőle.": "Mapa: un enlace GPS recibido, un punto de Google Maps o un texto con coordenadas se puede abrir en el mapa de PrepperPapa (Android: «Abrir con» o Compartir > PrepperPapa). El punto se coloca en el centro del mapa con el nombre rellenado, y con Guardar se convierte en un punto propio.",
  "Ajánlók internet nélkül is: a legutóbb letöltött ajánlók és képeik offline is megjelennek a szokásos gyakorisággal; a termék oldala akkor nyílik meg, amikor lesz kapcsolat.": "Recomendaciones también sin internet: las últimas recomendaciones descargadas y sus imágenes aparecen también sin conexión, con la frecuencia habitual; la página del producto se abre cuando haya conexión.",
  "Kezdőlap: a felugró ajánló egy megnyitás alatt legfeljebb egyszer jelenik meg (minden második megnyitásnál, naponta legfeljebb ötször), akárhányszor térsz vissza a kezdőlapra.": "Inicio: la recomendación emergente aparece como máximo una vez por apertura (cada segunda apertura, como máximo cinco veces al día), por muchas veces que vuelvas al inicio.",
  "Telepített app: a kötelező frissítés képernyőjéről kikerült a kézi, böngészős letöltés. Ha a telepítés nem indul el, ott a telepítési engedély beállításának útja áll.": "App instalada: se ha quitado la descarga manual por navegador de la pantalla de actualización obligatoria. Si la instalación no empieza, ahí se indica cómo llegar al ajuste del permiso de instalación.",
  "Vagyonkezelő: önálló termék, a prémiumot nem oldja fel. Ha csak a Vagyonkezelő van meg, az működik, minden más (a hirdetésekkel együtt) az ingyenes változat szerint látszik.": "Patrimonio: es un producto independiente y no desbloquea Premium. Si solo tienes Patrimonio, este funciona, y todo lo demás (anuncios incluidos) se ve como en la versión gratuita.",
  "Kezdőlap: a csempék alatt nincs többé állandó hirdetés-kártya. Ott a váltakozó tudástár- és bibliai ajánló látszik; viharjelzés után néha, véletlenszerűen egy hozzá illő termékajánló is sorra kerül, pontosan a tudástár-ajánló méretében.": "Inicio: bajo los mosaicos ya no hay una tarjeta de anuncio fija. Ahí se ve la recomendación alterna de la base de conocimientos y de la Biblia; tras un aviso de tormenta, a veces y al azar aparece también una recomendación de producto relacionada, exactamente del tamaño de la recomendación de la base de conocimientos.",
  "Mi hiányzik?: minden sor elmondja, miért fontos a hiányzó tétel, és mivel érdemes pótolni. Termékajánló legfeljebb két sorban, kicsiben, a tanács alatt.": "¿Qué falta?: cada línea explica por qué es importante el artículo que falta y con qué conviene reponerlo. Recomendación de producto como máximo en dos líneas, en pequeño, bajo el consejo.",
  "Tükör: a kép ujjal húzva mozgatható, nagyítva minden irányba, így közelről (például kontaktlencse behelyezésekor) a szem a felső kamera mellé tolható. Alapból a kép a képernyő teteje felé tolódik, a telefon megjegyzi az utolsó helyzetet és nagyítást, dupla koppintás visszaállítja. A felső fénykeret keskenyebb lett.": "Espejo: la imagen se mueve arrastrándola con el dedo, y ampliada en todas las direcciones, así que de cerca (por ejemplo, al ponerte lentillas) el ojo se puede llevar junto a la cámara frontal. Por defecto la imagen se desplaza hacia la parte superior de la pantalla, el teléfono recuerda la última posición y el zoom, y un doble toque lo restablece. El marco de luz superior es más estrecho.",
  "Prémium: a tudástár-cikkek végén is megjelenik egy csendes ajánló (a Készlet lista és az Áram-kalkulátor mellett). Felugró hirdetés továbbra sincs, a kezdőlapon és a Háztartás oldalon sincs hirdetés.": "Premium: al final de los artículos de la base de conocimientos también aparece una recomendación discreta (además de la lista de Reservas y la calculadora de electricidad). Sigue sin haber anuncios emergentes, y tampoco hay anuncios en el inicio ni en la página Hogar.",
  "Kezdőlap: az „Ajánld egy barátodnak” kártya naponta legfeljebb egyszer jelenik meg, a nap egy véletlen megnyitásánál, a napi tipp helyén.": "Inicio: la tarjeta «Recomiéndalo a un amigo» aparece como máximo una vez al día, en una apertura al azar del día, en el lugar del consejo del día.",
  "Prémium: nincs felugró hirdetés, és a kezdőlapon meg a Háztartás oldalon sincs hirdetés. Csak a Készlet listában és az Áram-kalkulátorban marad egy-egy csendes ajánló.": "Premium: no hay anuncios emergentes, y tampoco hay anuncios en el inicio ni en la página Hogar. Solo queda una recomendación discreta en la lista de Reservas y otra en la calculadora de electricidad.",
  "Tudástár súgó: az alap- és az életmentő cikkek ingyenesek, a bővített tudástár a Prémium része.": "Ayuda de la Base de conocimientos: los artículos básicos y los de primeros auxilios son gratuitos; la base de conocimientos ampliada forma parte de Premium.",
  "Telepített app: a kötelező frissítés képernyőjén mindig ott van a kézi letöltés linkje és a telepítési engedély beállítása, a telefon nyelvén.": "App instalada: en la pantalla de actualización obligatoria siempre están el enlace de descarga manual y el ajuste del permiso de instalación, en el idioma del teléfono.",
  "Kezdőlap: az „Ajánld egy barátodnak” kártya ritkábban, véletlenszerűen jelenik meg (nagyjából minden harmadik megnyitáskor), és egy órán belül soha nem jön elő újra. Az ingyenes és a fizetős változatban is így működik.": "Inicio: la tarjeta «Recomiéndalo a un amigo» aparece con menos frecuencia y al azar (más o menos cada tercera apertura), y nunca vuelve a salir antes de una hora. Funciona igual en la versión gratuita y en la de pago.",
  "Gerah: a profilnév megadásával a Gerah-azonosítód is magától elkészül, ugyanezzel a névvel, külön lépés nélkül. Akinek már van profilneve, de Gerah-ja még nincs, annál a következő megnyitáskor jön létre. A kézzel létrehozott Gerah-hoz az app nem nyúl.": "Gerah: al indicar el nombre de perfil, tu identificador Gerah se crea solo, con ese mismo nombre, sin un paso aparte. Si ya tienes nombre de perfil pero aún no tienes Gerah, se crea en la siguiente apertura. La app no toca un Gerah creado a mano.",
  "Szobák: megnyitáskor a beszélgetés a végén áll, ha mindent elolvastál; ha van új üzenet, az elsőnél nyílik meg egy „Új üzenetek” elválasztóval. A később betöltődő képek és üzenetek nem mozdítják el.": "Salas: al abrir, la conversación está al final si lo has leído todo; si hay mensajes nuevos, se abre en el primero con un separador «Mensajes nuevos». Las imágenes y mensajes que se cargan después no la desplazan.",
  "Szobák: a régi szerverhiba miatt csonka üzenetek „sérült üzenet” jelzést kapnak a félrevezető „ez a kulcs nem ehhez a szobához való” helyett.": "Salas: los mensajes incompletos por un antiguo error del servidor llevan la marca «mensaje dañado» en lugar del engañoso «esta clave no es de esta sala».",
  "A felolvasás hangjegy-gombja csak a Biblia és az imák képernyőjén látszik, és soha nem takarja a narancs + gombot.": "El botón de la nota musical de la lectura en voz alta solo se ve en las pantallas de la Biblia y de las oraciones, y nunca tapa el botón naranja +.",
  "Kezdőlap: az „Ajánld egy barátodnak” kártya teljes egészében a menüsor fölött áll. A felugró ajánlat szimmetrikus, a termék képe egészben látszik, mögötte elmosva.": "Inicio: la tarjeta «Recomiéndalo a un amigo» queda entera por encima de la barra de menú. La oferta emergente es simétrica, y la imagen del producto se ve entera, con una versión difuminada detrás.",
  "Készlet: a lejárati ajánló sáv a listával együtt gördül, nem ugrál a fejléc alatt.": "Reservas: la barra de recomendaciones de caducidad se desplaza junto con la lista y no salta bajo la cabecera.",
  "Beállítások: a rövid rezgés kapcsolója minden megnyitáskor újra ellenőrzi a telefont; alapból bekapcsolt.": "Ajustes: el interruptor de la vibración breve vuelve a comprobar el teléfono en cada apertura; por defecto está activado.",
  "Felugró ajánlat az ingyenes változatban: minden második megnyitáskor, naponta legfeljebb ötször.": "Oferta emergente en la versión gratuita: cada segunda apertura, como máximo cinco veces al día.",
  "Az „Ajánld egy barátodnak” és a Használati útmutató a választott nyelvű oldalra visz, és csak a Beállításokban van.": "«Recomiéndalo a un amigo» y la Guía de uso llevan a la página en el idioma elegido, y solo están en Ajustes.",
  "Fordítás: a Ki vagyok? oldal gombjai és a családtag-sor gyógyszer címkéje minden nyelven lefordítva.": "Traducción: los botones de la página ¿Quién soy? y la etiqueta de medicamentos de la línea de familiar están traducidos en todos los idiomas.",
  "Ingyenes és prémium változat: ingyen 2 saját családtag, 50 saját termék, interneten a térkép heti 2 útvonaltervezéssel. A prémium kód ezeket feloldja, az offline térképletöltéssel és a bővített tudástárral együtt.": "Versión gratuita y Premium: gratis, 2 familiares propios, 50 productos propios y, por internet, el mapa con 2 planificaciones de ruta por semana. El código Premium los desbloquea, junto con la descarga de mapas sin conexión y la base de conocimientos ampliada.",
  "A bemutató adat a korláton felül is betöltődik, de csak megnézhető: nem szerkeszthető, és nem számít bele a korlátba.": "Los datos de demostración se cargan también por encima del límite, pero solo se pueden ver: no se pueden editar y no cuentan para el límite.",
  "Vagyonkezelő: mindenki kipróbálhatja 10 saját tételig és 1 számláig, minta háztartással. A teljes használathoz a külön Vagyonkezelő kell, a prémium kód ezt nem oldja fel.": "Patrimonio: todos pueden probarlo con hasta 10 elementos propios y 1 cuenta, con un hogar de ejemplo. Para el uso completo hace falta Patrimonio por separado; el código Premium no lo desbloquea.",
  "Szobák: prémiummal legfeljebb 10 saját szoba és bármennyi tagság.": "Salas: con Premium, como máximo 10 salas propias y cualquier número de membresías.",
  "Ajánlások: helyzethez illő ajánló kártyák (például lejáró készletnél), az ingyenes változatban felugró hirdetések is. SOS, lámpa, riasztó, vészkártya, navigáció és éjszakai mód alatt soha nem jelennek meg.": "Recomendaciones: tarjetas de recomendación adecuadas a la situación (por ejemplo, con reservas que caducan) y, en la versión gratuita, también anuncios emergentes. Nunca aparecen durante el SOS, la lámpara, la alarma, la tarjeta de emergencia, la navegación ni el modo nocturno.",
  "A bemutató adat nevei és az életkor most minden nyelven a választott nyelven látszanak.": "Los nombres y la edad de los datos de demostración se ven ahora en todos los idiomas en el idioma elegido.",
  "A Morze és a Fax ingyenes: nincs próbaidő és nincs emlékeztető, mindkettő teljes egészében használható.": "Morse y Fax son gratuitos: sin periodo de prueba ni recordatorios, y ambos se pueden usar por completo.",
  "A Fax neve egyszerűbb: a Kommunikáció lapon és a Fax képernyőn csak „Fax” áll.": "El nombre de Fax es más sencillo: en la página Comunicación y en la pantalla de Fax solo aparece «Fax».",
  "Feloldás: a kód a fiókodhoz tartozik, és legfeljebb két készüléken használható. A feloldott modulok offline is működnek.": "Desbloqueo: el código pertenece a tu cuenta y se puede usar como máximo en dos dispositivos. Los módulos desbloqueados funcionan también sin conexión.",
  "Használati útmutató: jól látható gomb a Ki vagyok? oldal tetején és a Beállításokban, a prepperpapa.hu útmutatójára visz.": "Guía de uso: un botón bien visible arriba de la página ¿Quién soy? y en Ajustes lleva a la guía de prepperpapa.hu.",
  "Ki vagyok? oldal: az Elérhetőségek közül kikerült a blog.": "Página ¿Quién soy?: se ha quitado el blog de los datos de contacto.",
  "Térkép: modern térkép-ikonok a turistapontokon. Ivóvíz, forrás, kút, menedékház, táborhely, csúcs, barlang, kilátó, pihenő, útjelző, rom, vár, kereszt és rádió-átjátszó: mind egységes, színes kör, jól látható fehér jellel, éjszakai módban vörösen. A turistautak jelzései (például a piros kereszt) nem változtak.": "Mapa: iconos de mapa modernos en los puntos de senderismo. Agua potable, fuente, pozo, refugio, zona de acampada, cumbre, cueva, mirador, área de descanso, señal de camino, ruinas, castillo, cruz y repetidor de radio: todos son un círculo de color uniforme con un símbolo blanco bien visible, en rojo en modo nocturno. Las señales de los senderos (por ejemplo, la cruz roja) no han cambiado.",
  "Háztartás, családtag adatlapja: a vészkártyára kerülő mezők neve ugyanaz, mint a kártyán: „A kártya tulajdonosának telefonszáma”, „Vész esetén értesítendő személy” és „Vész esetén értesítendő telefonszáma”. Így másnak kitöltve is egyértelmű, kinek a számát kell beírni.": "Hogar, ficha del familiar: los campos que pasan a la tarjeta de emergencia se llaman igual que en la tarjeta: «Teléfono del titular de la tarjeta», «Contacto de emergencia (persona a avisar)» y «Teléfono del contacto de emergencia». Así, aunque la rellenes para otra persona, queda claro qué número hay que escribir.",
  "Vészkártya: a mezők neve egyértelműbb. „A kártya tulajdonosának telefonszáma” (a kártya másnak is kitölthető, ezért nem „saját”), „Vész esetén értesítendő személy” és „Vész esetén értesítendő telefonszáma”. A kártya nézetén, az SOS lapon és a nyomtatott kártyán is így szerepel.": "Tarjeta de emergencia: los nombres de los campos son más claros. «Teléfono del titular de la tarjeta» (la tarjeta se puede rellenar para otra persona, por eso no dice «propio»), «Contacto de emergencia (persona a avisar)» y «Teléfono del contacto de emergencia». Así aparece en la vista de la tarjeta, en la página SOS y en la tarjeta impresa.",
  "Hanggenerátor: a gombok alatt kiírja, hogy a hang szól, csak hallhatatlanul magas, tehát az a normális, ha semmit nem hallasz. Az új Próbahang gomb egy rövid, jól hallható sípot ad, így ellenőrizheted, hogy a telefon hangszórója működik. A futó hangot nem állítja le.": "Generador de tonos: bajo los botones indica que el sonido está sonando, solo que es tan agudo que no se oye, así que es normal no oír nada. El nuevo botón Tono de prueba da un pitido corto y bien audible, para comprobar que el altavoz del teléfono funciona. No detiene el tono en curso.",
  "Ha egy funkcióhoz hiányzik az engedély (kamera, mikrofon, helymeghatározás, értesítés, mozgásérzékelő, Bluetooth), egy lap mondja meg, mi hiányzik, mire kell, és mi a teendő. A telefonos appban egy koppintással megnyílik az app beállítása (értesítésnél az értesítési beállítás), és ha a telefon még rákérdezhet, előbb újra megkérdezi. Böngészőben a lap a böngésző saját kérdését hozza fel újra, és pontosan megmutatja, hol kapcsolhatod be: Chrome, telepített webapp, Samsung Internet, iPhone Safari, főképernyős iPhone-app és számítógép, a te eszközöd áll elöl. Androidon a PrepperPapa app megnyitását is felkínálja.": "Si a una función le falta un permiso (cámara, micrófono, ubicación, notificaciones, sensor de movimiento, Bluetooth), una página indica qué falta, para qué hace falta y qué hacer. En la app del teléfono, un toque abre los ajustes de la app (para las notificaciones, los ajustes de notificaciones), y si el teléfono aún puede preguntar, primero vuelve a preguntar. En el navegador, la página vuelve a mostrar la pregunta propia del navegador e indica exactamente dónde activarlo: Chrome, web app instalada, Samsung Internet, Safari de iPhone, app de iPhone en la pantalla de inicio y ordenador, con tu dispositivo en primer lugar. En Android también ofrece abrir la app PrepperPapa.",
  "Tükör: ha az előlapi kamera nem a szokásos módon nyílik meg, más beállításokkal és a telefon kameralistájából is megpróbálja. Ha a kamerát egy másik alkalmazás fogja, vagy az engedély megvan, de nem jön kép, ezt külön megmondja, a teendővel együtt.": "Espejo: si la cámara frontal no se abre de la forma habitual, lo intenta con otros ajustes y con la lista de cámaras del teléfono. Si otra app está usando la cámara, o el permiso está concedido pero no llega imagen, lo indica por separado, junto con qué hacer.",
  "Képküldés a telefon galériájából: a Google Fotókban (vagy bármelyik galériában) a Megosztás menüben megjelenik a PrepperPapa. Kiválasztva egyetlen lépés jön: koppints a szobára, és a kép (több kép is) azonnal elmegy. Utána egy másik szobára is koppinthatsz; a Kész bezárja. Ha még nem léptél be, előbb a belépés jön, utána a szobák.": "Enviar imágenes desde la galería del teléfono: en Google Fotos (o en cualquier galería), PrepperPapa aparece en el menú Compartir. Al elegirla viene un solo paso: toca la sala, y la imagen (también varias) se envía al instante. Después puedes tocar también otra sala; Hecho lo cierra. Si aún no has iniciado sesión, primero viene el inicio de sesión y después las salas.",
  "Internetes szobák: az értesítésre koppintva a szoba azonnal a saját nevével nyílik meg, és akkor is betöltődnek az üzenetek, ha a telefon hosszabb ideig a háttérben volt. Eddig ilyenkor előfordult, hogy csak egy üres „Szoba” felirat jelent meg, és a régi üzenetek sem jöttek be. A fejlécben a zöld pont csak akkor zöld, amikor a szoba már tényleg kapcsolódott; ha a kapcsolat nem jön létre, az app magától újrapróbálja.": "Salas por internet: al tocar la notificación, la sala se abre al instante con su propio nombre, y los mensajes se cargan aunque el teléfono haya estado mucho tiempo en segundo plano. Hasta ahora a veces solo aparecía un texto «Sala» vacío, y tampoco llegaban los mensajes antiguos. El punto de la cabecera solo está verde cuando la sala ya se ha conectado de verdad; si la conexión no se establece, la app lo reintenta sola.",
  "Biblia, apokrif könyvek: az Apokrif könyvek sáv alatt és minden apokrif könyv első fejezete fölött egy halk, kis betűs megjegyzés jelzi, hogy ezek nem a Szentírás részei, hanem ajánlott olvasmányok. A felolvasás ezt nem olvassa fel, a fejezet- és versszámozás nem változott.": "Biblia, libros apócrifos: bajo la barra de libros apócrifos y encima del primer capítulo de cada libro apócrifo, una nota discreta en letra pequeña indica que no forman parte de la Sagrada Escritura, sino que son lecturas recomendadas. La lectura en voz alta no la lee, y la numeración de capítulos y versículos no ha cambiado.",
  "Letölthető térkép: kevesebb helyet foglal a telefonon. A határ menti tájegységek a határ után 10 km-nél véget érnek (a szomszéd ország külön letölthető), a szintvonalakból kimaradt a felesleges legrészletesebb szint, a turistautak és -pontok tömörítve kerülnek a telefonra, a külföldi turistautak pedig nem jönnek le kétszer. A közeli nézet nem változott.": "Mapa descargable: ocupa menos espacio en el teléfono. Las regiones fronterizas terminan 10 km después de la frontera (el país vecino se descarga por separado), se ha quitado de las curvas de nivel el nivel más detallado innecesario, los senderos y puntos se guardan comprimidos en el teléfono, y los senderos extranjeros no se descargan dos veces. La vista cercana no ha cambiado.",
  "Térkép letöltése: az Alaptérkép sora a valódi letöltési méretet mutatja (benne a domborzat-árnyékolással, amíg még nincs a telefonon).": "Descarga de mapas: la línea del Mapa base muestra el tamaño real de descarga (incluido el sombreado del relieve, mientras aún no esté en el teléfono).",
  "Szellemi fegyverek: új, négyperces csatazene a megvalláshoz. Halkan indul, lassan épül fel, a küzdelem után diadalmas résszel zárul, majd elcsendesedik, és hézag nélkül kezdődik újra. Ha a korábbi csatazene le volt töltve, a telefon magától lecseréli az újra.": "«Szellemi fegyverek» (armas espirituales): nueva música de batalla de cuatro minutos para la confesión. Empieza suave, crece despacio, tras la lucha termina con una parte triunfal, luego se calma y vuelve a empezar sin pausa. Si tenías descargada la música de batalla anterior, el teléfono la sustituye sola por la nueva.",
  "Kalkulátorok: a telefon által visszatöltött vagy automatikusan kitöltött mezők már nem keverednek össze. Megnyitáskor a választók és a hozzájuk tartozó mezők összeillenek (a Lámpánál a „Saját megadás (mA)” mező, az Áramnál a kézi megadás bolt-link nélkül), és a régi eredmény eltűnik, ha egy adatot módosítasz. A Tájoló mért légnyomás-mezője nem indul 300-zal.": "Calculadoras: los campos restaurados por el teléfono o rellenados automáticamente ya no se mezclan. Al abrir, los selectores y sus campos coinciden (en Lámpara, el campo «Valor propio (mA)», y en Electricidad, la entrada manual sin enlace a la tienda), y el resultado antiguo desaparece si cambias un dato. El campo de presión atmosférica medida de Orientación no empieza en 300.",
  "Kalkulátorok: negatív, nulla vagy képtelen értékre (Menetidő, Esővíz, Fűtés, Víztisztítás, Kalória, Mit vigyek, Lámpa, Rádió) rövid, érthető üzenet jelenik meg a csendes vagy furcsa eredmény helyett.": "Calculadoras: ante un valor negativo, cero o imposible (Tiempo de marcha, Agua de lluvia, Calefacción, Potabilización del agua, Calorías, Qué llevo, Lámpara, Radio) aparece un mensaje breve y comprensible en lugar de un resultado vacío o extraño.",
  "Tudástár kereső: ékezet nélkül és kis-nagybetűtől függetlenül is talál („tuz”, „viz”, „ELELMISZER”), a hosszú keresőszó pedig nem lóg ki a képernyőről.": "Buscador de la Base de conocimientos: encuentra también sin acentos y sin distinguir mayúsculas y minúsculas («tuz», «viz», «ELELMISZER»), y una palabra de búsqueda larga no se sale de la pantalla.",
  "Térkép kereső: a magyar települések is kereshetők (például Maglód, Eger), internet nélkül is; a találatra koppintva a térkép odaugrik.": "Buscador del mapa: también se pueden buscar las localidades húngaras (por ejemplo, Maglód, Eger), también sin internet; al tocar el resultado, el mapa salta allí.",
  "Titkos QR: túl hosszú szövegnél érthető üzenet jelenik meg, és az előző QR-kód eltűnik.": "QR secreto: con un texto demasiado largo aparece un mensaje comprensible, y el código QR anterior desaparece.",
  "Nyelvek: a Háztartás számlálói ukránul és oroszul is helyes alakban állnak, nyelvváltás után nem marad régi nyelvű felirat (Háztartás címe, iránytű betűi, Tudástár témái), és orosz nyelven a levágott feliratok kiférnek.": "Idiomas: los contadores de Hogar aparecen con la forma correcta también en ucraniano y ruso, tras cambiar de idioma no queda ningún texto en el idioma anterior (título de Hogar, letras de la brújula, temas de la Base de conocimientos), y en ruso los textos que se cortaban ahora caben.",
  "Éjszakai (piros) mód: a kezdőlap és a Kockázat gyűrűi, a Készlet lejárat-jelzései és gombja, a térkép jelölője, keresője és gombjai, valamint a Lámpa is pirosra vált; a Mit vigyek kijelölt személye pipát kap.": "Modo nocturno (rojo): los anillos del inicio y de Riesgo, las marcas de caducidad y el botón de Reservas, el marcador, el buscador y los botones del mapa, y también la Lámpara pasan a rojo; en Qué llevo, la persona seleccionada recibe una marca.",
  "Felolvasás a telefon internetes hangjával: a várakozási idő beállítása most már tényleg eljut a Google hangmotorhoz.": "Lectura en voz alta con la voz de internet del teléfono: el ajuste del tiempo de espera llega ahora de verdad al motor de voz de Google.",
  "Internetes szobák: a szobalista azonnal megjelenik. A telefon megjegyzi a legutóbb látott listát, és megnyitáskor rögtön azt mutatja, a frissítés a háttérben érkezik. A szobák képe külön, egyszer töltődik le, és utána a telefonról jön, ezért a lista töredék adatforgalommal frissül (négy szobánál kb. 250 kB helyett 1 kB alatt). Ha a szerver épp nem válaszol, a lista akkor is látszik, és egy elakadt kapcsolat sem tartja a „Betöltés...” feliratot a végtelenségig.": "Salas por internet: la lista de salas aparece al instante. El teléfono recuerda la última lista vista y la muestra enseguida al abrir, mientras la actualización llega en segundo plano. Las imágenes de las salas se descargan por separado, una vez, y después salen del teléfono, así que la lista se actualiza con una fracción del tráfico de datos (con cuatro salas, menos de 1 kB en lugar de unos 250 kB). Si el servidor no responde en ese momento, la lista se ve igualmente, y una conexión atascada no mantiene el texto «Cargando...» indefinidamente.",
  "Értesítések: egy már látott vagy már jelzett szobaüzenetről a telefon nem küld újra értesítést, frissítés vagy újraindulás után sem.": "Notificaciones: el teléfono no vuelve a notificar un mensaje de sala ya visto o ya notificado, tampoco tras una actualización o un reinicio.",
  "Biblia felolvasás, PrepperPapa hang: a Biblia beállításaiban választható, melyik felvétel olvasson: Imre (gépi, a teljes Biblia) vagy Charon (új, jobb minőségű férfihang). A Charon-felvétel könyvenként érkezik: csak az elkészült könyvek tölthetők le, a többit addig Imre olvassa fel. A két felvétel letöltése külön marad. Alapból továbbra is Imre szól.": "Lectura en voz alta de la Biblia, voz PrepperPapa: en los ajustes de la Biblia puedes elegir qué grabación lee: Imre (sintética, toda la Biblia) o Charon (nueva voz masculina de mejor calidad). La grabación de Charon llega libro a libro: solo se pueden descargar los libros terminados, y los demás los lee Imre mientras tanto. Las descargas de las dos grabaciones siguen separadas. Por defecto sigue sonando Imre.",
  "Térkép, offline letöltés: a Térkép-funkciók panel „Offline térkép” csoportjában elöl a saját országod áll (a felület nyelve szerint, angolnál a telefon országbeállítása szerint), tájegységenként. Minden tájegységnél három külön sor van: Alaptérkép, Turistautak és Turistapontok; mindegyik külön tölthető le és külön törölhető. Az alaptérkép törlése már nem viszi el a külön letöltött turistautakat és pontokat. Magyarország tájegységeinél is így van.": "Mapa, descarga sin conexión: en el grupo «Mapa sin conexión» del panel Funciones del mapa, primero aparece tu propio país (según el idioma de la interfaz, y en inglés según la configuración de país del teléfono), por regiones. En cada región hay tres líneas separadas: Mapa base, Rutas de senderismo y Puntos de senderismo; cada una se descarga y se borra por separado. Borrar el mapa base ya no se lleva los senderos y puntos descargados aparte. También es así en las regiones de Hungría.",
  "Más országok térképei: a „Külföldi térképek” helyett. A listában csak az országok állnak, egy koppintással lenyílnak, és benne ugyanaz a három sor van az egész országra és a tájegységeire. A telefonos appban a lenyíló tájegységek eddig nem jelentek meg, ez is javítva.": "Mapas de otros países: en lugar de «Mapas extranjeros». En la lista solo están los países, que se despliegan con un toque, y dentro están las mismas tres líneas para todo el país y para sus regiones. En la app del teléfono, las regiones desplegables no aparecían hasta ahora; esto también está corregido.",
  "Szellemi fegyverek: a megvallást mostantól új, jobb minőségű férfihang olvassa fel, normál és lassú tempóban is.": "«Szellemi fegyverek» (armas espirituales): la confesión la lee ahora una nueva voz masculina de mejor calidad, a ritmo normal y lento.",
  "Biblia felolvasás, a telefon hangja internettel: a felolvasó most ugyanúgy kéri a Google internetes hangját, mint a Google saját könyvolvasója (a nyelv szerint, a Google választja ki a hangot), így ritkábban esik vissza a letöltött hangra.": "Lectura en voz alta de la Biblia, voz del teléfono con internet: el lector pide ahora la voz de internet de Google igual que el propio lector de libros de Google (según el idioma, y Google elige la voz), así que pasa con menos frecuencia a la voz descargada.",
  "Biblia felolvasás, a telefon hangja internettel: a Google jobb, internetes hangja mostantól a hosszú verseknél és imáknál is megszólal. Eddig a hosszú szövegre a Google szervere nem válaszolt időben, és a telefon szó nélkül a letöltött, gyengébb hangra váltott. Most a felolvasó rövid, mondatnyi részekben adja át a szöveget; a kiemelés, a szünet a versek között, a megállítás és a folytatás ugyanúgy működik.": "Lectura en voz alta de la Biblia, voz del teléfono con internet: la voz de internet de Google, mejor, suena ahora también en versículos y oraciones largos. Hasta ahora, con textos largos el servidor de Google no respondía a tiempo, y el teléfono pasaba sin avisar a la voz descargada, peor. Ahora el lector entrega el texto en partes cortas, de una frase; el resaltado, la pausa entre versículos, la pausa y la reanudación funcionan igual.",
  "Vissza gomb: a telefon Vissza gombja mostantól ugyanoda lép, mint a képernyő bal felső nyila (például a Számológépből a Kalkulátorokhoz, a Háztartás űrlapjából a listához). A Kezdőn a Vissza nem lépked vissza a korábbi képernyőkön, hanem a háttérbe teszi az appot. A Visszajelzés lapot és a súgót a Vissza bezárja, a mögötte lévő képernyő nem mozdul.": "Botón Atrás: el botón Atrás del teléfono va ahora al mismo sitio que la flecha superior izquierda de la pantalla (por ejemplo, de la Calculadora a Calculadoras, del formulario de Hogar a la lista). En Inicio, Atrás no recorre las pantallas anteriores, sino que pasa la app a segundo plano. Atrás cierra la página de Comentarios y la ayuda, y la pantalla de detrás no se mueve.",
  "Akkumulátor: az app a Kezdőn és a legtöbb képernyőn már nem kér folyamatosan pontos GPS-helyzetet. Folyamatosan csak a nyitott Térkép kéri; a légnyomás-riasztás ritkán vesz mintát, riasztás előtt pedig egy frisset, hogy autóban ne riasszon.": "Batería: en Inicio y en la mayoría de las pantallas la app ya no pide continuamente la posición GPS exacta. Solo la pide continuamente el Mapa abierto; la alarma de presión atmosférica toma muestras pocas veces, y antes de avisar toma una nueva, para no dar la alarma en un coche.",
  "Súgó: a Kockázat, a Beállítások, a Készlet és az SOS súgója a képernyőkhöz igazodik. A Kockázat-gyűrűn a szám az átlag, a színe a leggyengébb terület; az SOS súgója az esés utáni automatikus SOS-t is bemutatja; a „Mi hiányzik?” azt sorolja, ami hiányzik vagy kevés.": "Ayuda: la ayuda de Riesgo, Ajustes, Reservas y SOS se ajusta a las pantallas. En el anillo de Riesgo, el número es la media y el color el área más débil; la ayuda del SOS presenta también el SOS automático tras una caída; ¿Qué falta? enumera lo que falta o es escaso.",
  "Eszközök szoba az interneten át: ha az eszközök sürgős riasztást küldenek (például élesített riasztónál kinyílik az ajtó), a telefonod akkor is felébred, ha nem vagy a helyi szoba közelében, sőt akkor is, ha az app be van zárva. Ugyanaz a teljes képernyős RIASZTÁS jelenik meg, mint a helyi szobában: mi történt, mikor, melyik eszköz és melyik szoba, riasztó hangon, amíg meg nem nyomod a Láttam vagy a Megnyitom gombot.": "Sala Herramientas a través de internet: si los dispositivos envían una alarma urgente (por ejemplo, se abre la puerta con la alarma armada), tu teléfono se despierta aunque no estés cerca de la sala local, e incluso con la app cerrada. Aparece la misma ALARMA a pantalla completa que en la sala local: qué ha pasado, cuándo, qué dispositivo y qué sala, con sonido de alarma, hasta que pulses el botón Visto o Abrir.",
  "Térkép, offline letöltés: a térkép jobb alsó gombjával nyíló Térkép-funkciók panelen az „Offline térkép” csoport mostantól mindig látszik. Benne Magyarország tájegységei egyenként letölthetők, fölöttük a „Külföld: országok és tájegységeik” gomb nyitja meg az országok listáját, a nagyobb országoknál lenyíló tájegységekkel. Eddig a csoport kis képernyőn vagy nagyobb betűmérettel lecsúszott a panelről.": "Mapa, descarga sin conexión: en el panel Funciones del mapa, que se abre con el botón inferior derecho del mapa, el grupo «Mapa sin conexión» se ve ahora siempre. En él, las regiones de Hungría se descargan una a una, y encima el botón «Extranjero: países y sus regiones» abre la lista de países, con regiones desplegables en los países grandes. Hasta ahora, en pantallas pequeñas o con letra grande, el grupo se salía del panel.",
  "Biblia, jegyzetek: a Scofield-jegyzet forrás-sorában „saját fordítás”, a mértékegység-csomagéban „saját összeállítás” áll, mind a nyolc nyelven.": "Biblia, notas: en la línea de la fuente de la Nota de Scofield figura «traducción propia», y en la del paquete de unidades de medida «recopilación propia», en los ocho idiomas.",
  "Biblia, keresés: a keresett szót mostantól a szavak elején keresi, ékezettől függetlenül, a ragozott alakokkal együtt (például a „gíra” megtalálja a „gírát”, „gírád” alakokat, az „efa” az „éfát”, de nem a „figefát”). A „sékel” a Károli „siklus”, a „talentum” a „tálentom” szavát is megtalálja. A találati listában és a megnyitott fejezetben a megtalált szó félkövér.": "Biblia, búsqueda: la palabra buscada se busca ahora al principio de las palabras, sin importar los acentos y con sus formas flexionadas (por ejemplo, «gíra» encuentra «gírát» y «gírád», y «efa» encuentra «éfát», pero no «figefát»). «Sékel» también encuentra la palabra «siklus» de la Károli, y «talentum» también «tálentom». En la lista de resultados y en el capítulo abierto, la palabra encontrada aparece en negrita.",
  "Biblia, jegyzetek: a Scofield-jegyzet jele mostantól egy kis nyitott könyv, a mértékegységeké marad az „i”. Ha egy vershez mindkettő tartozik, a két jel egymás mellett áll, és mindegyik a saját jegyzeteit nyitja meg.": "Biblia, notas: el símbolo de la Nota de Scofield es ahora un pequeño libro abierto, y el de las unidades de medida sigue siendo la «i». Si un versículo tiene los dos, los dos símbolos aparecen uno al lado del otro, y cada uno abre sus propias notas.",
  "Biblia, Énok könyvei: a forrás-sorban a fordítás megjelölése mostantól „saját fordítás”, ugyanúgy, mint az apokrif könyveknél.": "Biblia, libros de Enoc: en la línea de la fuente, la traducción figura ahora como «traducción propia», igual que en los libros apócrifos.",
  "Biblia, apokrif könyvek: az Apokrif könyvek sávban egy csempével letölthetők a deuterokanonikus könyvek (Tóbiás, Judit, Bölcsesség, Sirák fia, Báruk, Makkabeusok, Eszter és Dániel kiegészítései), 1–2 Ezdrás, Manassé imája, 3–4 Makkabeus, a 151. zsoltár, a pszeudepigráfák (Jubileumok, 12 pátriárka, Ésaiás mennybemenetele, 2 Báruk, Salamon zsoltárai és ódái, Ábrahám apokalipszise) és a Didakhé meg Hermász pásztora, a Biblia nyelvén elérhető kiadásban. Letöltés után internet nélkül is olvashatók, kereshetők és felolvashatók; a valódi fejezet- és versszám látszik (például Dániel 3,24), és minden könyvnél ott a forrása.": "Biblia, libros apócrifos: en la barra de libros apócrifos, con un mosaico se descargan los libros deuterocanónicos (Tobías, Judit, Sabiduría, Eclesiástico, Baruc, Macabeos, adiciones a Ester y Daniel), 1-2 Esdras, la Oración de Manasés, 3-4 Macabeos, el Salmo 151, los pseudoepígrafos (Jubileos, los Doce Patriarcas, la Ascensión de Isaías, 2 Baruc, los Salmos y las Odas de Salomón, el Apocalipsis de Abraham) y la Didaché y el Pastor de Hermas, en la edición disponible en el idioma de la Biblia. Tras descargarlos se pueden leer, buscar y escuchar también sin internet; se ve el número real de capítulo y versículo (por ejemplo, Daniel 3:24), y cada libro indica su fuente.",
  "Frissítés: a telefonos app mostantól úgy telepíti a frissítést, hogy a Biblia-ébresztő teljes képernyős engedélye megmaradjon. Ez a mostanit követő frissítéstől hat. Ha egy frissítés mégis kikapcsolná, az app egy értesítéssel szól, és egy koppintással a beállításhoz visz.": "Actualización: la app del teléfono instala ahora la actualización de forma que se conserve el permiso de pantalla completa de la alarma bíblica. Esto se aplica a partir de la actualización siguiente a esta. Si una actualización aun así lo desactivara, la app avisa con una notificación y con un toque te lleva al ajuste.",
  "Biblia, ukrán fordítás: az ukrán Biblia mostantól Kulis, Puljuj és Nyecsuj-Levickij közkincs fordítása (1903–1905), a korábbi Ohijenko-fordítás helyett. Aki az ukrán Bibliát már letöltötte, annak frissítéskor magától lecserélődik, a jelölései (kiemelés, kommentár, könyvjelző) átkerülnek a megfelelő versekre. A zsoltárok számozása mostantól a héber (Károlival egyező) számozás.": "Biblia, traducción ucraniana: la Biblia ucraniana es ahora la traducción de dominio público de Kulish, Puliui y Nechui-Levytskyi (1903-1905), en lugar de la anterior traducción de Ohiienko. Si ya habías descargado la Biblia ucraniana, se sustituye sola al actualizar, y tus marcas (subrayados, comentarios, marcadores) pasan a los versículos correspondientes. La numeración de los salmos es ahora la hebrea (igual que la Károli).",
  "Biblia, jegyzetek az igék mellett: megjelent a Scofield-jegyzet (Scofield Reference Notes, 1917, saját fordítás) mind a nyolc nyelven, 2544 jegyzet könyvbevezetőkkel. A Biblia beállításaiban tölthető le, a mértékegység-csomag mellett.": "Biblia, notas junto a los versículos: ha llegado la Nota de Scofield (Scofield Reference Notes, 1917, traducción propia) en los ocho idiomas, 2544 notas con introducciones a los libros. Se descarga en los ajustes de la Biblia, junto al paquete de unidades de medida.",
  "Biblia, jegyzetek az igék mellett: ahol egy vershez jegyzet tartozik, egy kis jel áll mellette, rákoppintva megnyílnak a vers jegyzetei fajtánként, a forrással együtt. Az első csomag a bibliai mértékegységek mai értéke (könyök, éfa, siklus, talentum, dénár, órák): centiméterben, literben, kilogrammban, a pénz napszámban. Mind a nyolc Bibliához külön csomag van, a saját versszámozásával; a Biblia beállításaiban tölthető le, utána internet nélkül is megvan, és fajtánként ki-be kapcsolható.": "Biblia, notas junto a los versículos: donde un versículo tiene una nota, aparece un pequeño símbolo al lado; al tocarlo se abren las notas del versículo por tipo, con su fuente. El primer paquete es el valor actual de las unidades de medida bíblicas (codo, efa, siclo, talento, denario, horas): en centímetros, litros y kilogramos, y el dinero en jornales. Hay un paquete aparte para cada una de las ocho Biblias, con su propia numeración de versículos; se descarga en los ajustes de la Biblia, después está disponible también sin internet, y se activa y desactiva por tipo.",
  "Térkép, Világhelyzet: a háború jele csak a valódi háborúkat mutatja (évi ezer halott fölött). A kisebb fegyveres konfliktusok, felkelések, terrorizmus és szervezett bűnözés új, halványabb jelet kaptak: „Fegyveres összecsapás / instabilitás”. Az érintett, de nem harcoló országok (például akik csak részt vesznek egy háborúban) nem kapnak külön jelet, a hírekből jövő helyszínek pedig országonként egy jelként, csak ott látszanak, ahol újat mutatnak. Afrika fölött a háború-jelek száma 45-ről 11-re csökkent.": "Mapa, Situación mundial: el símbolo de guerra solo muestra las guerras reales (más de mil muertes al año). Los conflictos armados menores, las insurrecciones, el terrorismo y el crimen organizado tienen un símbolo nuevo, más tenue: «Enfrentamientos armados / inestabilidad». Los países afectados pero que no combaten (por ejemplo, los que solo participan en una guerra) no reciben un símbolo propio, y los lugares procedentes de las noticias aparecen como un símbolo por país, solo donde muestran algo nuevo. Sobre África, el número de símbolos de guerra ha bajado de 45 a 11.",
  "Térkép, Tűzgyújtási tilalom: távolról egyetlen jel mutatja Magyarországon, rákoppintva a tilalommal érintett megyék listájával. A megyénkénti narancs terület közelítve, megye-szinten jelenik meg, koppintásra a részletekkel, mint eddig.": "Mapa, Prohibición de hacer fuego: de lejos, un solo símbolo la muestra en Hungría y, al tocarlo, la lista de condados afectados. Al acercarse, la zona naranja por condado aparece a nivel de condado y, al tocarla, con los detalles, como hasta ahora.",
  "Térkép, új réteg: Világhelyzet. A rétegválasztóban bekapcsolva távolról ikonok jelzik a földrengéseket, erdőtüzeket, árvizeket, ciklonokat, vulkánkitöréseket, járványokat, háborús övezeteket és a magyar tűzgyújtási tilalmat; közelítve az érintett terület körvonallal és fátyollal látszik. Koppintásra rövid leírás, forrás és időpont. Óránként frissül, internet nélkül a legutóbbi állapot látszik.": "Mapa, nueva capa: Situación mundial. Al activarla en el selector de capas, de lejos unos iconos señalan terremotos, incendios forestales, inundaciones, ciclones, erupciones volcánicas, epidemias, zonas de guerra y la prohibición húngara de hacer fuego; al acercarse, la zona afectada se ve con contorno y velo. Al tocar, una breve descripción, la fuente y la hora. Se actualiza cada hora, y sin internet se ve el último estado.",
  "Térkép, új réteg: Tűzveszély-előrejelzés (EFFIS). Ez veszély-index, nem tilalom; csak internettel látszik.": "Mapa, nueva capa: Previsión de peligro de incendio (EFFIS). Es un índice de peligro, no una prohibición; solo se ve con internet.",
  "Kezdőlap, készültség-csempék: minden csempe a saját helyszínének adatlapját nyitja meg. Eddig bármelyikre koppintva (például a Lakókocsira) a legutóbb megnyitott helyszín, többnyire az otthon jelent meg.": "Inicio, mosaicos de preparación: cada mosaico abre la ficha de su propio lugar. Hasta ahora, al tocar cualquiera (por ejemplo, Caravana) aparecía el último lugar abierto, casi siempre la casa.",
  "Eszközök szoba, eszköz adatlap: a jelenléti listában az eszközre (például az áramtárolóra) koppintva megnyílik az adatlapja: jelez-e, töltöttség, mikor jelzett utoljára, és hogy a panelről vagy a felhőből jön. Alul a Helyszín választóval megadhatod, hol van (például a lakókocsiban); ez ugyanoda kerül, mint a Kockázatelemzésben.": "Sala Herramientas, ficha del dispositivo: en la lista de presencia, al tocar un dispositivo (por ejemplo, la batería portátil) se abre su ficha: si da señal, la carga, cuándo dio señal por última vez y si la información viene del panel o de la nube. Abajo, con el selector de Ubicación puedes indicar dónde está (por ejemplo, en la caravana); se guarda en el mismo sitio que en el Análisis de riesgos.",
  "Kockázatelemzés, helyszín adatlap: új „Eszköz hozzárendelése” gomb. Felsorolja az ismert eszközöket, koppintásra az eszköz ehhez a helyszínhez kerül; ami már itt van, arra koppintva lekerül. Ha még nincs eszköz-adat, a lista azt kéri, hogy egyszer nyisd meg az Eszközök szobát.": "Análisis de riesgos, ficha del lugar: nuevo botón «Asignar dispositivo». Enumera los dispositivos conocidos; al tocar uno, pasa a este lugar, y al tocar uno que ya está aquí, se quita. Si aún no hay datos de dispositivos, la lista te pide que abras una vez la sala Herramientas.",
  "Ha a panel egy korábban látott eszközt épp nem küld, az nem tűnik el a listából: szürkén, „nem jelez” felirattal marad, az utolsó ismert töltöttségével, és a helyszínhez rendelése megmarad.": "Si el panel no está enviando en ese momento un dispositivo visto antes, este no desaparece de la lista: se queda en gris, con el texto «sin señal», con su última carga conocida, y su asignación al lugar se mantiene.",
  "Térkép, külföld országonként: az országok a választott nyelven és annak ábécérendjében látszanak. Minden országnál külön tölthetők le a turistautak a pontokkal és az útvonaltervezővel (ezek az online térképen is működnek, és kevés helyet foglalnak), és külön az alaptérkép a térerő nélküli használathoz.": "Mapa, extranjero por países: los países aparecen en el idioma elegido y en su orden alfabético. En cada país se descargan por separado los senderos con los puntos y el planificador de rutas (funcionan también en el mapa en línea y ocupan poco espacio), y por separado el mapa base, para usarlo sin cobertura.",
  "Térkép, tájegységek: a nagyobb országok (például Németország, Franciaország, Olaszország) alatt lenyíló listában tájegységenként is letölthető az alaptérkép, így a túl nagy országok is használhatók offline.": "Mapa, regiones: en la lista desplegable bajo los países grandes (por ejemplo, Alemania, Francia, Italia), el mapa base también se descarga por regiones, así que los países demasiado grandes también se pueden usar sin conexión.",
  "Kockázatelemzés, eszközök a helyszíneken: a helyszínek alatt az Eszközök részben a panel és a Tuya-eszközök (például az áramtároló) utolsó ismert állapota látszik, és mindegyiknél kiválaszthatod, melyik helyszínen van (lakókocsi, nyaraló). A helyszín csempéjén látszik, hány eszköze jelez, az adatlapján pedig eszközönként a zöld vagy szürke pont, a töltöttség és hogy utoljára mikor jelzett. Az állapotot az app az Eszközök szoba megnyitásakor frissíti.": "Análisis de riesgos, equipo en los lugares: bajo los lugares, en la sección Herramientas, se ve el último estado conocido del panel y de los dispositivos Tuya (por ejemplo, la batería portátil), y en cada uno puedes elegir en qué lugar está (caravana, casa de vacaciones). En el mosaico del lugar se ve cuántos de sus dispositivos dan señal, y en su ficha, por dispositivo, el punto verde o gris, la carga y cuándo dio señal por última vez. La app actualiza el estado al abrir la sala Herramientas.",
  "Készültség, áramtároló: ha egy helyszínhez áramtároló van rendelve (például PowerMax 2400 Pro), a mért töltöttségéből kiszámolja, hány órára elég áramszünetben (alapból 50 W átlagos fogyasztással: hűtő, világítás, telefontöltés; a helyszín adatlapján átírható). Ez adja a helyszín Áram sávját, és beleszámít a készültség százalékába. Ha a kapacitása nem ismert, az adatlapon megadhatod wattórában.": "Preparación, batería portátil: si un lugar tiene asignada una batería portátil (por ejemplo, PowerMax 2400 Pro), a partir de su carga medida calcula para cuántas horas alcanza durante un apagón (por defecto con un consumo medio de 50 W: frigorífico, iluminación, carga de teléfonos; se puede cambiar en la ficha del lugar). Esto da la barra de Electricidad del lugar y cuenta en el porcentaje de preparación. Si no se conoce su capacidad, puedes indicarla en vatios hora en la ficha.",
  "Noah, Biblia: a saját szavaiddal feltett kérdésre is megtalálja az igét, akkor is, ha a Károli-fordítás más szavakkal mondja (például „Hol van megírva, hogy ne aggódjunk a holnapért?” -> Máté 6,34). Ha a hely nem szó szerint egyezik, „talán erre gondolsz” jelzéssel mutatja. A „Nézd meg jobban” vagy „Keress tovább” kérésre alaposabban, több találattal keres újra.": "Noah, Biblia: encuentra el versículo también cuando preguntas con tus propias palabras, aunque la traducción Károli lo diga con otras palabras (por ejemplo, «¿Dónde está escrito que no nos afanemos por el mañana?» -> Mateo 6:34). Si el pasaje no coincide literalmente, lo muestra con la indicación «quizá te refieres a esto». Si le pides «Míralo mejor» o «Busca más», vuelve a buscar más a fondo y con más resultados.",
  "Noah, készlet: a „Mi járt le?” kérdésre a lejárt tételeket sorolja (név, darab, dátum, helyszín), utána azokat, amelyek 30 napon belül lejárnak; ha semmi nem járt le, ezt mondja, és megadja a következő lejáratokat. A készlet összesítője külön írja a tételek számát és a darabszámot.": "Noah, reservas: a la pregunta «¿Qué ha caducado?» enumera los artículos caducados (nombre, cantidad, fecha, lugar) y después los que caducan en los próximos 30 días; si no ha caducado nada, lo dice e indica las próximas caducidades. El resumen de reservas indica por separado el número de artículos y el número de unidades.",
  "Eszközök a szobában: a felhőből olvasott eszköz (pl. a PowerMax áramtároló, amit a panel negyedóránként kérdez le) a neve mellett mutatja az akkumulátor töltöttségét (pl. 88%) és egy kis „felhő” jelzést. Zöld marad, ha az utolsó jelzése 20 percen belüli volt (a többi eszköznél 10 perc).": "Dispositivos en la sala: un dispositivo leído desde la nube (por ejemplo, la batería portátil PowerMax, que el panel consulta cada cuarto de hora) muestra junto a su nombre la carga de la batería (por ejemplo, 88%) y una pequeña marca de «nube». Se queda en verde si su última señal fue hace menos de 20 minutos (para los demás dispositivos, 10 minutos).",
  "Megvallások, felolvasás: a hangjegy-panel megvallás közben a megvallás beállításait mutatja (Tempó Normál/Lassú, Szünet a mondatok után, és hogy most melyik hang olvas: a PrepperPapa hang vagy a telefon hangja), ugyanazt, ami a szöveg alatt van. A 0 másodperces szünet valóban szünet nélkül olvas, és a beállítás felolvasás közben, a következő mondattól hat. A Tempó váltása is azonnal hat: a PrepperPapa hangnál a lassabban felolvasott felvételre vált, a telefon hangjánál lassabban beszél.": "Confesiones, lectura en voz alta: durante una confesión, el panel de la nota musical muestra los ajustes de la confesión (Ritmo Normal/Lento, Pausa tras cada frase, y qué voz lee ahora: la voz PrepperPapa o la voz del teléfono), lo mismo que hay bajo el texto. La pausa de 0 segundos lee de verdad sin pausa, y el ajuste se aplica durante la lectura, a partir de la frase siguiente. El cambio de Ritmo también se aplica al instante: con la voz PrepperPapa pasa a la grabación leída más despacio, y con la voz del teléfono habla más despacio.",
  "Megvallások, csatazene: új, valóban végtelenített változat (nem egy erős nyitással indul újra). Ha a régit letöltötted, az app magától lecseréli az újra (kb. 17 MB, internet kell hozzá); ha a régi volt kiválasztva, az új lesz az.": "Confesiones, música de batalla: nueva versión de verdad en bucle (no vuelve a empezar con una entrada fuerte). Si descargaste la antigua, la app la sustituye sola por la nueva (unos 17 MB, hace falta internet); si estaba elegida la antigua, pasa a estarlo la nueva.",
  "Androidos alkalmazás, a telefon hangja: ha van internet, a felolvasás a Google legjobb minőségű (internetes) magyar hangjával szól. Internet nélkül, vagy ha az internetes hang elakad, magától a telefonra letöltött hangra vált, a felolvasás nem áll meg. A lejátszó hangjegy-paneljén választhatsz a hangok közül (pl. „Google 1 (jobb, internet)”, „Google 2 (letöltött)”); a telefon megjegyzi.": "App de Android, voz del teléfono: si hay internet, la lectura en voz alta suena con la voz húngara de mejor calidad de Google (por internet). Sin internet, o si la voz de internet se atasca, pasa sola a la voz descargada en el teléfono y la lectura no se detiene. En el panel de la nota musical del reproductor puedes elegir entre las voces (por ejemplo, «Google 1 (mejor, internet)», «Google 2 (descargada)»); el teléfono lo recuerda.",
  "Megvallások, Lassú tempó: a Szellemi fegyverek felvétele most valóban lassabban van felolvasva (külön, lassú felolvasás), nem a normál hang lelassítva, ezért nem torzít. A Normál tempó a régi felvétel tempója. A PrepperPapa hangot az app sehol nem gyorsítja és nem lassítja; a sebesség-csúszka a telefon hangjára hat.": "Confesiones, ritmo Lento: «Szellemi fegyverek felvétele» (vestirse con la armadura espiritual) se lee ahora de verdad más despacio (una lectura lenta aparte), no con la voz normal ralentizada, así que no se distorsiona. El ritmo Normal es el de la grabación anterior. La app no acelera ni ralentiza la voz PrepperPapa en ninguna parte; el control de velocidad afecta a la voz del teléfono.",
  "iPhone-os alkalmazás: a Lámpa LED-je most a kamera bekapcsolása nélkül világít, ahogy az Androidos alkalmazásban is. A böngészős változatban ez nem változott.": "App de iPhone: el LED de la Lámpara ahora se enciende sin activar la cámara, como en la app de Android. En la versión de navegador esto no ha cambiado.",
  "A háttérzenét most ott választod és töltöd le, ahol szól: az ébresztőnél (két zene), a Biblia lejátszójában felolvasás közben a hangjegy gombbal (három epikus zene) és a Megvallásoknál (új csatazene). A Biblia beállításaiból a közös Háttérzene rész kikerült. A méret a letöltés előtt látszik.": "La música de fondo se elige y se descarga ahora donde suena: en la alarma (dos músicas), en el reproductor de la Biblia durante la lectura con el botón de la nota musical (tres músicas épicas) y en Confesiones (nueva música de batalla). Se ha quitado la sección común de Música de fondo de los ajustes de la Biblia. El tamaño se ve antes de descargar.",
  "Megvallások: a felolvasás mondatonként halad, és minden mondat után megáll, hogy hangosan elismételhesd. A szünetet te állítod (0-10 másodperc, vagy Auto: annyi, amennyi a mondat felolvasása), alapból 3 másodperc; a tempó Lassú vagy Normál, alapból Lassú. A zene a szünetekben is szól. A Szellemi fegyverek felvétele mondatonként újra felolvasva.": "Confesiones: la lectura avanza frase a frase y se detiene tras cada frase para que puedas repetirla en voz alta. La pausa la ajustas tú (0-10 segundos, o Auto: lo que dura la lectura de la frase), por defecto 3 segundos; el ritmo es Lento o Normal, por defecto Lento. La música suena también en las pausas. «Szellemi fegyverek felvétele» se ha vuelto a grabar frase a frase.",
  "Felolvasó hang a lejátszóban: a Biblia felolvasása közben a hangjegy gomb paneljén választhatsz a telefon hangja (a gomb kiírja, ha a Google hangja szól) és a PrepperPapa hang között. Az app alapból a telefon hangjára áll; a PrepperPapa hang egy koppintással visszakapcsolható.": "Voz de lectura en el reproductor: durante la lectura de la Biblia, en el panel del botón de la nota musical puedes elegir entre la voz del teléfono (el botón indica si suena la voz de Google) y la voz PrepperPapa. La app usa por defecto la voz del teléfono; la voz PrepperPapa se vuelve a activar con un toque.",
  "Felolvasás kikapcsolt képernyővel: a Biblia felolvasása (a telefon hangjával és a PrepperPapa hanggal is) most akkor is folytatódik, ha a képernyő kikapcsol vagy lezárod a telefont. Eddig néhány vers után elhallgatott, csak a zene szólt tovább, és a következő megnyitáskor indult újra. Az app most egyszerre kb. 45 percnyi szöveget ad át a telefon felolvasójának; amikor újra ránézel, a kiemelés oda ugrik, ahol a felolvasás éppen tart.": "Lectura en voz alta con la pantalla apagada: la lectura de la Biblia (con la voz del teléfono y con la voz PrepperPapa) continúa ahora aunque la pantalla se apague o bloquees el teléfono. Hasta ahora se callaba tras unos versículos, solo seguía sonando la música, y volvía a empezar en la siguiente apertura. La app entrega ahora de una vez al lector del teléfono unos 45 minutos de texto; cuando vuelves a mirar, el resaltado salta al punto por donde va la lectura.",
  "Az értesítési sáv lejátszójának Szünet, Folytatás és Leállítás gombja lezárt képernyőn is azonnal hat, a zenével együtt. Ha a felolvasás a képernyő kikapcsolt állapotában ér a végére, a zene is leáll.": "Los botones Pausa, Continuar y Detener del reproductor de la barra de notificaciones actúan al instante también con la pantalla bloqueada, junto con la música. Si la lectura termina con la pantalla apagada, la música también se detiene.",
  "Imák és megvallások felolvasása is folytatódik kikapcsolt képernyővel, és közben a lejátszó az értesítési sávban látszik.": "La lectura de oraciones y confesiones también continúa con la pantalla apagada, y mientras tanto el reproductor se ve en la barra de notificaciones.",
  "A Google beszédhang: ha a telefonra utólag telepíted a Google magyar hangadatát, a következő felolvasástól az szól, az app újraindítása nélkül.": "La voz de Google: si instalas después en el teléfono los datos de voz húngara de Google, suena esa voz a partir de la siguiente lectura, sin reiniciar la app.",
  "Eszközök szoba: a panel és az eszközei jelenléte most a szoba fő lapján, a fejléc alatt rögzítve látszik: zöld vagy szürke pont, a panelnél az is, hogy él-e. A sor végén a jelző eszközök száma áll; a sávra koppintva lenyílik a teljes lista azzal, hogy melyik eszköz hány perce jelzett utoljára. A sáv nem takarja az üzeneteket, és csak ott jelenik meg, ahol a panel küld jelenlétet. A szoba tagjainál továbbra is megvan ugyanez a lista.": "Sala Herramientas: la presencia del panel y de sus dispositivos se ve ahora fija en la página principal de la sala, bajo la cabecera: punto verde o gris, y en el panel también si está activo. Al final de la línea figura el número de dispositivos que dan señal; al tocar la barra se despliega la lista completa con cuántos minutos hace que cada dispositivo dio señal por última vez. La barra no tapa los mensajes y solo aparece donde el panel envía presencia. En los miembros de la sala sigue estando la misma lista.",
  "Háttérzene a felolvasáshoz: a Biblia beállításaiban (fogaskerék) öt zene tölthető le egyenként, a méretük a letöltés előtt látszik: három epikus zene a Biblia felolvasásához, egy akusztikus gitáros és egy kelta az ébresztőhöz. Letöltés után internet nélkül is szólnak, és hézag nélkül ismétlődnek.": "Música de fondo para la lectura en voz alta: en los ajustes de la Biblia (engranaje) se pueden descargar cinco músicas una a una, y su tamaño se ve antes de descargar: tres músicas épicas para la lectura de la Biblia, y una de guitarra acústica y una celta para la alarma. Tras descargarlas suenan también sin internet y se repiten sin pausa.",
  "A Biblia felolvasása alatt a beállításokban kiválasztott zene halkan szól (kb. 18 dB-lel a beszéd alatt), és a felolvasással együtt áll le. A hangerejét felolvasás közben a hangjegy gombbal állíthatod.": "Durante la lectura de la Biblia, la música elegida en los ajustes suena baja (unos 18 dB por debajo de la voz) y se detiene junto con la lectura. Su volumen se ajusta durante la lectura con el botón de la nota musical.",
  "Ébresztő: a terv ébresztőjénél a Zene sorban kiválasztható a letöltött ébresztő-zene. A felolvasással együtt, halkan indul és együtt erősödik vele, és leáll, amikor az ébresztő véget ér, vagy a Leállítom / Szundi gombot megnyomod.": "Alarma: en la alarma del plan, en la línea Música puedes elegir la música de alarma descargada. Empieza baja junto con la lectura, sube con ella y se detiene cuando termina la alarma o cuando pulsas Detener / Posponer.",
  "Eszközök szoba: a szoba tagjainál (a fejléc pontjára koppintva) új Eszközök rész mutatja, él-e a panel, és mellette minden eszközét zöld vagy szürke ponttal: zöld, ha az elmúlt tíz percben jelzett, mellette az is, hogy utoljára hány perce. Az internetes és a helyi (bluetooth) szobában is működik, amint a panel új szoftvere küldi az életjelet; addig a lista nem változik.": "Sala Herramientas: en los miembros de la sala (tocando el punto de la cabecera), una nueva sección Herramientas muestra si el panel está activo y, a su lado, cada uno de sus dispositivos con un punto verde o gris: verde si ha dado señal en los últimos diez minutos, y al lado también cuántos minutos hace de la última. Funciona en la sala por internet y en la local (Bluetooth) en cuanto el nuevo software del panel envía la señal de vida; hasta entonces la lista no cambia.",
  "Helyi szoba, társgazda: ha a panel a szoba gazdája, és téged társgazdává tett, a telefonod nem készít saját kulcsot és nem osztja ki, így a szoba kulcsa nem válhat ketté. A belépési kérelmeket ugyanúgy beengedheted vagy elutasíthatod; a szoba törlése a panelnél marad.": "Sala local, coanfitrión: si el panel es el anfitrión de la sala y te ha hecho coanfitrión, tu teléfono no crea ni reparte una clave propia, así que la clave de la sala no puede dividirse en dos. Puedes admitir o rechazar las solicitudes de entrada igual que antes; el borrado de la sala sigue en manos del panel.",
  "Bibliaolvasási ébresztő: a felolvasás most a teljes napi szakaszt végigolvassa, akkor is, ha közben az app a háttérbe kerül (eddig előfordult, hogy az első vers után megállt). A végén elhangzik az „Áldott napot kívánok!”, és az ébresztő magától leáll; az értesítés Leállítom és Szundi gombja azonnal elhallgattatja.": "Alarma de lectura bíblica: la lectura en voz alta lee ahora entero el pasaje del día, aunque mientras tanto la app pase a segundo plano (antes a veces se detenía tras el primer versículo). Al final suena «¡Que tengas un día bendecido!» y la alarma se detiene sola; los botones Detener y Posponer de la notificación la silencian al instante.",
  "Androidon a felolvasás a Google beszédmotorját használja, ha telepítve van és van hozzá letöltött magyar (vagy az app nyelvén elérhető) hang; a legjobb minőségű, internet nélkül is működő hangot választja. Ha nincs ilyen, marad a telefon saját felolvasója. A hangot a Beállítások → Szövegfelolvasás → Google → Hangadatok telepítése menüben lehet letölteni.": "En Android, la lectura en voz alta usa el motor de voz de Google si está instalado y tiene descargada una voz húngara (o en el idioma de la app); elige la voz de mejor calidad que funciona también sin internet. Si no la hay, se usa el lector propio del teléfono. La voz se descarga en Ajustes → Texto a voz → Google → Instalar datos de voz.",
  "Szobák: a szoba gazdája eltávolíthat egy tagot. A szoba beállításaiban A szoba tagjai alatt (vagy a fejléc pontjára koppintva) koppints a tagra, majd az Eltávolítás gombra; az app előbb rákérdez. Saját magadat nem tudod eltávolítani.": "Salas: el anfitrión de la sala puede eliminar a un miembro. En los ajustes de la sala, en Miembros de la sala (o tocando el punto de la cabecera), toca el miembro y después el botón Eliminar; la app pide confirmación antes. No puedes eliminarte a ti mismo.",
  "Akit eltávolítottak, annál a szoba bezárul, és megjelenik: „A szoba gazdája eltávolított a szobából.” Ha épp nem volt bent, a Szobák listán szól egyszer. Új üzenetet a szobából már nem kap, a régi meghívóval és a szoba kódjával nem jöhet vissza, csak egy új meghívóval.": "A quien han eliminado se le cierra la sala y aparece: «El anfitrión de la sala te ha eliminado de la sala.» Si en ese momento no estaba dentro, se le avisa una vez en la lista de Salas. Ya no recibe mensajes nuevos de la sala, y no puede volver con la invitación antigua ni con el código de la sala, solo con una invitación nueva.",
  "Kezdőlap: a készültség-kártyákon a „4 fő · 30 nap” sor nem vágódik le kétjegyű vagy háromjegyű napszámnál sem. Ha a teljes szöveg nem fér ki (főleg háromjegyű napszámnál vagy más nyelven), az app rövidebb alakot ír ki, például „120 n.”, és mindig egy sorban marad.": "Inicio: en las tarjetas de preparación, la línea «4 personas · 30 días» no se corta tampoco con números de días de dos o tres cifras. Si el texto completo no cabe (sobre todo con tres cifras o en otro idioma), la app escribe una forma más corta, por ejemplo «120 d», y siempre se queda en una línea.",
  "Túrán visszafordulási ébresztő: a Kalkulátor Menetidő lapján a Túra indítása kapcsolóval élesítheted. Az app a helyzeted szerinti napnyugtából (vagy a szürkület végéből) kivonja a visszaút idejét és egy biztonsági tartalékot (alapból 30 perc), és megmutatja, mikor kell visszafordulnod. Az időpontot kézzel is átállíthatod.": "Alarma de regreso en excursiones: en la página Tiempo de marcha de la Calculadora la armas con el interruptor Iniciar ruta. La app resta a la puesta de sol según tu posición (o al final del crepúsculo) el tiempo de vuelta y un margen de seguridad (por defecto 30 minutos), y te muestra cuándo debes dar la vuelta. También puedes cambiar la hora a mano.",
  "A visszafordulás percében a telefon felébred, lezárt képernyőn is teljes képernyőn mutatja, mennyi idő van sötétedésig és mennyi a visszaút, és riasztó hangon szól, amíg meg nem nyomod a Láttam gombot. A Visszaút indítása gomb a túra kiindulópontjához tervez utat és elindítja a navigációt; ha nincs turistaút-adat, a tájoló mutatja az irányt.": "En el minuto del regreso el teléfono se despierta, muestra a pantalla completa, también con la pantalla bloqueada, cuánto falta para que oscurezca y cuánto dura la vuelta, y suena con tono de alarma hasta que pulses el botón Visto. El botón Iniciar la vuelta planifica una ruta al punto de partida de la excursión e inicia la navegación; si no hay datos de senderos, la brújula indica la dirección.",
  "A visszaút idejét a Menetidő számításából vagy a térképen tervezett útvonalból egy gombbal kitöltheted. Ugyanazzal a kapcsolóval ki is kapcsolhatod. Böngészőben és iPhone-on csak akkor szól, ha az oldal nyitva van; a lezárt telefont az Android app ébreszti fel.": "El tiempo de vuelta lo puedes rellenar con un botón a partir del cálculo de Tiempo de marcha o de la ruta planificada en el mapa. Con el mismo interruptor también la desactivas. En el navegador y en iPhone solo suena si la página está abierta; el teléfono bloqueado lo despierta la app de Android.",
  "Eszközök szoba: ha az eszközök sürgős riasztást küldenek, például élesített riasztónál kinyílik az ajtó, a telefonod felébred, és lezárt képernyőn is teljes képernyőn mutatja, mi történt, mikor és melyik szobában, riasztó hangon szól, amíg meg nem nyomod a Láttam vagy a Megnyitom gombot.": "Sala Herramientas: si los dispositivos envían una alarma urgente, por ejemplo se abre la puerta con la alarma armada, tu teléfono se despierta y muestra a pantalla completa, también con la pantalla bloqueada, qué ha pasado, cuándo y en qué sala, y suena con tono de alarma hasta que pulses el botón Visto o Abrir.",
  "A nem sürgős eszköz-üzenetek, például a napi összegzés vagy az ajtónyitás élesítés nélkül, továbbra is sima értesítések. Ugyanaz a riasztás csak egyszer szól, a régi üzenetek újracsatlakozáskor nem szólnak újra.": "Los mensajes de dispositivos no urgentes, por ejemplo el resumen diario o la apertura de la puerta sin la alarma armada, siguen siendo notificaciones normales. La misma alarma solo suena una vez, y los mensajes antiguos no vuelven a sonar al reconectarse.",
  "Szobák, SOS: ha egy szobatársad SOS-t küld (például az esés-érzékelés automatikus SOS-ét), a telefonod felébred, lezárt képernyőn is teljes képernyőn mutatja, ki küldte, mikor, melyik szobából és honnan, ha a helyzete benne van, és riasztó hangon szól, amíg meg nem nyomod a Megnyitom vagy a Láttam gombot. A Megnyitom a szobát nyitja meg, a helyzetet a térképen is megnézheted.": "Salas, SOS: si un compañero de sala envía un SOS (por ejemplo, el SOS automático de la detección de caídas), tu teléfono se despierta y muestra a pantalla completa, también con la pantalla bloqueada, quién lo envió, cuándo, desde qué sala y desde dónde, si incluye su posición, y suena con tono de alarma hasta que pulses el botón Abrir o Visto. Abrir abre la sala, y la posición también la puedes ver en el mapa.",
  "Internetes szobánál ez akkor is működik, ha az app be van zárva; helyi szobánál (Bluetooth vagy wifi, internet nélkül) akkor, ha az app a háttérben fut. Csak a vészjelzés ébreszt: a sima és a sürgős üzenet továbbra is sima értesítés, a saját SOS-od pedig a te telefonodon nem szól.": "En una sala por internet esto funciona aunque la app esté cerrada; en una sala local (Bluetooth o wifi, sin internet), si la app funciona en segundo plano. Solo despierta la alerta de emergencia: los mensajes normales y urgentes siguen siendo notificaciones normales, y tu propio SOS no suena en tu teléfono.",
  "Az esés-érzékelés SOS-e mostantól a helyi szobába is elmegy, ha éppen helyi szobában vagy, nem csak az internetes szobáidba.": "El SOS de la detección de caídas se envía ahora también a la sala local si estás en una sala local en ese momento, no solo a tus salas por internet.",
  "Esés-érzékelés: ha esés után elindul a visszaszámlálás, a telefon felkapcsolja a kijelzőt, és lezárt telefonon is mutatja a hátralevő másodperceket nagy számokkal, alatta a nagy Jól vagyok gombbal. Nem csak a hangját hallod.": "Detección de caídas: si tras una caída empieza la cuenta atrás, el teléfono enciende la pantalla y, también con el teléfono bloqueado, muestra los segundos restantes con números grandes y debajo el botón grande Estoy bien. Ya no solo se oye.",
  "Az értesítés is visszaszámol, és van rajta Jól vagyok gomb. Ha a telefonod nem engedi a teljes képernyős értesítést, az esés-érzékelés beállításánál ezt kiírja, és egy gombbal engedélyezheted.": "La notificación también hace la cuenta atrás y tiene un botón Estoy bien. Si tu teléfono no permite la notificación a pantalla completa, el ajuste de detección de caídas lo indica y con un botón puedes permitirla.",
  "Biblia, ébresztő: a köszöntés most az időt, a dátumot és a hét napját mondja be, utána a mai olvasmányt; a terv nevét nem. A végén áldott napot kíván. Minden nyelven a saját formájában.": "Biblia, alarma: el saludo dice ahora la hora, la fecha y el día de la semana, y después la lectura de hoy; el nombre del plan, no. Al final te desea un día bendecido. En cada idioma con su propia forma.",
  "Noah, az offline MI segéd mostantól minden tesztelőnek elérhető. Az Android appban a Beállításokban kapcsolható be, a modellt a segéd oldalán, a fogaskerék alatt töltheted le. Letöltés előtt az app megmutatja a modell méretét, a szükséges szabad helyet és memóriát, és ha mobilinterneten vagy, Wi-Fi-t javasol. 6 GB-nál kevesebb memóriájú telefonon Noah nem használható, mert a rendszer válasz közben leállítaná az appot; ezt a segéd oldala ki is írja.": "Noah, el asistente de IA sin conexión, está ahora disponible para todos los probadores. En la app de Android se activa en Ajustes, y el modelo se descarga en la página del asistente, bajo el engranaje. Antes de descargarlo, la app muestra el tamaño del modelo, el espacio libre y la memoria necesarios y, si estás con datos móviles, recomienda Wi-Fi. En teléfonos con menos de 6 GB de memoria Noah no se puede usar, porque el sistema cerraría la app mientras responde; la página del asistente también lo indica.",
  "A böngészős változatban és iPhone-on Noah a Több menüben látszik, és megnyitva elmagyarázza, hogy az Android appban fut, mert ide a modell nem tölthető le.": "En la versión de navegador y en iPhone, Noah aparece en el menú Más y, al abrirlo, explica que funciona en la app de Android, porque aquí no se puede descargar el modelo.",
  "Mai tesztfeladat: naponta egyszer, az első megnyitáskor egy ablak ajánl egy rövid feladatot, ami a te telefonodhoz és felületedhez illik (név nélkül). Mellette pár mondatban az is ott áll, hogyan működik az adott funkció és mit kell látnod. A Működik gomb egy koppintással visszajelez, a Hibás megnyitja a visszajelzés lapot a feladat nevével kitöltve, a Később bezárja mára. Amire már válaszoltál, az nem jön elő újra. A Visszajelzés lapon a Mai tesztfeladat gombbal bármikor újra megnyithatod.": "Tarea de prueba de hoy: una vez al día, en la primera apertura, una ventana propone una tarea breve adecuada a tu teléfono y a tu interfaz (sin nombre). Al lado, en unas frases, explica también cómo funciona esa función y qué deberías ver. El botón Funciona envía la respuesta con un toque, Falla abre la página de comentarios con el nombre de la tarea rellenado, y Más tarde la cierra por hoy. Lo que ya has respondido no vuelve a salir. En la página de Comentarios, con el botón Tarea de prueba de hoy puedes volver a abrirla cuando quieras.",
  "Kalkulátor, súgó: az első lépés a csempék első sorát mutatja, nem az egész rácsot, így a buborék nem takarja el a középső csempéket.": "Calculadora, ayuda: el primer paso señala la primera fila de mosaicos, no toda la cuadrícula, así que la burbuja no tapa los mosaicos del centro.",
  "Helyi szoba (eszközök panele): a később megérkező régebbi üzenetek az időrendben a helyükre kerülnek, nem a lista végére; újranyitáskor a panel csak a hiányzó üzeneteket küldi.": "Sala local (panel de dispositivos): los mensajes más antiguos que llegan más tarde se colocan en su lugar por orden cronológico, no al final de la lista; al volver a abrir, el panel solo envía los mensajes que faltan.",
  "Biblia, olvasási terv, ébresztő: a be- és kikapcsolás csúszkás kapcsoló lett, a napok egyforma körök, az időpontot pedig az app saját időválasztója állítja be (óra és perc nagy plusz-mínusz gombokkal, Mégse és Kész).": "Biblia, plan de lectura, alarma: la activación y desactivación es ahora un interruptor deslizante, los días son círculos iguales, y la hora se ajusta con el selector de hora propio de la app (hora y minuto con botones grandes de más y menos, Cancelar y Hecho).",
  "Az ébresztő felolvasása halkan indul, és az első bő fél percben fokozatosan erősödik. Előtte egy rövid köszöntés elmondja, melyik tervből mi a mai olvasmány, a végén pedig áldott napot kíván, mindig az app nyelvén.": "La lectura de la alarma empieza baja y sube poco a poco durante el primer medio minuto largo. Antes, un breve saludo dice cuál es la lectura de hoy y de qué plan, y al final te desea un día bendecido, siempre en el idioma de la app.",
  "Amíg az ébresztő olvas, a képernyő alján egy nagy Leállítom gomb van; egy koppintással azonnal leállítja. A sima felolvasásnál ez a gomb nem jelenik meg. Az értesítésen a gomb neve is Leállítom lett.": "Mientras la alarma lee, al pie de la pantalla hay un botón grande Detener; con un toque la detiene al instante. En la lectura en voz alta normal este botón no aparece. En la notificación, el botón también se llama ahora Detener.",
  "Biblia: a könyvcsoportok csempéi ugyanazokkal a zöld árnyalatokkal, de váltakozó világos-sötét sorrendben, így a szomszédos csoportok jobban elválnak.": "Biblia: los mosaicos de los grupos de libros, con los mismos tonos verdes, pero en un orden alterno claro y oscuro, así que los grupos vecinos se distinguen mejor.",
  "Javítás: a lenyíló lista (például a Rádió-hatótáv sávválasztója) nem marad nyitva a következő képernyő fölött. A vissza gomb nyitott listánál csak a listát zárja be.": "Corrección: la lista desplegable (por ejemplo, el selector de banda de Alcance de radio) no se queda abierta sobre la pantalla siguiente. Con una lista abierta, el botón Atrás solo cierra la lista.",
  "Biblia, olvasási terv: ébresztő. A futó terv oldalán bekapcsolhatsz egy ébresztőt, megadhatod az időpontot és a napokat (alapból minden nap), és látod, mikor szól legközelebb. Az Android appban az ébresztő a megadott időben felébreszti a telefont, a lezárt képernyő fölött megnyitja a terv aznapi olvasmányát, elkezdi felolvasni, és amíg olvas, a kijelző nem alszik el. Az értesítésen Szundi (10 perc) és Leállítás gomb van. Első használatkor az app engedélyt kér az értesítéshez; ha a pontos időzítés vagy a teljes képernyős megjelenés nincs engedélyezve, a beállításnál egy gombbal megnyitható a hozzá tartozó telefon-beállítás. A böngészőben és iPhone-on az ébresztő nem tud megszólalni, ezt a beállításnál ki is írja.": "Biblia, plan de lectura: alarma. En la página del plan en curso puedes activar una alarma, indicar la hora y los días (por defecto todos los días) y ver cuándo sonará la próxima vez. En la app de Android, a la hora indicada la alarma despierta el teléfono, abre sobre la pantalla bloqueada la lectura del día del plan, empieza a leerla en voz alta, y mientras lee la pantalla no se apaga. La notificación tiene los botones Posponer (10 minutos) y Detener. La primera vez, la app pide permiso para las notificaciones; si la programación exacta o la visualización a pantalla completa no están permitidas, en el ajuste un botón abre el ajuste correspondiente del teléfono. En el navegador y en iPhone la alarma no puede sonar, y el ajuste también lo indica.",
  "Szobák, privát üzenet: a „Csak neki” üzenet most már akkor is elmegy, ha a címzett egy másik telefonról, saját fiókkal van a szobában (eddig ilyenkor „Az üzenet nem ment el” jelent meg). A „Csak neki” sáv nem takarja el a legutolsó üzenetet, az mindig fölötte látszik. Ha egy üzenet mégsem megy el, az app megmondja, miért: nincs internet, a címzett már nem tagja a szobának, túl hosszú, vagy a szerver hibát jelzett. A beírt szöveg ilyenkor megmarad.": "Salas, mensaje privado: el mensaje «Solo a» se envía ahora también cuando el destinatario está en la sala desde otro teléfono, con su propia cuenta (hasta ahora aparecía «El mensaje no se ha enviado»). La barra «Solo a» no tapa el último mensaje, que siempre se ve por encima. Si un mensaje aun así no se envía, la app dice por qué: no hay internet, el destinatario ya no es miembro de la sala, es demasiado largo o el servidor ha dado error. El texto escrito se conserva en ese caso.",
  "Súgó-bemutató: a magyarázó buborék Tovább és Kihagyom gombja már nem csúszik le az alsó menüsávra vagy a telefon saját gombjai alá, így mindig kényelmesen megnyomható. Ha a megmutatott rész nagy (például a Helyi szoba üzenetei vagy a Kalkulátor csempéi), a buborék a rész alján jelenik meg, és nem takarja el az első sort. A Helyi szobában a „Ha nem talál senkit” lépés a beíró sorra mutat, nem az egész üzenetlistára.": "Presentación de la ayuda: los botones Siguiente y Lo omito de la burbuja explicativa ya no se meten bajo la barra de menú inferior ni bajo los botones propios del teléfono, así que siempre se pulsan cómodamente. Si la parte mostrada es grande (por ejemplo, los mensajes de la Sala local o los mosaicos de la Calculadora), la burbuja aparece al pie de esa parte y no tapa la primera línea. En la Sala local, el paso «Si no encuentra a nadie» señala la línea de escritura, no toda la lista de mensajes.",
  "Biblia, olvasási terv: ha a tervből megnyitod a napi olvasmányt, csak az aznapi fejezetek látszanak, és nem lehet továbbgörgetni a Biblia többi részébe. Az olvasmány végén egy jelzés áll, ahonnan egy koppintással visszamehetsz a tervhez, vagy elolvasottnak jelölheted a napot. A felolvasás is az olvasmány utolsó versénél megáll. A Biblia szokásos olvasása nem változott.": "Biblia, plan de lectura: si abres la lectura del día desde el plan, solo se ven los capítulos de ese día y no se puede seguir desplazando al resto de la Biblia. Al final de la lectura hay una marca desde la que, con un toque, puedes volver al plan o marcar el día como leído. La lectura en voz alta también se detiene en el último versículo de la lectura. La lectura habitual de la Biblia no ha cambiado.",
  "Vagyon, Nemesfém: minden tételnél az összeg alatt látszik a fém és a súly is (például „ezüst · 1000 g”), akkor is, ha a tétel össze van csukva. A kezdőlap összesítő kártyája nem változott.": "Patrimonio, Metales preciosos: en cada elemento se ven bajo el importe también el metal y el peso (por ejemplo, «plata · 1000 g»), aunque el elemento esté plegado. La tarjeta de resumen del inicio no ha cambiado.",
  "Kalkulátor és Tudástár: görgetéskor, vagy amikor a billentyűzet megjelenik, már nem takarja el sötét sáv a fejléc alatti részt. A Víztisztítás, a Menetidő és a többi számoló, a Számológép, valamint a Tudástár témái és cikkei is rendesen látszanak, és visszalépés után sem marad ott a sáv.": "Calculadora y Base de conocimientos: al desplazarse, o cuando aparece el teclado, una franja oscura ya no tapa la parte bajo la cabecera. Potabilización del agua, Tiempo de marcha y las demás calculadoras, la Calculadora numérica, y los temas y artículos de la Base de conocimientos se ven bien, y la franja tampoco se queda al volver atrás.",
  "Kalkulátor, első megnyitás: a rövid súgó-buborék görgetésre bezárul, és nem ugrik a képernyő aljára. Ha megnyitsz egy számolót, a buborék eltűnik, így nem takarja a számológép előzmény-sorát.": "Calculadora, primera apertura: la breve burbuja de ayuda se cierra al desplazarse y no salta al pie de la pantalla. Si abres una calculadora, la burbuja desaparece, así que no tapa la línea del historial de la calculadora.",
  "Biblia, keresés: ha a keresőmezőbe koppintasz, a korábbi kereséseid jelennek meg, és egy koppintással újra lefuttathatod őket. Amint gépelni kezdesz, a lista eltűnik.": "Biblia, búsqueda: al tocar el campo de búsqueda aparecen tus búsquedas anteriores, y con un toque puedes volver a lanzarlas. En cuanto empiezas a escribir, la lista desaparece.",
  "Biblia, előzmények: a keresőmező jobb oldalán lévő előzmény-jelre koppintva a legutóbb olvasott igéket látod, fejezetenként egyet, a legfrissebbel kezdve, dátummal (például „ma 20:41” vagy „tegnap 18:05”). Koppintásra az ige kiemelve nyílik meg. Mindkét listát külön lehet törölni.": "Biblia, historial: al tocar el símbolo de historial a la derecha del campo de búsqueda ves los versículos leídos más recientemente, uno por capítulo, empezando por el más reciente, con fecha (por ejemplo, «hoy 20:41» o «ayer 18:05»). Al tocarlo, el versículo se abre resaltado. Las dos listas se pueden borrar por separado.",
  "Biblia, Imák, Megvallások: amíg a Bibliát olvasod, igét keresel, imádkozol vagy a megvallásaidat olvasod, a képernyő nem sötétedik el és nem zár le. Amikor kilépsz a Bibliából, vagy az app a háttérbe kerül, a telefon újra a megszokott módon zár.": "Biblia, Oraciones, Confesiones: mientras lees la Biblia, buscas un versículo, oras o lees tus confesiones, la pantalla no se oscurece ni se bloquea. Cuando sales de la Biblia, o la app pasa a segundo plano, el teléfono vuelve a bloquearse como de costumbre.",
  "Biblia: a vers melletti térkép-jelre koppintva a térkép mindig műholdas nézetben nyílik meg. Amikor visszalépsz, a térkép visszaáll arra a nézetre, amit korábban magadnak választottál.": "Biblia: al tocar el símbolo de mapa junto al versículo, el mapa se abre siempre en vista de satélite. Al volver atrás, el mapa vuelve a la vista que habías elegido antes.",
  "Tájoló: a kamerás nézet a telefon fő hátsó kameráját nyitja meg, nem a széles látószögűt. A választott kamerát az app megjegyzi.": "Orientación: la vista con cámara abre la cámara trasera principal del teléfono, no la gran angular. La app recuerda la cámara elegida.",
  "Lámpa (böngészős változat): ha a vaku nem kapcsolható, vagy nem adsz engedélyt a kamerához, az app azonnal elengedi a kamerát, és nem kéri újra minden koppintásra. A kamera így nem marad bekapcsolva vaku nélkül.": "Lámpara (versión de navegador): si el flash no se puede encender, o no das permiso para la cámara, la app libera la cámara al instante y no lo vuelve a pedir en cada toque. Así la cámara no se queda encendida sin flash.",
  "Kérdezz: a nagy (12B) modell kikerült az appból. Ha korábban letöltötted, az app frissítés után magától törli, és vele a hozzá tartozó ideiglenes fájlokat is, így visszakapod a helyet. Az E4B és az E2B változatlanul megmarad.": "Pregunta: el modelo grande (12B) se ha quitado de la app. Si lo habías descargado, la app lo borra sola tras la actualización, junto con sus archivos temporales, así que recuperas el espacio. E4B y E2B se mantienen sin cambios.",
  "Kérdezz: ha az app egy modell futása közben váratlanul bezáródott, a segéd beállításaiban egy sor megmondja, miért (például memóriahiány).": "Pregunta: si la app se cerró inesperadamente mientras funcionaba un modelo, una línea en los ajustes del asistente dice por qué (por ejemplo, falta de memoria).",
  "Útvonaltervezés: messzi célhoz (például Budapestről a Kékesre) is tervez. Eddig a kezdőponthoz legközelebbi, sehová nem csatlakozó turistaút-darabra tette az indulást, és azt írta, hogy nem talált útvonalat. Most a célig összefüggő turistaút-hálózat legközelebbi pontjáról indul, és kiírja, milyen messze van az légvonalban.": "Planificación de rutas: planifica también hacia destinos lejanos (por ejemplo, de Budapest al Kékes). Hasta ahora ponía la salida en el tramo de sendero más cercano al punto de partida, que no conectaba con nada, y decía que no había encontrado ruta. Ahora sale del punto más cercano de la red de senderos conectada con el destino, e indica a qué distancia en línea recta está.",
  "Kérdezz: a nagyobb (12B) modell a 12 GB memóriájú telefonokon is választható (kísérleti). Ha egy modell egy telefonon nem választható, a listában ott áll, hány GB-os telefon kell hozzá, és hány GB-os ez.": "Pregunta: el modelo más grande (12B) también se puede elegir en teléfonos con 12 GB de memoria (experimental). Si un modelo no se puede elegir en un teléfono, la lista indica cuántos GB necesita el teléfono y cuántos tiene este.",
  "Szobák: az értesítés kapcsolója frissítés után is a valódi beállítást mutatja. Eddig az app frissítése után kikapcsoltnak látszott, és ha rákoppintottál, akkor ténylegesen kikapcsolt.": "Salas: el interruptor de notificaciones muestra el ajuste real también tras una actualización. Hasta ahora, tras actualizar la app parecía desactivado, y si lo tocabas, se desactivaba de verdad.",
  "Saját térkép: a letöltött tájegységen nagy nagyításnál nem maradnak szürke foltok és fehér négyzetek. A térkép csak azokat a rétegeket rajzolja, amelyek a látott területre esnek, így a telefon memóriája elég az egész képernyőhöz.": "Mapa propio: en la región descargada, con mucho zoom ya no quedan manchas grises ni cuadrados blancos. El mapa solo dibuja las capas que caen en la zona visible, así que la memoria del teléfono alcanza para toda la pantalla.",
  "Tájoló: amikor az irány ráfordul a felvett irányra (a zöld háromszögre), a telefon egyet rezzen. Csak a ráfordulás pillanatában jelez, a kis remegésre nem ismétli; ha kikapcsoltad a rezgést a beállításokban, akkor itt sem rezeg.": "Orientación: cuando la dirección coincide con la dirección registrada (el triángulo verde), el teléfono vibra una vez. Solo avisa en el momento de coincidir, no se repite con pequeños temblores; si desactivaste la vibración en los ajustes, aquí tampoco vibra.",
  "Nincs többé Mentés gomb: amit beírsz, magától elmentődik (Rólam, készlet-adatlap, családtagok, háziállatok, helyszínek, saját ima és megvallás, rajzos jegyzet, igehely-kommentár, a neved a szobákban, a szoba nyelve). Ahol a gomb maradt, ott „Kész” lett belőle, és csak bezár.": "Ya no hay botón Guardar: lo que escribes se guarda solo (Sobre mí, ficha de reservas, familiares, mascotas, lugares, oración y confesión propias, nota dibujada, comentario del versículo, tu nombre en las salas, el idioma de la sala). Donde quedaba el botón, ahora es «Hecho» y solo cierra.",
  "Javítva: a kötelező frissítés nem ragad be többé a „mentsd el, amit írsz” csíknál, ha minden el van mentve.": "Corregido: la actualización obligatoria ya no se queda atascada en la barra «guarda lo que escribes» cuando todo está guardado.",
  "A térkép gyorsabb: csak a képernyő környékén lévő, épp látható turistautakat rajzolja, így nagyításkor és mozgatáskor kevesebbet számol.": "El mapa es más rápido: solo dibuja los senderos visibles en ese momento cerca de la pantalla, así que calcula menos al ampliar y mover.",
  "Turistautak távolról: az Alföldön sem tűnnek el. Közepes távolságból a regionális utak is látszanak, egy lépéssel közelebbről pedig minden legalább 10 km-es út is; csak a rövid helyi körök jönnek elő később.": "Senderos de lejos: tampoco desaparecen en la Gran Llanura. Desde una distancia media se ven también los caminos regionales, y un paso más cerca todos los caminos de al menos 10 km; solo los circuitos locales cortos aparecen más tarde.",
  "Felolvasás: a hosszú, saját megvallások és imák is végig felolvashatók a telefon hangjával. Eddig egy hosszú bekezdésnél a felolvasás el sem indult; most a szöveg kisebb darabokban szól, a kiemelés ugyanúgy követi.": "Lectura en voz alta: las confesiones y oraciones propias largas también se pueden leer enteras con la voz del teléfono. Hasta ahora, con un párrafo largo la lectura ni siquiera empezaba; ahora el texto suena en trozos más pequeños y el resaltado lo sigue igual.",
  "Turistautak a térképen: egy nagyítással távolabbról is minden jelzett út látszik; ennél távolabbról csak a nagy, hosszú távú utak (Országos Kéktúra, a Kékkör szakaszai, Camino, Mária-út, európai utak), hogy a térkép ne legyen zsúfolt.": "Senderos en el mapa: todos los caminos señalizados se ven también un nivel de zoom más lejos; desde más lejos solo los caminos grandes de larga distancia (Országos Kéktúra, los tramos del Kékkör, Camino, Mária-út, senderos europeos), para que el mapa no se sature.",
  "Felolvasás közben a hangjegy gomb és a stop gomb most egyforma méretű, és egy vonalban áll.": "Durante la lectura en voz alta, el botón de la nota musical y el botón de stop tienen ahora el mismo tamaño y están alineados.",
  "A tesztidőszakban a frissítés kötelező, de nem veszi el, amit épp írsz: ha egy mezőben félbehagyott szöveg van, a frissítés megvárja, amíg elmented vagy bezárod, és a felső sáv szól, hogy ezt várja.": "Durante el periodo de prueba la actualización es obligatoria, pero no te quita lo que estás escribiendo: si en un campo hay texto a medias, la actualización espera a que lo guardes o lo cierres, y la barra superior avisa de que está esperando.",
  "Ha a frissítés letöltése nem sikerül, a régi verzióval még 30 percig tovább dolgozhatsz, nem zár ki az app.": "Si la descarga de la actualización falla, puedes seguir trabajando con la versión antigua 30 minutos más; la app no te bloquea.",
  "Felolvasás közben új hangjegy gomb: egy áttetsző panelen egy helyen, csúszkával állítható a versek közötti szünet, a felolvasás sebessége és a zene hangereje.": "Nuevo botón de la nota musical durante la lectura en voz alta: en un panel translúcido, en un solo lugar y con controles deslizantes, se ajustan la pausa entre versículos, la velocidad de lectura y el volumen de la música.",
  "Zene a felolvasás alá: a panelen a telefonodról választhatsz zenét, az app maga játssza le, saját hangerővel. A felolvasás közbeni -/+ gombok helyett ez a panel van; a dupla koppintásos görgetésnél a -/+ megmaradt.": "Música durante la lectura: en el panel puedes elegir música de tu teléfono, y la app la reproduce ella misma, con su propio volumen. En lugar de los botones -/+ durante la lectura está este panel; en el desplazamiento con doble toque se mantienen los -/+.",
  "Felolvasás: a telefon hangja már nem mondja ki a kereszthivatkozás-jelet és a jelölő ikonokat.": "Lectura en voz alta: la voz del teléfono ya no pronuncia el símbolo de referencia cruzada ni los iconos de marcas.",
  "Zene a felolvasás alatt: a zenelejátszó most lehalkul, amíg a felolvasás szól (akkor is, ha a Zene gombbal később indítod), és a felolvasás a média-hangerőt követi.": "Música durante la lectura: el reproductor de música baja ahora el volumen mientras suena la lectura (también si lo inicias más tarde con el botón Música), y la lectura sigue el volumen multimedia.",
  "Felolvasás az imáknál és a megvallásoknál is (ugyanaz a hangszóró-gomb, mint a Bibliánál), kiemeléssel és görgetéssel.": "Lectura en voz alta también en las oraciones y las confesiones (el mismo botón de altavoz que en la Biblia), con resaltado y desplazamiento.",
  "Felolvasás közben állítható a sebesség (0,7×–1,2×), és a Zene gombbal a telefon zenelejátszója szólhat alatta.": "Durante la lectura en voz alta se puede ajustar la velocidad (0,7×-1,2×), y con el botón Música puede sonar debajo el reproductor de música del teléfono.",
  "Vészkártya: a családtagnál bepipálható, hogy az én adataim jelenjenek meg; a szobanév és a profilkép ugyanitt szerkeszthető.": "Tarjeta de emergencia: en el familiar se puede marcar que aparezcan mis datos; el nombre en las salas y la foto de perfil se editan en el mismo sitio.",
  "A Bibliában, az Apokrif könyvek között mindhárom Énok-könyv letölthető: magyarul saját fordításban (az első könyv a görög szöveggel is összevetve, a harmadik közvetlenül héberből), angolul is.": "En la Biblia, entre los libros apócrifos, se pueden descargar los tres libros de Enoc: en húngaro, en traducción propia (el primer libro cotejado también con el texto griego, el tercero traducido directamente del hebreo), y también en inglés.",
  "Esés után csak a szaggatott vészsíp szól, a vaku nem villog, hogy a telefon tovább bírja, amíg segítség érkezik.": "Tras una caída solo suena el silbato de emergencia intermitente y el flash no parpadea, para que el teléfono aguante más hasta que llegue ayuda.",
  "Nem magyar nyelvű felületen nem jelenik meg a magyar hangos Biblia letöltése (a beállítás és a letöltött hang megmarad).": "En la interfaz en otros idiomas no aparece la descarga de la Biblia hablada en húngaro (el ajuste y la voz descargada se conservan).",
  "Esés után a szabványos szaggatott vészsíp szól, és a vaku SOS-t villog. Az értesítésből le lehet állítani, és a riasztást a „Jól vagyok” gombbal az app megnyitása nélkül is le lehet mondani.": "Tras una caída suena el silbato de emergencia intermitente estándar y el flash parpadea SOS. Se puede detener desde la notificación, y la alarma se puede cancelar con el botón «Estoy bien» sin abrir la app.",
  "A piros gombokon fehér a felirat (éjszakai módban marad a sötét).": "En los botones rojos el texto es blanco (en modo nocturno sigue siendo oscuro).",
  "Esés-riasztás: csak akkor riaszt, ha a telefon előbb zuhant, aztán ütközött. Az asztalra letett vagy leejtett telefon nem okoz többé riasztást.": "Alarma de caída: solo avisa si el teléfono primero cayó y después chocó. Un teléfono dejado sobre la mesa o que se cae ya no provoca una alarma.",
  "Az app ikonján nem jelenik meg többé piros szám a háttérben futó esés-érzékelés vagy helyi szoba miatt.": "En el icono de la app ya no aparece un número rojo por la detección de caídas o la sala local que funcionan en segundo plano.",
  "A hanggenerátor az SOS lapról az Eszközök közé került, saját lapra. A telefonos appban háttérben és kikapcsolt képernyőn is szól, amíg a lapján le nem állítod (vagy az értesítésből).": "El generador de tonos ha pasado de la página SOS a Herramientas, en su propia página. En la app del teléfono suena también en segundo plano y con la pantalla apagada, hasta que lo detengas en su página (o desde la notificación).",
  "A kezdőlap csempéi témakörök szerint rendeződtek: felkészülés, vészhelyzet és terep, tudás és közösség, értékek és iratok.": "Los mosaicos del inicio se han ordenado por temas: preparación, emergencia y terreno, conocimiento y comunidad, bienes y documentos.",
  "Szoba tagjai: egy tagot hosszan nyomva menü nyílik: privát üzenet neki, vagy Gerah küldése (ha neki már van Gerah-azonosítója).": "Miembros de la sala: al mantener pulsado un miembro se abre un menú: enviarle un mensaje privado o enviar Gerah (si ya tiene identificador Gerah).",
  "Az Eszközök csempe új ikont kapott: villáskulcs és csavarhúzó.": "El mosaico Herramientas tiene un nuevo icono: llave inglesa y destornillador.",
  "Tükör: a szelfikamera a legnagyobb felbontásán dolgozik, és nyitáskor már nem villan fel a lejátszó-ikon.": "Espejo: la cámara frontal trabaja a su máxima resolución, y al abrir ya no destella el icono del reproductor.",
  "Új Eszközök csempe a Kalkulátor helyén: benne a Kalkulátorok, a Fémdetektor és az új Tükör.": "Nuevo mosaico Herramientas en lugar de Calculadora: dentro están las Calculadoras, el Detector de metales y el nuevo Espejo.",
  "Tükör: az előlapi kamera teljes képernyőn, körben fehér fénykerettel és maximális kijelző-fényerővel, amíg nyitva van a képernyő nem alszik el. Két ujjal nagyítható. Bezárás az alsó gombbal vagy oldalra söpréssel, ilyenkor a kamera és a fény is kikapcsol.": "Espejo: la cámara frontal a pantalla completa, con un marco de luz blanca alrededor y el brillo de pantalla al máximo; mientras está abierto, la pantalla no se apaga. Se amplía con dos dedos. Se cierra con el botón inferior o deslizando hacia el lado, y entonces se apagan también la cámara y la luz.",
  "Esés-érzékelés (Vészhelyzet lap, alapból kikapcsolva): ha a telefon nagy ütés után egy percig nem mozdul, hangosan visszaszámol, és ha nem nyomod meg a Jól vagyok gombot, SOS-t küld a helyzeteddel. A telefonos appban kikapcsolt képernyőn is figyel.": "Detección de caídas (página Emergencia, desactivada por defecto): si tras un golpe fuerte el teléfono no se mueve durante un minuto, hace una cuenta atrás en voz alta y, si no pulsas el botón Estoy bien, envía un SOS con tu posición. En la app del teléfono vigila también con la pantalla apagada.",
  "Fémkereső (Kalkulátor → Fémkereső): a telefon iránytű-érzékelőjével vasat, acélt, vezetéket keres néhány centiről, pittyegéssel. Csak a telefonos appban működik.": "Detector de metales (Calculadora → Detector de metales): con el sensor de brújula del teléfono busca hierro, acero o cables a unos centímetros, con pitidos. Solo funciona en la app del teléfono.",
  "Térkép: az utcanevek sötétbarnák és jobban olvashatók, és az út közepén futnak, nem mellette.": "Mapa: los nombres de las calles son marrón oscuro y se leen mejor, y van por el centro de la calle, no al lado.",
  "Androidon az alsó menüsor már nem csúszik a telefon gombsora alá (háromgombos navigációnál félig takarásban volt).": "En Android, la barra de menú inferior ya no se mete bajo la barra de botones del teléfono (con la navegación de tres botones quedaba medio tapada).",
  "Térkép: az utak kategóriánként finom pasztell színt kaptak – autópálya rózsaszín, autóút barack, főút vajsárga; az alsóbbrendű utak fehérek maradtak.": "Mapa: las carreteras tienen un suave color pastel según su categoría: autopista rosa, autovía melocotón, carretera principal amarillo mantequilla; las vías secundarias siguen en blanco.",
  "Térkép: a városon kívüli utakat – a mellékutakat és földutakat is – vékony, lakóterület-színű keret szegélyezi, így a világos alapon is jól látszanak.": "Mapa: las carreteras fuera de las ciudades, también las secundarias y los caminos de tierra, llevan un fino borde del color de las zonas urbanas, así que se ven bien también sobre el fondo claro.",
  "Térkép: a Saját térkép tájegységenkénti letöltése a térkép jobb alsó gombja alatt, az „Offline térkép” csoportban található (eddig a teljes képernyős térkép alatt elérhetetlen volt).": "Mapa: la descarga por regiones del Mapa propio está bajo el botón inferior derecho del mapa, en el grupo «Mapa sin conexión» (hasta ahora no se podía acceder a ella desde el mapa a pantalla completa).",
  "Térkép: a Saját térkép turistatérkép-színezést kapott – barna lakóterület, fehér utcák, zöld erdő, sárgás rét és szántó.": "Mapa: el Mapa propio tiene colores de mapa de senderismo: zonas urbanas marrones, calles blancas, bosque verde, prados y campos amarillentos.",
  "Térkép: a domborzat-árnyékolás egy darabban fedi az országot – nincsenek sötét csíkok a tájegységek határán, és a sík terület nem lesz szürke.": "Mapa: el sombreado del relieve cubre el país de una sola pieza: no hay franjas oscuras en los límites de las regiones, y las zonas llanas no quedan grises.",
  "Térkép: a távoli turistaút-adat mindig a friss változat (hálózaton újra letöltődik), offline a tárolt marad.": "Mapa: los datos de senderos remotos son siempre la versión más reciente (con red se vuelven a descargar); sin conexión se mantienen los guardados.",
  "Az alkalmazás csak egy példányban fut – frissítés után sem nyílik meg kétszer.": "La app solo se ejecuta en una instancia: tampoco tras actualizar se abre dos veces.",
  "Térkép: középtávolról (9–10-es nagyítás) a regionális turistautak is látszanak, nem csak az országosak – az Alföldön így nem üres a térkép.": "Mapa: desde una distancia media (zoom 9-10) también se ven los senderos regionales, no solo los nacionales, así que en la Gran Llanura el mapa no queda vacío.",
  "Térkép: a domborzat és a szintvonalak a Saját térképen akkor is látszanak, ha a tájegységet nem töltötted le (hálózaton); offline a letöltött tájegységeken.": "Mapa: el relieve y las curvas de nivel se ven en el Mapa propio aunque no hayas descargado la región (con red); sin conexión, en las regiones descargadas.",
  "Térkép: a kereső mező üveghatású maradt, de sűrűbb, és a felirata világosabb, így világos térképen is olvasható.": "Mapa: el campo de búsqueda sigue con efecto de cristal, pero más denso, y su texto es más claro, así que se lee también sobre un mapa claro.",
  "Térkép: a kereső mező felirata világos térképen is olvasható.": "Mapa: el texto del campo de búsqueda se lee también sobre un mapa claro.",
  "Térkép: a Saját térkép turistatérkép lett – domborzat-árnyékolás és 20 méteres szintvonalak (minden 100 méteres vastagabb, nagyításkor magassági számmal), mind a 11 tájegységre, offline is.": "Mapa: el Mapa propio es ahora un mapa de senderismo: sombreado del relieve y curvas de nivel cada 20 metros (cada 100 metros más gruesas, con la altitud al ampliar), para las 11 regiones, también sin conexión.",
  "Térkép: a már letöltött tájegységekhez a domborzat magától letöltődik, a térképet nem kell újra letölteni.": "Mapa: para las regiones ya descargadas, el relieve se descarga solo; no hay que volver a descargar el mapa.",
  "Frissítés: az app magától letölti az új verziót, és magától feldobja a telefon telepítő ablakát – csak a telefon „Frissítés” gombját kell megnyomni.": "Actualización: la app descarga sola la nueva versión y abre sola la ventana de instalación del teléfono: solo hay que pulsar el botón «Actualizar» del teléfono.",
  "Frissítés: két letöltés többé nem írhatja felül egymást („Probléma van az alkalmazásfájllal” hiba javítva), és egy új verzió már nem zárja ki a régebbit használókat.": "Actualización: dos descargas ya no pueden sobrescribirse entre sí (corregido el error «Hay un problema con el archivo de la aplicación»), y una versión nueva ya no deja fuera a quienes usan una anterior.",
  "Térkép: új réteg a Rétegek menüben – rádióamatőr átjátszók (hívójel, frekvencia, eltolás, CTCSS, mód), egyelőre Európa.": "Mapa: nueva capa en el menú Capas: repetidores de radioaficionado (indicativo, frecuencia, desplazamiento, CTCSS, modo), de momento en Europa.",
  "Térkép: ha elhúzod a térképet, az „Itt vagy” buborék bezárul, és a térkép többé nem ugrik vissza.": "Mapa: si arrastras el mapa, la burbuja «Estás aquí» se cierra y el mapa ya no vuelve de golpe.",
  "Térkép, terület letöltése: az alaptérképnél érthető magyarázat, és egy gomb, ami átvált az offline letölthető Saját térképre.": "Mapa, descarga de zona: en el mapa base, una explicación comprensible y un botón que cambia al Mapa propio descargable sin conexión.",
  "Térkép: egy turistaút kiválasztásakor adatlap jelenik meg – hossz, menetidő, kezdő- és végpont, MTSZ-szám, a jelzés festésének éve, leírás, weboldal, és az út menti források, menedékházak, kilátók.": "Mapa: al elegir un sendero aparece una ficha: longitud, tiempo de marcha, punto de inicio y final, número MTSZ, año de pintado de la señalización, descripción, sitio web, y las fuentes, refugios y miradores a lo largo del camino.",
  "Térkép: egy turistaút vonalára koppintva csak az a szakasz marad a térképen, alatta az adatlappal.": "Mapa: al tocar la línea de un sendero, solo queda en el mapa ese tramo, con la ficha debajo.",
  "Térkép: a külföldi, színjelzés nélküli turistautak a halvány szürke helyett jól látható magentát kapnak, a Via Alpina a saját színét.": "Mapa: los senderos extranjeros sin señal de color tienen un magenta bien visible en lugar del gris tenue, y la Via Alpina su propio color.",
  "Térkép, útvonaltervezés: a tervezés kártyáján már indulás előtt látszik a menetidő, a várható érkezés és a szintdiagram (emelkedés, lejtés).": "Mapa, planificación de rutas: en la tarjeta de planificación se ven ya antes de salir el tiempo de marcha, la llegada prevista y el perfil de altitud (subida, bajada).",
  "A lépéslistában minden szakasz mellett ott a turistajelzés rajza; a jelzés nélküli szakaszokat (utca, földút, ösvény) egy kék szaggatott vonal jelöli, ugyanaz, mint a térképen.": "En la lista de pasos, junto a cada tramo aparece el dibujo de la señal de senderismo; los tramos sin señal (calle, camino de tierra, sendero) se marcan con una línea discontinua azul, la misma que en el mapa.",
  "Ima-stopper: új név, egyetlen gomb (Indítás, futás közben Leállítás, lejárat után Újra), és a csengés ismétlése plusz-mínusszal 1 és 15 másodperc között állítható.": "Temporizador de oración: nuevo nombre, un solo botón (Iniciar, Detener mientras funciona, Otra vez al terminar), y la repetición del timbre se ajusta con más y menos entre 1 y 15 segundos.",
  "Újdonságok és Bejelentéseim ablak: a fejlécben mindig látható bezáró gomb, és a háttérre koppintva is bezárul.": "Ventana de Novedades y de Mis informes: botón de cerrar siempre visible en la cabecera, y también se cierra al tocar el fondo.",
  "Imák, stopper: új csengőhang, mint amikor egy kristálypoharat kanállal megkoccintanak, lassan lecsengve.": "Oraciones, temporizador: nuevo tono de timbre, como cuando se golpea una copa de cristal con una cuchara, que se apaga lentamente.",
  "Tájoló: a hangvezetés gombja az app saját ikonját kapta. Jó irányban lassú a sípolás, minél jobban eltérsz, annál sűrűbb.": "Orientación: el botón de la guía por sonido tiene el icono propio de la app. En la dirección correcta el pitido es lento, y cuanto más te desvías, más seguido.",
  "Tájoló (telepített app, Android): a hangvezetés kikapcsolt képernyővel és háttérben is követi az irányt; értesítésből leállítható.": "Orientación (app instalada, Android): la guía por sonido sigue la dirección también con la pantalla apagada y en segundo plano; se detiene desde la notificación.",
  "A gombok felirata ismét a rendes betűméretű ott, ahol kifér; eddig sok gombon feleslegesen apró volt.": "El texto de los botones vuelve a tener el tamaño de letra normal donde cabe; hasta ahora en muchos botones era innecesariamente pequeño.",
  "Tájoló, hangvezetés: megfordult a hang. Jó irányban mély, kettős sípolás szól; minél jobban eltérsz, annál magasabb.": "Orientación, guía por sonido: el sonido se ha invertido. En la dirección correcta suena un doble pitido grave; cuanto más te desvías, más agudo.",
  "Térkép, útvonaltervezés: a jelzés nélküli szakasz szaggatott vonala kék lett és vastagabb, hogy jobban látszódjon.": "Mapa, planificación de rutas: la línea discontinua de los tramos sin señal es ahora azul y más gruesa, para que se vea mejor.",
  "Térkép, navigáció közben: a kanyar-utasítás alulra került, a „Hol vagyok” gomb mellé; fent szabadon marad a kereső.": "Mapa, durante la navegación: la indicación de giro ha pasado abajo, junto al botón «Dónde estoy»; arriba queda libre el buscador.",
  "Térkép, útvonaltervezés: a GPX és az Indulás gomb a tervezés kártyájába került, a Törlés mellé.": "Mapa, planificación de rutas: los botones GPX e Iniciar han pasado a la tarjeta de planificación, junto a Borrar.",
  "Imák: a stopper csengője a fejlécbe került, a fogaskerék mellé.": "Oraciones: el timbre del temporizador ha pasado a la cabecera, junto al engranaje.",
  // Ujdonsagok v43.466 (2026-11-09)
  "Imaszoba: új Imakérések rész: mások kéréseiért imádkozhatsz, és saját imakérést küldhetsz be; az idegen nyelvű kéréseket a telefon a saját nyelvedre fordítja, az eredeti egy koppintással látható.": "Sala de oración: nueva sección Peticiones de oración: ora por las peticiones de otros y envía la tuya; el teléfono traduce a tu idioma las peticiones escritas en otro idioma, y el original está a un toque.",
  "Imaszoba: áttekinthetőbb kezdőlap; a vezetett ima egész évre szóló sorozatból jön, minden napra saját imával, a választott nyelven.": "Sala de oración: página de inicio más clara; la oración guiada viene ahora de una serie para todo el año, con una oración propia para cada día, en el idioma elegido.",
  "Biblia: a jegyzetek, kiemelések, könyvjelzők és a többi Biblia-adat titkosítva szinkronizálható a készülékeid és a két app között; a Beállításokban kapcsolható be.": "Biblia: las notas, los resaltados, los marcadores y el resto de tus datos bíblicos se pueden sincronizar, cifrados, entre tus dispositivos y las dos apps; se activa en Ajustes.",
  "Biblia: névtelen olvasási és ima-statisztika, alapból kikapcsolva; a Beállításokban kapcsolható be.": "Biblia: estadística anónima de lectura y oración, desactivada por defecto; se activa en Ajustes.",
  "Biblia: több vers is kijelölhető a versszámra koppintva, és a kijelölés együtt kiemelhető vagy megosztható; újabb koppintás leveszi a kijelölést.": "Biblia: se pueden seleccionar varios versículos tocando su número y resaltar o compartir toda la selección; un segundo toque la quita.",
  "Biblia: a fejezetválasztó görgetve a következő könyvvel folytatódik.": "Biblia: el selector de capítulos continúa con el libro siguiente al desplazarse.",
  "Biblia: a jegyzetablak a szövegtől külön, lebegő ablakban nyílik, saját ablakgombokkal.": "Biblia: la ventana de notas se abre aparte del texto, como ventana flotante con sus propios botones.",
  "Biblia: tableten és laptopon fekvő helyzetben tömör könyv-, fejezet- és versválasztó; a Strong-ablak szélesebb margót kapott.": "Biblia: en tableta y portátil, en horizontal, un selector compacto de libro, capítulo y versículo; la ventana Strong tiene márgenes más anchos.",
  "Biblia: a Prófécia- vagy Vészhelyzet-listából megnyitott versből a Vissza gomb ugyanarra a helyre visz vissza a listában.": "Biblia: Atrás desde un versículo abierto en la lista de Profecías o de Emergencia vuelve al mismo punto de la lista.",
  "Biblia: szövegjavítások a Luther 1912, a Reina-Valera, a Biblia 1914 és a Károli fordításban (elírások és versfelosztás).": "Biblia: correcciones de texto en Luther 1912, Reina-Valera, Biblia 1914 y Károli (erratas y división de versículos).",
  "Igetanuló: az igekártyák tintatakarékosak, kétoldalas nyomtatásra készülnek, és „Wordlight Biblia” felirat áll rajtuk.": "Aprender versículos: las tarjetas ahorran tinta, están hechas para imprimir a doble cara y llevan el rótulo «Wordlight Biblia».",
  "Helyi szoba: az értesítés szobánként kikapcsolható.": "Sala local: las notificaciones se pueden desactivar por sala.",
  "Beállítások: hét csoportba rendezve, képjelekkel.": "Ajustes: ordenados en siete grupos con pictogramas.",
  "Wordlight tableten és laptopon: személyes irányítópult világtérképpel és oldalsávval; álló helyzetben egy közös statisztika- és világhelyzet-csempe a gombok fölött.": "Wordlight en tableta y portátil: un panel personal con el mapa del mundo y una barra lateral; en vertical, un mosaico común de estadística y situación mundial encima de los botones.",
  "Fordítások: idegen nyelvű felületen nem marad magyar szöveg, az újdonságok teljes listája is le van fordítva.": "Traducciones: en una interfaz en otro idioma ya no queda texto en húngaro, y todo el historial de novedades está traducido.",
  // Ujdonsagok v43.467 (2026-11-09)
  "Megvallások: a Szellemi fegyverek felvétele megvallás mind a 8 nyelven elérhető, a választott nyelven.": "Confesiones: la confesión «Vestirse con la armadura espiritual» está disponible en los 8 idiomas, en el idioma que elijas.",
  "Prémium: a Google Play-en és az App Store-ban vásárolt prémium is 2 készüléken működik, és a Készülékeim listában kezelhető.": "Premium: el premium comprado en Google Play o en la App Store también funciona en 2 dispositivos y se gestiona en Mis dispositivos."
});
