  "Biblia: a (?) súgó minden Biblia-aloldalon az adott oldal saját útmutatóját mutatja.": "Biblia: la ayuda (?) en cada subpágina de la Biblia muestra la guía propia de esa página.",
  "Biblia: a napi olvasási percek csak akkor számítanak, amikor egy bibliai könyv szövege nyitva van, vagy felolvasás közben.": "Biblia: los minutos diarios de lectura solo cuentan mientras está abierto el texto de un libro bíblico, o mientras se lee en voz alta.",
